package com.customrpg.listeners;

import com.customrpg.CustomRPG;
import com.customrpg.managers.FocusManager;
import com.customrpg.managers.TalentManager;
import com.customrpg.players.PlayerTalents;
import com.customrpg.talents.Talent;
import org.bukkit.*;
import org.bukkit.entity.*;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.entity.EntityDamageEvent;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.event.entity.ProjectileHitEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.metadata.FixedMetadataValue;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.util.Vector;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * BowTalentListener — 風獵者之道 弓箭天賦事件處理器
 *
 * 負責：
 * 1. 被動增益應用（靜止傷害、距離傷害、爆頭、連擊、標記）
 * 2. 專注/連擊積累
 * 3. 幻影步伐自動閃避
 * 4. 分裂箭命中效果
 * 5. 緩速箭命中效果
 * 6. 獵人本能周期掃描
 */
public class BowTalentListener implements Listener {

    private final CustomRPG plugin;
    private final FocusManager focusManager;
    private final TalentManager talentManager;

    /** 幻影步伐冷卻 Map<PlayerUUID, lastUsedMs> */
    private final Map<UUID, Long> phantomStepCooldowns = new ConcurrentHashMap<>();

    public BowTalentListener(CustomRPG plugin, FocusManager focusManager, TalentManager talentManager) {
        this.plugin = plugin;
        this.focusManager = focusManager;
        this.talentManager = talentManager;
        startPassiveTasks();
    }

    // ══════════════════════════════════════════════════════
    //  1. 箭矢命中事件 — 被動乘數應用
    // ══════════════════════════════════════════════════════

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onArrowHitEntity(EntityDamageByEntityEvent event) {
        // 只處理「箭矢射手是玩家」的情況
        if (!(event.getDamager() instanceof AbstractArrow arrow)) return;
        if (!(arrow.getShooter() instanceof Player player)) return;
        if (!(event.getEntity() instanceof LivingEntity target)) return;

        // 視覺型箭矢不造成傷害
        if (arrow.hasMetadata("bow_skill_visual")) {
            event.setCancelled(true);
            return;
        }

        PlayerTalents pt = talentManager.getPlayerTalents(player);
        double dmg = event.getDamage();
        double mult = 1.0;

        // ─ 1. 靜止姿態（still_stance）─
        int stillLv = pt.getTalentLevel("still_stance");
        if (stillLv > 0 && focusManager.isStill(player)) {
            Talent t = talentManager.findTalent("still_stance");
            mult += t.getEffectDouble(stillLv, "stillDamageBonus", 0.10);
        }

        // ─ 2. 鷹眼（eagle_eye）：距離加成 ─
        int eagleLv = pt.getTalentLevel("eagle_eye");
        if (eagleLv > 0) {
            Talent t = talentManager.findTalent("eagle_eye");
            double perBlock = t.getEffectDouble(eagleLv, "damagePerBlock", 0.01);
            double maxBonus = t.getEffectDouble(eagleLv, "maxDistanceBonus", 0.30);
            double dist = arrow.getLocation().distance(player.getLocation());
            mult += Math.min(maxBonus, dist * perBlock);
        }

        // ─ 3. 致命瞄準（deadly_aim）：專注加成 ─
        int deadlyLv = pt.getTalentLevel("deadly_aim");
        if (deadlyLv > 0) {
            Talent t = talentManager.findTalent("deadly_aim");
            double perFocus = t.getEffectDouble(deadlyLv, "damagePerFocus", 0.04);
            mult += focusManager.getFocus(player) * perFocus;
        }

        // ─ 4. 連擊強化（combo_shot）+ 急速殺機（rapid_fire）─
        int comboShotLv = pt.getTalentLevel("combo_shot");
        if (comboShotLv > 0) {
            Talent t = talentManager.findTalent("combo_shot");
            double perCombo = t.getEffectDouble(comboShotLv, "damagePerCombo", 0.05);
            int combo = focusManager.getCombo(player);
            mult += combo * perCombo;

            // 急速殺機：連擊滿時觸發倍率
            int rapidLv = pt.getTalentLevel("rapid_fire");
            if (rapidLv > 0 && combo >= FocusManager.MAX_COMBO) {
                Talent rtl = talentManager.findTalent("rapid_fire");
                double bonus = rtl.getEffectDouble(rapidLv, "maxComboBonus", 1.5);
                mult *= bonus;
                focusManager.resetCombo(player); // 消耗連擊
                player.sendMessage("§c§l[急速殺機] §e連擊爆發！");
            }
        }

        // ─ 5. 追蹤標記（tracking_mark）：標記加成 ─
        if (focusManager.isMarked(player, target)) {
            int markLv = pt.getTalentLevel("tracking_mark");
            if (markLv > 0) {
                Talent t = talentManager.findTalent("tracking_mark");
                mult += t.getEffectDouble(markLv, "markedDamageBonus", 0.25);
            }
        }

        // ─ 套用乘數 ─
        if (mult != 1.0) {
            event.setDamage(dmg * mult);
        }

        // ─ 6. 爆頭精通（headshot_mastery）─
        int headshotLv = pt.getTalentLevel("headshot_mastery");
        if (headshotLv > 0) {
            double arrowY  = arrow.getLocation().getY();
            double eyeY    = target.getEyeLocation().getY();
            if (Math.abs(arrowY - eyeY) < 0.35) { // 命中頭部範圍
                Talent t = talentManager.findTalent("headshot_mastery");
                double hsMult = t.getEffectDouble(headshotLv, "headshotMultiplier", 1.5);
                int focusGain = (int) t.getEffectDouble(headshotLv, "focusOnHeadshot", 2);

                event.setDamage(event.getDamage() * hsMult);
                focusManager.addFocus(player, focusGain);

                player.sendMessage("§6[爆頭！] §e+" + focusGain + " 專注");
                target.getWorld().spawnParticle(Particle.CRIT,
                        target.getEyeLocation(), 12, 0.2, 0.2, 0.2, 0.3);
                player.playSound(player.getLocation(),
                        Sound.ENTITY_EXPERIENCE_ORB_PICKUP, 0.8f, 1.8f);
            }
        }

        // ─ 7. 連擊計數（quick_draw）─
        int quickDrawLv = pt.getTalentLevel("quick_draw");
        if (quickDrawLv > 0) {
            focusManager.addCombo(player);
        }

        // ─ 8. 獵人鎮定：命中獲得 1 專注（靜止時才觸發）─
        int huntersCalmLv = pt.getTalentLevel("hunters_calm");
        if (huntersCalmLv > 0 && focusManager.isStill(player)) {
            focusManager.addFocus(player, 1);
        }
    }

    // ══════════════════════════════════════════════════════
    //  2. 箭矢命中方塊/實體 — 特殊技能箭效果
    // ══════════════════════════════════════════════════════

    @EventHandler
    public void onProjectileHit(ProjectileHitEvent event) {
        if (!(event.getEntity() instanceof AbstractArrow arrow)) return;
        if (!(arrow.getShooter() instanceof Player player)) return;

        // ── 分裂箭 ──
        if (arrow.hasMetadata("bow_split_arrow")) {
            Entity hitEntity = event.getHitEntity();
            if (hitEntity == null) return; // 只在命中實體時分裂

            int splitCount = (int) arrow.getMetadata("bow_split_count").get(0).asDouble();
            double splitDmg = arrow.getMetadata("bow_split_damage").get(0).asDouble();
            Location hitLoc = hitEntity.getLocation().clone();

            for (int i = 0; i < splitCount; i++) {
                double angle = (2 * Math.PI / splitCount) * i;
                Vector dir = new Vector(Math.cos(angle), 0.15, Math.sin(angle))
                        .normalize().multiply(2.2);
                Arrow splitArrow = player.getWorld().spawn(
                        hitLoc.clone().add(0, 0.6, 0), Arrow.class);
                splitArrow.setVelocity(dir);
                splitArrow.setShooter(player);
                splitArrow.setDamage(splitDmg);
                splitArrow.setPickupStatus(AbstractArrow.PickupStatus.DISALLOWED);
            }
            hitLoc.getWorld().spawnParticle(Particle.CRIT,
                    hitLoc.add(0, 1, 0), 18, 0.5, 0.5, 0.5, 0.2);
            player.playSound(hitLoc, Sound.ENTITY_ARROW_SHOOT, 0.8f, 1.3f);
            arrow.remove();
            return;
        }

        // ── 緩速箭 ──
        if (arrow.hasMetadata("bow_slow_arrow")) {
            Entity hitEntity = event.getHitEntity();
            if (!(hitEntity instanceof LivingEntity le)) return;

            int slowLv  = (int) arrow.getMetadata("bow_slow_level").get(0).asDouble();
            int slowDur = (int) arrow.getMetadata("bow_slow_duration").get(0).asDouble();
            le.addPotionEffect(new PotionEffect(
                    PotionEffectType.SLOWNESS, slowDur, slowLv - 1, false, true, true));

            le.getWorld().spawnParticle(Particle.SNOWFLAKE,
                    le.getLocation().add(0, 1, 0), 18, 0.3, 0.5, 0.3, 0);
            le.getWorld().playSound(le.getLocation(),
                    Sound.BLOCK_POWDER_SNOW_PLACE, 1.0f, 1.0f);
        }
    }

    // ══════════════════════════════════════════════════════
    //  3. 幻影步伐（phantom_step）— 受傷時自動閃避
    // ══════════════════════════════════════════════════════

    @EventHandler(priority = EventPriority.LOW)
    public void onPlayerDamaged(EntityDamageEvent event) {
        if (!(event.getEntity() instanceof Player player)) return;
        if (event.isCancelled()) return;

        PlayerTalents pt = talentManager.getPlayerTalents(player);
        int psLv = pt.getTalentLevel("phantom_step");
        if (psLv < 1) return;

        UUID pid = player.getUniqueId();
        long now = System.currentTimeMillis();
        Long last = phantomStepCooldowns.get(pid);

        Talent talent = talentManager.findTalent("phantom_step");
        long cdMs = (long) (talent.getEffectDouble(psLv, "cooldownSecs", 20) * 1000);
        if (last != null && now - last < cdMs) return;

        phantomStepCooldowns.put(pid, now);

        double dashForce   = talent.getEffectDouble(psLv, "dashForce", 1.2);
        int    invisTicks  = (int) talent.getEffectDouble(psLv, "invisDurationTicks", 20);
        double dmgReduction= talent.getEffectDouble(psLv, "damageReduction", 0.30);

        // 向後衝刺 (multiply(-1) = 反向)
        Vector dash = player.getLocation().getDirection().clone()
                .multiply(-1).setY(0.4).normalize().multiply(dashForce);
        player.setVelocity(dash);

        // 減免傷害
        event.setDamage(event.getDamage() * (1 - dmgReduction));

        // 短暫隱身
        player.addPotionEffect(new PotionEffect(
                PotionEffectType.INVISIBILITY, invisTicks, 0, false, false, false));

        // 特效
        player.getWorld().spawnParticle(Particle.CLOUD,
                player.getLocation().add(0, 1, 0), 15, 0.3, 0.5, 0.3, 0.05);
        player.playSound(player.getLocation(),
                Sound.ENTITY_ENDERMAN_TELEPORT, 0.5f, 1.5f);
        player.sendActionBar("§b§l[幻影步伐] §7閃避！");
    }

    // ══════════════════════════════════════════════════════
    //  4. 標記目標死亡時清除標記
    // ══════════════════════════════════════════════════════

    @EventHandler
    public void onEntityDeath(EntityDeathEvent event) {
        // 如果死亡的實體被某個玩家標記，清除標記
        UUID deadId = event.getEntity().getUniqueId();
        for (Player p : Bukkit.getOnlinePlayers()) {
            if (focusManager.isMarked(p, event.getEntity())) {
                event.getEntity().setGlowing(false);
            }
        }
    }

    // ══════════════════════════════════════════════════════
    //  5. 玩家離線清理
    // ══════════════════════════════════════════════════════

    @EventHandler
    public void onPlayerQuit(PlayerQuitEvent event) {
        focusManager.cleanup(event.getPlayer());
        phantomStepCooldowns.remove(event.getPlayer().getUniqueId());
    }

    // ══════════════════════════════════════════════════════
    //  6. 被動週期任務
    // ══════════════════════════════════════════════════════

    private void startPassiveTasks() {
        // ─ 獵人鎮定：靜止時每秒積累專注 ─
        new BukkitRunnable() {
            @Override
            public void run() {
                for (Player p : Bukkit.getOnlinePlayers()) {
                    if (!focusManager.isStill(p)) continue;
                    PlayerTalents pt = talentManager.getPlayerTalents(p);
                    int lv = pt.getTalentLevel("hunters_calm");
                    if (lv < 1) continue;
                    if (focusManager.getFocus(p) >= FocusManager.MAX_FOCUS) continue;
                    Talent t = talentManager.findTalent("hunters_calm");
                    int fps = (int) t.getEffectDouble(lv, "focusPerSecond", 1);
                    focusManager.addFocus(p, fps);
                }
            }
        }.runTaskTimer(plugin, 20L, 20L); // 每秒

        // ─ 獵人本能：每 3 秒掃描周圍敵人並使其發光 ─
        new BukkitRunnable() {
            @Override
            public void run() {
                for (Player p : Bukkit.getOnlinePlayers()) {
                    PlayerTalents pt = talentManager.getPlayerTalents(p);
                    int lv = pt.getTalentLevel("hunters_instinct");
                    if (lv < 1) continue;
                    Talent t = talentManager.findTalent("hunters_instinct");
                    double radius     = t.getEffectDouble(lv, "detectRadius", 20);
                    int    glowTicks  = (int) t.getEffectDouble(lv, "glowDurationTicks", 80);

                    for (Entity e : p.getNearbyEntities(radius, radius / 2, radius)) {
                        if (!(e instanceof LivingEntity le)) continue;
                        if (e instanceof Player) continue;
                        le.setGlowing(true);
                        Bukkit.getScheduler().runTaskLater(plugin,
                                () -> le.setGlowing(false), glowTicks);
                    }
                }
            }
        }.runTaskTimer(plugin, 60L, 60L); // 每 3 秒
    }
}

package com.customrpg.listeners;

import com.customrpg.CustomRPG;
import com.customrpg.managers.MobManager;
import com.customrpg.managers.PlayerStatsManager;
import com.customrpg.managers.WeaponManager;
import org.bukkit.*;
import org.bukkit.entity.*;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityCombustEvent;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.event.entity.ProjectileHitEvent;
import org.bukkit.event.entity.ProjectileLaunchEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;
import org.bukkit.projectiles.ProjectileSource;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.util.Vector;

import java.util.Random;
import java.util.UUID;

/**
 * MobListener - Handles custom mob behavior events
 *
 * This listener implements special behaviors for custom mobs such as
 * projectile attacks, death mechanics, and combat modifications.
 *
 * Handles:
 * - Snow Zombie: Throws snowballs periodically
 * - Fire Skeleton: Shoots fire arrows
 * - Giant Slime: Splits into smaller slimes on death
 */
public class MobListener implements Listener {

    private final CustomRPG plugin;
    private final MobManager mobManager;
    private final PlayerStatsManager statsManager;
    private final WeaponManager weaponManager;
    private final Random random;

    /**
     * Constructor for MobListener
     * @param plugin Main plugin instance
     * @param mobManager MobManager instance
     */
    public MobListener(CustomRPG plugin, MobManager mobManager, PlayerStatsManager statsManager, WeaponManager weaponManager) {
        this.plugin = plugin;
        this.mobManager = mobManager;
        this.statsManager = statsManager;
        this.weaponManager = weaponManager;
        this.random = new Random();
        startCustomMobBehaviors();
    }

    /**
     * Start periodic behaviors for custom mobs
     */
    private void startCustomMobBehaviors() {
        new BukkitRunnable() {
            @Override
            public void run() {
                for (org.bukkit.World world : plugin.getServer().getWorlds()) {
                    for (Entity entity : world.getEntities()) {
                        String mobKey = mobManager.getCustomMobKey(entity);
                        if (mobKey == null) continue;

                        MobManager.MobData mobData = mobManager.getMobData(mobKey);
                        if (mobData == null) continue;

                        applyPeriodicBehavior(entity, mobData);
                    }
                }
            }
        }.runTaskTimer(plugin, 0L, 60L);
    }

    /**
     * Apply periodic behaviors to custom mobs
     * @param entity The mob entity
     * @param mobData The mob data
     */
    private void applyPeriodicBehavior(Entity entity, MobManager.MobData mobData) {
        if (!(entity instanceof LivingEntity)) {
            return;
        }

        LivingEntity mob = (LivingEntity) entity;
        String behavior = mobData.getSpecialBehavior().toLowerCase();

        switch (behavior) {
            case "snowball_thrower" -> {
                if (random.nextDouble() < 0.3) {
                    throwSnowball(mob);
                }
            }
            case "snowball_mage" -> {
                // 骷髏法師：丟出傷害性雪球
                if (random.nextDouble() < 0.4) {
                    throwDamagingSnowball(mob);
                }
            }
            case "shadow_teleport" -> {
                // 影襲蜘蛛：暗影粒子 + 短距離瞬移
                // 持續噴出粒子
                Location loc = mob.getLocation().add(0, 0.5, 0);
                mob.getWorld().spawnParticle(Particle.DRIPPING_OBSIDIAN_TEAR, loc, 2, 0.3, 0.3, 0.3, 0);
                mob.getWorld().spawnParticle(Particle.SQUID_INK, loc, 1, 0.2, 0.2, 0.2, 0.01);

                // 15% 機率瞬移到附近玩家身邊
                if (random.nextDouble() < 0.15) {
                    shadowTeleport(mob);
                }
            }
            case "charge_attack" -> {
                // 狂暴野豬：直線衝撞
                if (random.nextDouble() < 0.2) {
                    chargeAttack(mob);
                }
            }
            case "flee" -> {
                // 逃跑型：看到玩家就跑
                fleeFromPlayer(mob);
            }
            case "stalker_stealth" -> {
                // 潛伏蜘蛛：靠近玩家時隱形
                stalkerStealth(mob);
            }
            case "plague_aura" -> {
                // 瘟疫散播者：周圍持續毒氣
                plagueAura(mob);
            }
            case "charge_beast" -> {
                // 衝鋒野獸：鎖定後直線衝刺
                if (random.nextDouble() < 0.2) {
                    chargeBeastAttack(mob);
                }
            }
            case "berserker_rage" -> {
                // 狂戰殭屍：低血量時發紅光粒子
                double hpPercent = mob.getHealth() / mob.getMaxHealth();
                if (hpPercent < 0.3) {
                    mob.getWorld().spawnParticle(Particle.DAMAGE_INDICATOR, mob.getLocation().add(0, 1, 0),
                            3, 0.3, 0.3, 0.3, 0.02);
                }
            }
            // ═══ 野外 Boss 行為 ═══
            case "boss_pumpkin_knight" -> {
                // 南瓜騎士：Boss 光環粒子
                mob.getWorld().spawnParticle(Particle.FLAME, mob.getLocation().add(0, 2.2, 0),
                        3, 0.2, 0.1, 0.2, 0.01);
            }
            case "boss_scissor_frenzy" -> {
                // 瘋狂剪刀手：快速揮砍粒子 + 加速
                mob.getWorld().spawnParticle(Particle.SWEEP_ATTACK, mob.getLocation().add(0, 1, 0),
                        1, 0.5, 0.3, 0.5, 0);
                if (!mob.hasPotionEffect(PotionEffectType.SPEED)) {
                    mob.addPotionEffect(new PotionEffect(PotionEffectType.SPEED, 80, 1, false, false));
                }
            }
            case "boss_zombie_beast" -> {
                // 豬屍獸：衝撞（10秒冷卻）+ Boss 粒子
                mob.getWorld().spawnParticle(Particle.LAVA, mob.getLocation().add(0, 1, 0),
                        1, 0.3, 0.3, 0.3, 0);
                bossZombieBeastCharge(mob);
            }
        }
    }

    /**
     * Handle custom mob death events
     * @param event EntityDeathEvent
     */
    @EventHandler(priority = EventPriority.HIGH)
    public void onMobDeath(EntityDeathEvent event) {
        // 排除玩家死亡
        if (event.getEntity() instanceof Player) {
            return;
        }

        Player killer = event.getEntity().getKiller();
        if (killer == null) {
            // 支援野獸擊殺：如果 killer 為 null，檢查 beast_kill_owner metadata
            if (event.getEntity().hasMetadata("beast_kill_owner")) {
                try {
                    String ownerId = event.getEntity().getMetadata("beast_kill_owner").get(0).asString();
                    Player owner = Bukkit.getPlayer(UUID.fromString(ownerId));
                    if (owner != null && owner.isOnline()) {
                        killer = owner;
                    }
                } catch (Exception ignored) {}
            }
        }

        String mobKey = mobManager.getCustomMobKey(event.getEntity());

        // 如果是自製怪物
        if (mobKey != null) {
            MobManager.MobData mobData = mobManager.getMobData(mobKey);
            if (mobData == null) {
                return;
            }

            // 沒有擊殺者（例如跌落死亡），跳過獎勵
            if (killer == null) {
                return;
            }

            int mobLevel = mobManager.getMobLevel(event.getEntity());

            // Handle custom mob drops or effects
            // For example, splitting slimes
            if (mobData.getSpecialBehavior().equalsIgnoreCase("split_on_death")) {
                splitSlime(event.getEntity(), mobData);
            }

            // 黏液爆破者：延遲爆炸
            if (mobData.getSpecialBehavior().equalsIgnoreCase("delayed_explosion")) {
                delayedExplosion(event.getEntity().getLocation(), mobLevel);
            }

            // 清除預設掉落物（如果有自定義掉落物）
            if (!mobData.getVanillaDrops().isEmpty() || !mobData.getWeaponDrops().isEmpty() || !mobData.getEquipmentDrops().isEmpty()) {
                event.getDrops().clear();

                // 掉落原版物品
                for (MobManager.DropItem dropItem : mobData.getVanillaDrops()) {
                    if (random.nextDouble() < dropItem.getChance()) {
                        int amount = dropItem.getMinAmount();
                        if (dropItem.getMaxAmount() > dropItem.getMinAmount()) {
                            amount = random.nextInt(dropItem.getMaxAmount() - dropItem.getMinAmount() + 1) + dropItem.getMinAmount();
                        }
                        event.getDrops().add(new ItemStack(dropItem.getMaterial(), amount));
                    }
                }

                // 掉落自定義武器
                for (MobManager.WeaponDrop weaponDrop : mobData.getWeaponDrops()) {
                    if (random.nextDouble() < weaponDrop.getChance()) {
                        ItemStack weapon = weaponManager.createWeapon(weaponDrop.getWeaponKey());
                        if (weapon != null) {
                            event.getDrops().add(weapon);
                            killer.sendMessage(ChatColor.GOLD + "★ 獲得稀有武器: " + weapon.getItemMeta().getDisplayName());
                        }
                    }
                }

                // 掉落自定義裝備 (飾品 / 裝甲)
                for (MobManager.EquipmentDrop equipDrop : mobData.getEquipmentDrops()) {
                    if (random.nextDouble() < equipDrop.getChance()) {
                        ItemStack dropItem = null;
                        if ("armor".equalsIgnoreCase(equipDrop.getType())) {
                            // 裝甲掉落
                            com.customrpg.equipment.ArmorManager armorMgr = plugin.getArmorManager();
                            if (armorMgr != null) {
                                com.customrpg.equipment.ArmorData armor = armorMgr.createArmor(equipDrop.getEquipmentKey());
                                if (armor != null) {
                                    dropItem = armor.toItemStack();
                                }
                            }
                        } else {
                            // 飾品掉落
                            com.customrpg.equipment.EquipmentManager equipMgr = plugin.getEquipmentManager();
                            if (equipMgr != null) {
                                com.customrpg.equipment.EquipmentData equip = equipMgr.createEquipment(equipDrop.getEquipmentKey());
                                if (equip != null) {
                                    dropItem = equip.toItemStack();
                                }
                            }
                        }
                        if (dropItem != null) {
                            event.getDrops().add(dropItem);
                            String itemName = dropItem.hasItemMeta() && dropItem.getItemMeta().hasDisplayName()
                                    ? dropItem.getItemMeta().getDisplayName()
                                    : equipDrop.getEquipmentKey();
                            killer.sendMessage(ChatColor.LIGHT_PURPLE + "★ 獲得稀有裝備: " + itemName);
                        }
                    }
                }
            }

            // 給予經驗值（基於等級 + 階級倍率 + 等級差距調整）
            int baseExpReward = mobData.calculateExp(mobLevel);

            // 階級經驗倍率：普通 x1, 精英 x2.5, Boss x5
            String mobTier = mobManager.getMobTier(event.getEntity());
            double tierMultiplier = switch (mobTier) {
                case "ELITE" -> 2.5;
                case "BOSS" -> 5.0;
                default -> 1.0;
            };

            // 等級差距調整：怪物等級比玩家高 → 加成，比玩家低太多 → 減少
            com.customrpg.players.PlayerStats killerStats = statsManager.getStats(killer);
            int playerLevel = killerStats.getLevel();
            int levelDiff = mobLevel - playerLevel;
            double levelMultiplier;
            if (levelDiff >= 5) {
                levelMultiplier = 1.5;  // 怪物比玩家高 5 級以上 → +50%
            } else if (levelDiff >= 0) {
                levelMultiplier = 1.0 + (levelDiff * 0.05); // 每高 1 級 +5%
            } else if (levelDiff >= -5) {
                levelMultiplier = 1.0;  // 低 1~5 級 → 正常
            } else if (levelDiff >= -10) {
                levelMultiplier = 0.5;  // 低 6~10 級 → 50%
            } else {
                levelMultiplier = 0.1;  // 低 10 級以上 → 10%（防止刷低等怪）
            }

            int finalExp = Math.max(1, (int) (baseExpReward * tierMultiplier * levelMultiplier));
            if (finalExp > 0) {
                statsManager.addExp(killer, finalExp);

                // 根據階級顯示不同顏色的訊息
                String tierTag = switch (mobTier) {
                    case "ELITE" -> ChatColor.GOLD + "[精英] ";
                    case "BOSS" -> ChatColor.RED + "[BOSS] ";
                    default -> "";
                };

                killer.sendMessage(ChatColor.YELLOW + "擊敗 " + tierTag +
                    ChatColor.YELLOW + "[Lv." + mobLevel + "] " +
                    ChatColor.stripColor(mobData.getName()) + " 獲得 " +
                    ChatColor.GREEN + finalExp + ChatColor.YELLOW + " 經驗值" +
                    (tierMultiplier > 1.0 ? ChatColor.GOLD + " (x" + tierMultiplier + ")" : ""));
            }

            // 移除 BossBar
            com.customrpg.managers.BossBarManager bossBarMgr = plugin.getBossBarManager();
            if (bossBarMgr != null) {
                bossBarMgr.onMobDeath(event.getEntity().getUniqueId());
            }
        } else {
            // 普通原版怪物：依類型給予不同經驗值
            if (killer == null) return; // 無擊殺者（跌落、其他原因死亡）
            int vanillaExp = switch (event.getEntity().getType()) {
                case ENDER_DRAGON -> 500;
                case WITHER -> 300;
                case ELDER_GUARDIAN -> 80;
                case WARDEN -> 100;
                case RAVAGER -> 50;
                case EVOKER, VINDICATOR -> 20;
                case GHAST, BLAZE, GUARDIAN -> 15;
                case ENDERMAN, PIGLIN_BRUTE -> 10;
                case CREEPER, SKELETON, ZOMBIE, SPIDER -> 5;
                case SLIME, MAGMA_CUBE -> 3;
                default -> 2;
            };
            statsManager.addExp(killer, vanillaExp);
            killer.sendMessage(ChatColor.YELLOW + "獲得 " + vanillaExp + " 經驗值");
        }
    }

    /**
     * Handle custom mob damage events (level-scaled damage)
     * 處理玩家攻擊 BlockDisplay 偽裝系統的情況
     * @param event EntityDamageByEntityEvent
     */
    @EventHandler
    public void onMobAttack(EntityDamageByEntityEvent event) {
        // === 情況 1：玩家攻擊 BlockDisplay 或名稱標籤 ArmorStand ===
        // BlockDisplay 和 ArmorStand 不是 LivingEntity，需要找到對應的隱形核心
        if (event.getDamager() instanceof Player player) {
            Entity target = event.getEntity();

            // 檢查是否攻擊到 BlockDisplay
            if (target instanceof org.bukkit.entity.BlockDisplay) {
                event.setCancelled(true); // 取消對 BlockDisplay 的傷害

                // 從 BlockDisplay 的 PersistentData 獲取核心 UUID
                String coreUuidString = target.getPersistentDataContainer().get(
                    new org.bukkit.NamespacedKey(plugin, "disguise_blockdisplay"),
                    org.bukkit.persistence.PersistentDataType.STRING
                );

                if (coreUuidString != null) {
                    java.util.UUID coreUuid = java.util.UUID.fromString(coreUuidString);
                    // 在同一世界中尋找核心實體
                    for (Entity entity : target.getWorld().getEntities()) {
                        if (entity.getUniqueId().equals(coreUuid) && entity instanceof LivingEntity core) {
                            // 找到核心，對其造成傷害

                            // 計算傷害（考慮玩家的武器）
                            double damage = 1.0;
                            ItemStack weapon = player.getInventory().getItemInMainHand();
                            if (weapon != null && !weapon.getType().isAir()) {
                                // 這裡可以加入自定義武器傷害計算
                                damage = weaponManager.getBaseDamage(weapon);
                            }

                            core.damage(damage, player);
                            plugin.getLogger().fine("玩家攻擊 BlockDisplay，轉移 " + damage + " 傷害到核心");
                            return;
                        }
                    }
                }
            }

            // 檢查是否攻擊到名稱標籤 ArmorStand
            if (target instanceof ArmorStand armorStand) {
                String coreUuidString = armorStand.getPersistentDataContainer().get(
                    new org.bukkit.NamespacedKey(plugin, "disguise_nametag"),
                    org.bukkit.persistence.PersistentDataType.STRING
                );

                if (coreUuidString != null) {
                    event.setCancelled(true); // 取消對 ArmorStand 的傷害

                    java.util.UUID coreUuid = java.util.UUID.fromString(coreUuidString);
                    // 在同一世界中尋找核心實體
                    for (Entity entity : target.getWorld().getEntities()) {
                        if (entity.getUniqueId().equals(coreUuid) && entity instanceof LivingEntity core) {
                            // 找到核心，對其造成傷害

                            // 計算傷害
                            double damage = 1.0;
                            ItemStack weapon = player.getInventory().getItemInMainHand();
                            if (weapon != null && !weapon.getType().isAir()) {
                                damage = weaponManager.getBaseDamage(weapon);
                            }

                            core.damage(damage, player);
                            plugin.getLogger().fine("玩家攻擊名稱標籤，轉移 " + damage + " 傷害到核心");
                            return;
                        }
                    }
                }
            }
        }

        // === 情況 1.5：玩家攻擊自訂 Boss 怪物（特殊防禦機制）===
        if (event.getDamager() instanceof Player player && event.getEntity() instanceof LivingEntity target) {
            String targetMobKey = mobManager.getCustomMobKey(target);
            if (targetMobKey != null) {
                MobManager.MobData targetData = mobManager.getMobData(targetMobKey);
                if (targetData != null) {
                    // 南瓜騎士：35% 格擋 → 減傷60%
                    if (targetData.getSpecialBehavior().equalsIgnoreCase("boss_pumpkin_knight")) {
                        if (random.nextDouble() < 0.35) {
                            event.setDamage(event.getDamage() * 0.4);
                            target.getWorld().spawnParticle(Particle.ENCHANTED_HIT, target.getLocation().add(0, 1, 0),
                                    10, 0.3, 0.3, 0.3, 0.05);
                            target.getWorld().playSound(target.getLocation(), Sound.ITEM_SHIELD_BLOCK, 1.0f, 1.0f);
                            player.sendMessage(ChatColor.YELLOW + " 南瓜騎士格擋了你的攻擊！");
                        }
                    }
                }

                // BossBar 顯示：玩家攻擊自訂怪物時顯示血量條
                com.customrpg.managers.BossBarManager bossBarMgr = plugin.getBossBarManager();
                if (bossBarMgr != null) {
                    // 延遲1tick更新，讓傷害先生效
                    new BukkitRunnable() {
                        @Override
                        public void run() {
                            if (!target.isDead()) {
                                bossBarMgr.onMobDamaged(target);
                            }
                        }
                    }.runTaskLater(plugin, 1L);
                }
            }
        }

        // === 情況 2：自定義生物攻擊玩家（等級化傷害）===
        // 檢查是否為自定義生物攻擊玩家
        if (!(event.getDamager() instanceof LivingEntity)) {
            return;
        }

        if (!(event.getEntity() instanceof Player)) {
            return;
        }

        LivingEntity attacker = (LivingEntity) event.getDamager();
        String mobKey = mobManager.getCustomMobKey(attacker);

        if (mobKey == null) {
            return;
        }

        MobManager.MobData mobData = mobManager.getMobData(mobKey);
        if (mobData == null) {
            return;
        }

        // 獲取生物等級並計算傷害
        int mobLevel = mobManager.getMobLevel(attacker);
        double scaledDamage = mobData.calculateDamage(mobLevel);

        // 狂戰殭屍：HP < 30% → +50% 傷害
        if (mobData.getSpecialBehavior().equalsIgnoreCase("berserker_rage")) {
            double hpPercent = attacker.getHealth() / attacker.getMaxHealth();
            if (hpPercent < 0.3) {
                scaledDamage *= 1.5;
                attacker.getWorld().spawnParticle(Particle.DAMAGE_INDICATOR, attacker.getLocation().add(0, 1.5, 0),
                        8, 0.3, 0.3, 0.3, 0.05);
                attacker.getWorld().playSound(attacker.getLocation(), Sound.ENTITY_RAVAGER_ROAR, 0.4f, 1.5f);
            }
        }

        // 潛伏蜘蛛：隱形狀態下第一擊 +80% 傷害
        if (mobData.getSpecialBehavior().equalsIgnoreCase("stalker_stealth")) {
            if (attacker.hasPotionEffect(PotionEffectType.INVISIBILITY)) {
                scaledDamage *= 1.8;
                attacker.removePotionEffect(PotionEffectType.INVISIBILITY);
                attacker.getWorld().spawnParticle(Particle.CRIT, attacker.getLocation().add(0, 1, 0),
                        15, 0.3, 0.3, 0.3, 0.1);
                attacker.getWorld().playSound(attacker.getLocation(), Sound.ENTITY_PLAYER_ATTACK_CRIT, 1.0f, 1.0f);
            }
        }

        // 設置等級化傷害（對於偽裝生物，確保傷害大於0）
        if (scaledDamage < 1.0) {
            scaledDamage = 1.0; // 最低傷害為 1
        }
        event.setDamage(scaledDamage);

        // 冰霜殭屍：攻擊附帶緩速
        if (mobData.getSpecialBehavior().equalsIgnoreCase("frost_attack")) {
            if (event.getEntity() instanceof Player victim) {
                victim.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS, 60, 1)); // 3秒 緩速II
                victim.getWorld().spawnParticle(Particle.SNOWFLAKE, victim.getLocation().add(0, 1, 0),
                        10, 0.3, 0.5, 0.3, 0.02);
                victim.getWorld().playSound(victim.getLocation(), Sound.BLOCK_GLASS_BREAK, 0.5f, 1.8f);
            }
        }

        // ═══ 南瓜騎士：30% 重擊（2倍傷害 + 擊退） ═══
        if (mobData.getSpecialBehavior().equalsIgnoreCase("boss_pumpkin_knight")) {
            if (random.nextDouble() < 0.3) {
                scaledDamage *= 2.0;
                event.setDamage(scaledDamage);
                if (event.getEntity() instanceof Player victim) {
                    Vector knockback = attacker.getLocation().getDirection().normalize().multiply(1.0).setY(0.4);
                    victim.setVelocity(knockback);
                    attacker.getWorld().playSound(attacker.getLocation(), Sound.ENTITY_IRON_GOLEM_ATTACK, 1.0f, 0.6f);
                    attacker.getWorld().spawnParticle(Particle.CRIT, victim.getLocation().add(0, 1, 0),
                            20, 0.3, 0.3, 0.3, 0.1);
                    victim.sendMessage(ChatColor.RED + "⚔ 南瓜騎士使出了重擊！");
                }
            }
        }

        // ═══ 瘋狂剪刀手：每次攻擊附帶流血（凋零 1 秒）+ 雙重攻擊（40% 機率連擊）═══
        if (mobData.getSpecialBehavior().equalsIgnoreCase("boss_scissor_frenzy")) {
            if (event.getEntity() instanceof Player victim) {
                // 流血
                victim.addPotionEffect(new PotionEffect(PotionEffectType.WITHER, 20, 0, false, true)); // 1秒凋零
                attacker.getWorld().spawnParticle(Particle.DAMAGE_INDICATOR, victim.getLocation().add(0, 1, 0),
                        5, 0.2, 0.3, 0.2, 0.02);
                attacker.getWorld().playSound(attacker.getLocation(), Sound.ENTITY_PLAYER_ATTACK_SWEEP, 1.0f, 1.5f);

                // 40% 連擊（延遲 5 tick 再打一下）
                if (random.nextDouble() < 0.4) {
                    final double comboDamage = scaledDamage * 0.6;
                    new BukkitRunnable() {
                        @Override
                        public void run() {
                            if (attacker.isDead() || victim.isDead()) return;
                            if (attacker.getLocation().distance(victim.getLocation()) > 4) return;
                            victim.damage(comboDamage, attacker);
                            attacker.getWorld().spawnParticle(Particle.SWEEP_ATTACK, victim.getLocation().add(0, 1, 0),
                                    3, 0.3, 0.3, 0.3, 0);
                            attacker.getWorld().playSound(victim.getLocation(), Sound.ENTITY_PLAYER_ATTACK_SWEEP, 0.8f, 1.8f);
                        }
                    }.runTaskLater(plugin, 5L);
                }
            }
        }

        // Debug 訊息
        plugin.getLogger().info("Custom mob " + mobData.getName() + " (Lv." + mobLevel + ") attacked player with " + scaledDamage + " damage");
    }

    /**
     * Split a giant slime into smaller ones
     * @param entity The dying entity
     * @param mobData The mob data
     */
    private void splitSlime(LivingEntity entity, MobManager.MobData mobData) {
        Location location = entity.getLocation();

        for (int i = 0; i < 4; i++) {
            Slime smallSlime = (Slime) location.getWorld().spawnEntity(location, EntityType.SLIME);
            smallSlime.setSize(1);

            Vector velocity = new Vector(
                random.nextDouble() - 0.5,
                0.5,
                random.nextDouble() - 0.5
            ).normalize().multiply(0.5);
            smallSlime.setVelocity(velocity);
        }
    }

    /**
     * Handle projectile launch events for custom mobs
     * @param event ProjectileLaunchEvent
     */
    @EventHandler
    public void onProjectileLaunch(ProjectileLaunchEvent event) {
        ProjectileSource shooter = event.getEntity().getShooter();
        if (!(shooter instanceof LivingEntity)) {
            return;
        }

        LivingEntity mob = (LivingEntity) shooter;
        String mobKey = mobManager.getCustomMobKey(mob);
        if (mobKey == null) {
            return;
        }

        MobManager.MobData mobData = mobManager.getMobData(mobKey);
        if (mobData == null) {
            return;
        }

        if (mobData.getSpecialBehavior().equalsIgnoreCase("fire_arrows")) {
            if (event.getEntity() instanceof Arrow) {
                Arrow arrow = (Arrow) event.getEntity();
                arrow.setFireTicks(1000);
            }
        }

        // 爆裂骷髏：標記箭矢為爆炸箭
        if (mobData.getSpecialBehavior().equalsIgnoreCase("explosive_arrow")) {
            if (event.getEntity() instanceof Arrow arrow) {
                arrow.getPersistentDataContainer().set(
                        new org.bukkit.NamespacedKey(plugin, "explosive_arrow"),
                        org.bukkit.persistence.PersistentDataType.BOOLEAN, true
                );
                // 火焰軌跡視覺提示
                arrow.setFireTicks(200);
            }
        }
    }

    /**
     * Throw a snowball from the mob
     * @param mob The mob entity
     */
    private void throwSnowball(LivingEntity mob) {
        Player nearestPlayer = getNearestPlayer(mob, 15.0);
        if (nearestPlayer == null) {
            return;
        }

        Location mobLocation = mob.getEyeLocation();
        Location playerLocation = nearestPlayer.getEyeLocation();

        Vector direction = playerLocation.toVector().subtract(mobLocation.toVector()).normalize();

        Snowball snowball = (Snowball) mob.getWorld().spawnEntity(mobLocation, EntityType.SNOWBALL);
        snowball.setVelocity(direction.multiply(1.5));
        snowball.setShooter(mob);
    }

    /**
     * Get the nearest player to a mob within range
     * @param mob The mob entity
     * @param range The search range
     * @return The nearest player or null
     */
    private Player getNearestPlayer(LivingEntity mob, double range) {
        Player nearest = null;
        double nearestDistance = range;

        for (Entity entity : mob.getNearbyEntities(range, range, range)) {
            if (entity instanceof Player player) {
                if (player.getGameMode() == org.bukkit.GameMode.CREATIVE || player.getGameMode() == org.bukkit.GameMode.SPECTATOR) continue;
                double distance = mob.getLocation().distance(player.getLocation());
                if (distance < nearestDistance) {
                    nearest = player;
                    nearestDistance = distance;
                }
            }
        }

        return nearest;
    }

    // ═══════════════════════════════════════
    //  新增特殊行為
    // ═══════════════════════════════════════

    /**
     * 黏液爆破者：死亡2秒後小範圍爆炸
     */
    private void delayedExplosion(Location deathLocation, int mobLevel) {
        // 生成粒子警告
        new BukkitRunnable() {
            int ticks = 0;
            @Override
            public void run() {
                if (ticks >= 40) { // 2秒 = 40 ticks
                    // 爆炸！
                    deathLocation.getWorld().spawnParticle(Particle.EXPLOSION, deathLocation, 3, 0.5, 0.5, 0.5, 0);
                    deathLocation.getWorld().spawnParticle(Particle.HAPPY_VILLAGER, deathLocation, 30, 1.5, 1.0, 1.5, 0.1);
                    deathLocation.getWorld().playSound(deathLocation, Sound.ENTITY_GENERIC_EXPLODE, 1.0f, 1.5f);

                    // 對範圍內玩家造成傷害（半徑3格）
                    double damage = 5.0 + mobLevel * 1.5;
                    for (Entity entity : deathLocation.getWorld().getNearbyEntities(deathLocation, 3, 3, 3)) {
                        if (entity instanceof Player player) {
                            if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                            player.damage(damage);
                            player.sendMessage(ChatColor.RED + " 你被黏液爆炸波及了！");
                        }
                    }
                    cancel();
                    return;
                }
                // 警告粒子 (越來越密集)
                int particleCount = 3 + (ticks / 10);
                deathLocation.getWorld().spawnParticle(Particle.FLAME, deathLocation.clone().add(0, 0.5, 0),
                        particleCount, 0.3, 0.3, 0.3, 0.02);
                if (ticks % 10 == 0) {
                    deathLocation.getWorld().playSound(deathLocation, Sound.BLOCK_NOTE_BLOCK_BASS, 0.8f, 0.5f + (ticks / 40f));
                }
                ticks += 5;
            }
        }.runTaskTimer(plugin, 0L, 5L);
    }

    /**
     * 影襲蜘蛛：短距離瞬移到玩家附近
     */
    private void shadowTeleport(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 12.0);
        if (target == null) return;

        Location playerLoc = target.getLocation();
        // 隨機在玩家周圍 2~4 格瞬移
        double angle = random.nextDouble() * Math.PI * 2;
        double dist = 2.0 + random.nextDouble() * 2.0;
        Location teleportLoc = playerLoc.clone().add(Math.cos(angle) * dist, 0, Math.sin(angle) * dist);

        // 確保目標位置安全
        teleportLoc.setY(teleportLoc.getWorld().getHighestBlockYAt(teleportLoc) + 1);

        // 起點粒子效果
        Location fromLoc = mob.getLocation();
        fromLoc.getWorld().spawnParticle(Particle.SQUID_INK, fromLoc.clone().add(0, 0.5, 0), 15, 0.3, 0.5, 0.3, 0.05);
        fromLoc.getWorld().spawnParticle(Particle.DRIPPING_OBSIDIAN_TEAR, fromLoc.clone().add(0, 1, 0), 10, 0.4, 0.6, 0.4, 0);
        fromLoc.getWorld().playSound(fromLoc, Sound.ENTITY_ENDERMAN_TELEPORT, 0.6f, 1.5f);

        // 瞬移
        mob.teleport(teleportLoc);

        // 終點粒子效果
        teleportLoc.getWorld().spawnParticle(Particle.SQUID_INK, teleportLoc.clone().add(0, 0.5, 0), 15, 0.3, 0.5, 0.3, 0.05);
        teleportLoc.getWorld().spawnParticle(Particle.DRIPPING_OBSIDIAN_TEAR, teleportLoc.clone().add(0, 1, 0), 10, 0.4, 0.6, 0.4, 0);
        teleportLoc.getWorld().playSound(teleportLoc, Sound.ENTITY_ENDERMAN_TELEPORT, 0.6f, 1.8f);
    }

    /**
     * 狂暴野豬：直線衝撞
     */
    private void chargeAttack(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 10.0);
        if (target == null) return;

        double distance = mob.getLocation().distance(target.getLocation());
        if (distance < 3.0 || distance > 10.0) return; // 太近或太遠不衝

        // 衝撞方向
        Vector direction = target.getLocation().toVector()
                .subtract(mob.getLocation().toVector()).normalize();

        // 播放音效
        mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_RAVAGER_ROAR, 0.5f, 1.5f);

        // 衝撞動畫 (粒子軌跡)
        new BukkitRunnable() {
            int ticks = 0;
            @Override
            public void run() {
                if (ticks >= 10 || mob.isDead()) {
                    cancel();
                    return;
                }
                mob.setVelocity(direction.clone().multiply(1.2).setY(0.05));
                mob.getWorld().spawnParticle(Particle.CLOUD, mob.getLocation().add(0, 0.3, 0),
                        5, 0.2, 0.1, 0.2, 0.02);

                // 碰到玩家就擊退
                for (Entity nearby : mob.getNearbyEntities(1.5, 1.5, 1.5)) {
                    if (nearby instanceof Player player) {
                        if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                        Vector knockback = direction.clone().multiply(0.8).setY(0.4);
                        player.setVelocity(knockback);
                        player.getWorld().playSound(player.getLocation(), Sound.ENTITY_PLAYER_HURT, 1.0f, 0.8f);
                        cancel();
                        return;
                    }
                }
                ticks++;
            }
        }.runTaskTimer(plugin, 0L, 2L);
    }

    /**
     * 逃跑型：遠離玩家
     */
    private void fleeFromPlayer(LivingEntity mob) {
        Player nearest = getNearestPlayer(mob, 8.0);
        if (nearest == null) return;

        // 計算遠離方向
        Vector away = mob.getLocation().toVector()
                .subtract(nearest.getLocation().toVector()).normalize();
        away.setY(0).normalize().multiply(0.5);
        if (random.nextDouble() < 0.3) {
            away.setY(0.2); // 偶爾跳一下
        }
        mob.setVelocity(away);
    }

    /**
     * 骷髏法師：丟出傷害性雪球（標記為魔法雪球）
     */
    private void throwDamagingSnowball(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 15.0);
        if (target == null) return;

        Location mobLoc = mob.getEyeLocation();
        Vector direction = target.getEyeLocation().toVector()
                .subtract(mobLoc.toVector()).normalize();

        Snowball snowball = mob.getWorld().spawn(mobLoc, Snowball.class);
        snowball.setVelocity(direction.multiply(1.2));
        snowball.setShooter(mob);

        // 標記這顆雪球為魔法雪球
        snowball.getPersistentDataContainer().set(
                new org.bukkit.NamespacedKey(plugin, "magic_snowball"),
                org.bukkit.persistence.PersistentDataType.BOOLEAN, true
        );

        // 紫色粒子
        mob.getWorld().spawnParticle(Particle.WITCH, mobLoc, 5, 0.2, 0.2, 0.2, 0.05);
        mob.getWorld().playSound(mobLoc, Sound.ENTITY_SNOWBALL_THROW, 1.0f, 0.6f);
    }

    /**
     * 處理雪球命中事件 — 骷髏法師的魔法雪球造成傷害
     */
    @EventHandler
    public void onProjectileHit(ProjectileHitEvent event) {
        // === 爆裂骷髏：爆炸箭 ===
        if (event.getEntity() instanceof Arrow arrow) {
            boolean isExplosive = arrow.getPersistentDataContainer().has(
                    new org.bukkit.NamespacedKey(plugin, "explosive_arrow"),
                    org.bukkit.persistence.PersistentDataType.BOOLEAN
            );
            if (isExplosive) {
                Location hitLoc = arrow.getLocation();
                // 小範圍爆炸 (不破壞方塊)
                hitLoc.getWorld().spawnParticle(Particle.EXPLOSION, hitLoc, 2, 0.3, 0.3, 0.3, 0);
                hitLoc.getWorld().spawnParticle(Particle.FLAME, hitLoc, 15, 0.5, 0.5, 0.5, 0.05);
                hitLoc.getWorld().playSound(hitLoc, Sound.ENTITY_GENERIC_EXPLODE, 0.7f, 1.5f);

                // 計算傷害
                double damage = 5.0;
                if (arrow.getShooter() instanceof LivingEntity shooter) {
                    String mobKey = mobManager.getCustomMobKey(shooter);
                    if (mobKey != null) {
                        MobManager.MobData data = mobManager.getMobData(mobKey);
                        int level = mobManager.getMobLevel(shooter);
                        if (data != null) {
                            damage = data.calculateDamage(level) * 0.4;
                        }
                    }
                }

                // 半徑2.5格範圍傷害
                for (Entity nearby : hitLoc.getWorld().getNearbyEntities(hitLoc, 2.5, 2.5, 2.5)) {
                    if (nearby instanceof Player player) {
                        if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                        player.damage(damage);
                    }
                }
                arrow.remove();
                return;
            }
        }

        // === 骷髏法師：魔法雪球 ===
        if (!(event.getEntity() instanceof Snowball snowball)) return;

        // 檢查是否為魔法雪球
        boolean isMagic = snowball.getPersistentDataContainer().has(
                new org.bukkit.NamespacedKey(plugin, "magic_snowball"),
                org.bukkit.persistence.PersistentDataType.BOOLEAN
        );
        if (!isMagic) return;

        // 如果命中實體
        if (event.getHitEntity() instanceof Player player) {
            if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) return;

            // 計算傷害 (根據射擊者等級)
            double damage = 4.0;
            if (snowball.getShooter() instanceof LivingEntity shooter) {
                String mobKey = mobManager.getCustomMobKey(shooter);
                if (mobKey != null) {
                    MobManager.MobData mobData = mobManager.getMobData(mobKey);
                    int level = mobManager.getMobLevel(shooter);
                    if (mobData != null) {
                        damage = mobData.calculateDamage(level) * 0.6;
                    }
                }
            }

            player.damage(damage);
            player.getWorld().spawnParticle(Particle.WITCH, player.getLocation().add(0, 1, 0),
                    10, 0.3, 0.5, 0.3, 0.05);
            player.getWorld().playSound(player.getLocation(), Sound.ENTITY_PLAYER_HURT, 0.8f, 1.2f);
        }
    }

    /**
     * 潛伏蜘蛛：靠近玩家後隱形（距離8格以內）
     */
    private void stalkerStealth(LivingEntity mob) {
        Player nearest = getNearestPlayer(mob, 12.0);
        if (nearest == null) return;

        double distance = mob.getLocation().distance(nearest.getLocation());

        // 8格以內且尚未隱形 → 進入隱形
        if (distance <= 8.0 && distance > 2.0 && !mob.hasPotionEffect(PotionEffectType.INVISIBILITY)) {
            mob.addPotionEffect(new PotionEffect(PotionEffectType.INVISIBILITY, 100, 0, false, false)); // 5秒隱形
            mob.getWorld().spawnParticle(Particle.SMOKE, mob.getLocation().add(0, 0.5, 0), 10, 0.3, 0.3, 0.3, 0.02);
            mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_ILLUSIONER_MIRROR_MOVE, 0.5f, 1.5f);
        }
    }

    /**
     * 瘟疫散播者：周圍持續毒氣（半徑4格）
     */
    private void plagueAura(LivingEntity mob) {
        Location loc = mob.getLocation();

        // 毒氣粒子效果
        mob.getWorld().spawnParticle(Particle.ITEM_SLIME, loc.clone().add(0, 0.5, 0), 5, 1.5, 0.5, 1.5, 0.01);
        mob.getWorld().spawnParticle(Particle.ENTITY_EFFECT, loc.clone().add(0, 0.3, 0), 3, 1.0, 0.3, 1.0, 0);

        // 對4格內的玩家施加中毒
        for (Entity nearby : mob.getNearbyEntities(4, 4, 4)) {
            if (nearby instanceof Player player) {
                if (player.getGameMode() == org.bukkit.GameMode.CREATIVE || player.getGameMode() == org.bukkit.GameMode.SPECTATOR) continue;
                if (!player.hasPotionEffect(PotionEffectType.POISON)) {
                    player.addPotionEffect(new PotionEffect(PotionEffectType.POISON, 80, 0)); // 4秒中毒I
                }
            }
        }
    }

    /**
     * 衝鋒野獸：鎖定後直線衝刺 (更猛烈的衝撞)
     */
    private void chargeBeastAttack(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 15.0);
        if (target == null) return;

        double distance = mob.getLocation().distance(target.getLocation());
        if (distance < 4.0 || distance > 15.0) return;

        Vector direction = target.getLocation().toVector()
                .subtract(mob.getLocation().toVector()).normalize();

        // 蓄力警告 (1秒)
        mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_RAVAGER_ROAR, 1.0f, 0.8f);
        mob.getWorld().spawnParticle(Particle.ANGRY_VILLAGER, mob.getLocation().add(0, 1.5, 0), 5, 0.3, 0.3, 0.3, 0);

        new BukkitRunnable() {
            int warmup = 20; // 1秒蓄力
            int chargeTicks = 0;
            @Override
            public void run() {
                if (mob.isDead()) { cancel(); return; }

                // 蓄力階段
                if (warmup > 0) {
                    warmup -= 2;
                    mob.getWorld().spawnParticle(Particle.CLOUD, mob.getLocation().add(0, 0.5, 0),
                            2, 0.2, 0.1, 0.2, 0.01);
                    return;
                }

                // 衝刺階段
                if (chargeTicks >= 15) { cancel(); return; }

                mob.setVelocity(direction.clone().multiply(1.5).setY(0.05));
                mob.getWorld().spawnParticle(Particle.CLOUD, mob.getLocation().add(0, 0.3, 0),
                        8, 0.3, 0.1, 0.3, 0.03);
                mob.getWorld().spawnParticle(Particle.BLOCK, mob.getLocation(),
                        5, 0.3, 0.1, 0.3, 0.1, org.bukkit.Material.DIRT.createBlockData());

                // 碰撞檢測
                for (Entity nearby : mob.getNearbyEntities(1.8, 1.8, 1.8)) {
                    if (nearby instanceof Player player) {
                        if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                        // 衝撞傷害 + 擊飛
                        Vector knockback = direction.clone().multiply(1.2).setY(0.6);
                        player.setVelocity(knockback);
                        player.getWorld().playSound(player.getLocation(), Sound.ENTITY_PLAYER_HURT_SWEET_BERRY_BUSH, 1.0f, 0.5f);
                        player.getWorld().spawnParticle(Particle.CRIT, player.getLocation().add(0, 1, 0),
                                15, 0.3, 0.3, 0.3, 0.1);
                        cancel();
                        return;
                    }
                }
                chargeTicks++;
            }
        }.runTaskTimer(plugin, 0L, 2L);
    }

    // ═══════════════════════════════════════
    //  野外 Boss 專用行為
    // ═══════════════════════════════════════

    /**
     * 豬屍獸：衝撞攻擊（10秒冷卻）
     * 使用 PersistentDataContainer 儲存上次衝撞時間
     */
    private void bossZombieBeastCharge(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 18.0);
        if (target == null) return;

        double distance = mob.getLocation().distance(target.getLocation());
        if (distance < 4.0 || distance > 18.0) return;

        // 檢查冷卻 (10秒 = 10000ms)
        org.bukkit.NamespacedKey cdKey = new org.bukkit.NamespacedKey(plugin, "beast_charge_cd");
        Long lastCharge = mob.getPersistentDataContainer().get(cdKey, org.bukkit.persistence.PersistentDataType.LONG);
        long now = System.currentTimeMillis();
        if (lastCharge != null && (now - lastCharge) < 10000) return;

        // 設定冷卻
        mob.getPersistentDataContainer().set(cdKey, org.bukkit.persistence.PersistentDataType.LONG, now);

        Vector direction = target.getLocation().toVector()
                .subtract(mob.getLocation().toVector()).normalize();

        // 蓄力警告 (1.5秒)
        mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_RAVAGER_ROAR, 1.5f, 0.5f);
        mob.getWorld().spawnParticle(Particle.ANGRY_VILLAGER, mob.getLocation().add(0, 2, 0), 8, 0.4, 0.3, 0.4, 0);

        // 通知附近玩家
        for (Entity nearby : mob.getNearbyEntities(18, 18, 18)) {
            if (nearby instanceof Player p) {
                p.sendMessage(ChatColor.RED + "⚠ 豬屍獸正在蓄力衝撞！");
            }
        }

        new BukkitRunnable() {
            int warmup = 30; // 1.5秒蓄力
            int chargeTicks = 0;
            boolean hit = false;
            @Override
            public void run() {
                if (mob.isDead()) { cancel(); return; }

                // 蓄力階段 — 身體泛紅
                if (warmup > 0) {
                    warmup -= 2;
                    mob.getWorld().spawnParticle(Particle.SMOKE, mob.getLocation().add(0, 0.5, 0),
                            3, 0.3, 0.2, 0.3, 0.02);
                    mob.getWorld().spawnParticle(Particle.LAVA, mob.getLocation().add(0, 1, 0),
                            2, 0.2, 0.2, 0.2, 0);
                    return;
                }

                // 衝刺階段
                if (chargeTicks >= 20 || hit) { cancel(); return; }

                mob.setVelocity(direction.clone().multiply(1.8).setY(0.05));
                mob.getWorld().spawnParticle(Particle.CLOUD, mob.getLocation().add(0, 0.3, 0),
                        10, 0.4, 0.1, 0.4, 0.04);
                mob.getWorld().spawnParticle(Particle.BLOCK, mob.getLocation(),
                        8, 0.4, 0.1, 0.4, 0.1, org.bukkit.Material.NETHERRACK.createBlockData());

                // 碰撞檢測 — 範圍更大、傷害更高
                for (Entity nearby : mob.getNearbyEntities(2.0, 2.0, 2.0)) {
                    if (nearby instanceof Player player) {
                        if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                        // 衝撞傷害 = 怪物傷害 * 2.5
                        int level = mobManager.getMobLevel(mob);
                        String key = mobManager.getCustomMobKey(mob);
                        double chargeDmg = 10.0;
                        if (key != null) {
                            MobManager.MobData data = mobManager.getMobData(key);
                            if (data != null) chargeDmg = data.calculateDamage(level) * 2.5;
                        }
                        player.damage(chargeDmg, mob);

                        // 擊飛
                        Vector knockback = direction.clone().multiply(1.5).setY(0.7);
                        player.setVelocity(knockback);
                        player.getWorld().playSound(player.getLocation(), Sound.ENTITY_IRON_GOLEM_ATTACK, 1.5f, 0.5f);
                        player.getWorld().spawnParticle(Particle.EXPLOSION, player.getLocation().add(0, 1, 0),
                                3, 0.3, 0.3, 0.3, 0);
                        player.sendMessage(ChatColor.RED + " 你被豬屍獸衝撞擊飛了！");
                        hit = true;
                        cancel();
                        return;
                    }
                }

                // 衝撞音效
                if (chargeTicks % 3 == 0) {
                    mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_RAVAGER_STEP, 1.0f, 0.8f);
                }

                chargeTicks++;
            }
        }.runTaskTimer(plugin, 0L, 2L);
    }

    /**
     * 防止自訂怪物被陽光燃燒
     * 殭屍、骷髏等不死生物在白天會著火，取消此行為
     */
    @EventHandler
    public void onCustomMobCombust(EntityCombustEvent event) {
        if (!(event.getEntity() instanceof LivingEntity)) return;

        String mobKey = mobManager.getCustomMobKey(event.getEntity());
        if (mobKey != null) {
            // 是自訂怪物 → 取消燃燒
            event.setCancelled(true);
        }
    }
}

package com.customrpg.listeners;

import com.customrpg.CustomRPG;
import com.customrpg.managers.MobManager;
import com.customrpg.managers.PlayerStatsManager;
import com.customrpg.managers.WeaponManager;
import org.bukkit.*;
import org.bukkit.entity.*;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityCombustEvent;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.event.entity.ProjectileHitEvent;
import org.bukkit.event.entity.ProjectileLaunchEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;
import org.bukkit.projectiles.ProjectileSource;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.util.Vector;

import java.util.Random;
import java.util.UUID;

/**
 * MobListener - Handles custom mob behavior events
 *
 * This listener implements special behaviors for custom mobs such as
 * projectile attacks, death mechanics, and combat modifications.
 *
 * Handles:
 * - Snow Zombie: Throws snowballs periodically
 * - Fire Skeleton: Shoots fire arrows
 * - Giant Slime: Splits into smaller slimes on death
 */
public class MobListener implements Listener {

    private final CustomRPG plugin;
    private final MobManager mobManager;
    private final PlayerStatsManager statsManager;
    private final WeaponManager weaponManager;
    private final Random random;

    /**
     * Constructor for MobListener
     * @param plugin Main plugin instance
     * @param mobManager MobManager instance
     */
    public MobListener(CustomRPG plugin, MobManager mobManager, PlayerStatsManager statsManager, WeaponManager weaponManager) {
        this.plugin = plugin;
        this.mobManager = mobManager;
        this.statsManager = statsManager;
        this.weaponManager = weaponManager;
        this.random = new Random();
        startCustomMobBehaviors();
    }

    /**
     * Start periodic behaviors for custom mobs
     */
    private void startCustomMobBehaviors() {
        new BukkitRunnable() {
            @Override
            public void run() {
                for (org.bukkit.World world : plugin.getServer().getWorlds()) {
                    for (Entity entity : world.getEntities()) {
                        String mobKey = mobManager.getCustomMobKey(entity);
                        if (mobKey == null) continue;

                        MobManager.MobData mobData = mobManager.getMobData(mobKey);
                        if (mobData == null) continue;

                        applyPeriodicBehavior(entity, mobData);
                    }
                }
            }
        }.runTaskTimer(plugin, 0L, 60L);
    }

    /**
     * Apply periodic behaviors to custom mobs
     * @param entity The mob entity
     * @param mobData The mob data
     */
    private void applyPeriodicBehavior(Entity entity, MobManager.MobData mobData) {
        if (!(entity instanceof LivingEntity)) {
            return;
        }

        LivingEntity mob = (LivingEntity) entity;
        String behavior = mobData.getSpecialBehavior().toLowerCase();

        switch (behavior) {
            case "snowball_thrower" -> {
                if (random.nextDouble() < 0.3) {
                    throwSnowball(mob);
                }
            }
            case "snowball_mage" -> {
                // 骷髏法師：丟出傷害性雪球
                if (random.nextDouble() < 0.4) {
                    throwDamagingSnowball(mob);
                }
            }
            case "shadow_teleport" -> {
                // 影襲蜘蛛：暗影粒子 + 短距離瞬移
                // 持續噴出粒子
                Location loc = mob.getLocation().add(0, 0.5, 0);
                mob.getWorld().spawnParticle(Particle.DRIPPING_OBSIDIAN_TEAR, loc, 2, 0.3, 0.3, 0.3, 0);
                mob.getWorld().spawnParticle(Particle.SQUID_INK, loc, 1, 0.2, 0.2, 0.2, 0.01);

                // 15% 機率瞬移到附近玩家身邊
                if (random.nextDouble() < 0.15) {
                    shadowTeleport(mob);
                }
            }
            case "charge_attack" -> {
                // 狂暴野豬：直線衝撞
                if (random.nextDouble() < 0.2) {
                    chargeAttack(mob);
                }
            }
            case "flee" -> {
                // 逃跑型：看到玩家就跑
                fleeFromPlayer(mob);
            }
            case "stalker_stealth" -> {
                // 潛伏蜘蛛：靠近玩家時隱形
                stalkerStealth(mob);
            }
            case "plague_aura" -> {
                // 瘟疫散播者：周圍持續毒氣
                plagueAura(mob);
            }
            case "charge_beast" -> {
                // 衝鋒野獸：鎖定後直線衝刺
                if (random.nextDouble() < 0.2) {
                    chargeBeastAttack(mob);
                }
            }
            case "berserker_rage" -> {
                // 狂戰殭屍：低血量時發紅光粒子
                double hpPercent = mob.getHealth() / mob.getMaxHealth();
                if (hpPercent < 0.3) {
                    mob.getWorld().spawnParticle(Particle.DAMAGE_INDICATOR, mob.getLocation().add(0, 1, 0),
                            3, 0.3, 0.3, 0.3, 0.02);
                }
            }
            // ═══ 野外 Boss 行為 ═══
            case "boss_pumpkin_knight" -> {
                // 南瓜騎士：Boss 光環粒子
                mob.getWorld().spawnParticle(Particle.FLAME, mob.getLocation().add(0, 2.2, 0),
                        3, 0.2, 0.1, 0.2, 0.01);
            }
            case "boss_scissor_frenzy" -> {
                // 瘋狂剪刀手：快速揮砍粒子 + 加速
                mob.getWorld().spawnParticle(Particle.SWEEP_ATTACK, mob.getLocation().add(0, 1, 0),
                        1, 0.5, 0.3, 0.5, 0);
                if (!mob.hasPotionEffect(PotionEffectType.SPEED)) {
                    mob.addPotionEffect(new PotionEffect(PotionEffectType.SPEED, 80, 1, false, false));
                }
            }
            case "boss_zombie_beast" -> {
                // 豬屍獸：衝撞（10秒冷卻）+ Boss 粒子
                mob.getWorld().spawnParticle(Particle.LAVA, mob.getLocation().add(0, 1, 0),
                        1, 0.3, 0.3, 0.3, 0);
                bossZombieBeastCharge(mob);
            }
        }
    }

    /**
     * Handle custom mob death events
     * @param event EntityDeathEvent
     */
    @EventHandler(priority = EventPriority.HIGH)
    public void onMobDeath(EntityDeathEvent event) {
        // 排除玩家死亡
        if (event.getEntity() instanceof Player) {
            return;
        }

        Player killer = event.getEntity().getKiller();
        if (killer == null) {
            // 支援野獸擊殺：如果 killer 為 null，檢查 beast_kill_owner metadata
            if (event.getEntity().hasMetadata("beast_kill_owner")) {
                try {
                    String ownerId = event.getEntity().getMetadata("beast_kill_owner").get(0).asString();
                    Player owner = Bukkit.getPlayer(UUID.fromString(ownerId));
                    if (owner != null && owner.isOnline()) {
                        killer = owner;
                    }
                } catch (Exception ignored) {}
            }
        }

        String mobKey = mobManager.getCustomMobKey(event.getEntity());

        // 如果是自製怪物
        if (mobKey != null) {
            MobManager.MobData mobData = mobManager.getMobData(mobKey);
            if (mobData == null) {
                return;
            }

            // 沒有擊殺者（例如跌落死亡），跳過獎勵
            if (killer == null) {
                return;
            }

            int mobLevel = mobManager.getMobLevel(event.getEntity());

            // Handle custom mob drops or effects
            // For example, splitting slimes
            if (mobData.getSpecialBehavior().equalsIgnoreCase("split_on_death")) {
                splitSlime(event.getEntity(), mobData);
            }

            // 黏液爆破者：延遲爆炸
            if (mobData.getSpecialBehavior().equalsIgnoreCase("delayed_explosion")) {
                delayedExplosion(event.getEntity().getLocation(), mobLevel);
            }

            // 清除預設掉落物（如果有自定義掉落物）
            if (!mobData.getVanillaDrops().isEmpty() || !mobData.getWeaponDrops().isEmpty() || !mobData.getEquipmentDrops().isEmpty()) {
                event.getDrops().clear();

                // 掉落原版物品
                for (MobManager.DropItem dropItem : mobData.getVanillaDrops()) {
                    if (random.nextDouble() < dropItem.getChance()) {
                        int amount = dropItem.getMinAmount();
                        if (dropItem.getMaxAmount() > dropItem.getMinAmount()) {
                            amount = random.nextInt(dropItem.getMaxAmount() - dropItem.getMinAmount() + 1) + dropItem.getMinAmount();
                        }
                        event.getDrops().add(new ItemStack(dropItem.getMaterial(), amount));
                    }
                }

                // 掉落自定義武器
                for (MobManager.WeaponDrop weaponDrop : mobData.getWeaponDrops()) {
                    if (random.nextDouble() < weaponDrop.getChance()) {
                        ItemStack weapon = weaponManager.createWeapon(weaponDrop.getWeaponKey());
                        if (weapon != null) {
                            event.getDrops().add(weapon);
                            killer.sendMessage(ChatColor.GOLD + "★ 獲得稀有武器: " + weapon.getItemMeta().getDisplayName());
                        }
                    }
                }

                // 掉落自定義裝備 (飾品 / 裝甲)
                for (MobManager.EquipmentDrop equipDrop : mobData.getEquipmentDrops()) {
                    if (random.nextDouble() < equipDrop.getChance()) {
                        ItemStack dropItem = null;
                        if ("armor".equalsIgnoreCase(equipDrop.getType())) {
                            // 裝甲掉落
                            com.customrpg.equipment.ArmorManager armorMgr = plugin.getArmorManager();
                            if (armorMgr != null) {
                                com.customrpg.equipment.ArmorData armor = armorMgr.createArmor(equipDrop.getEquipmentKey());
                                if (armor != null) {
                                    dropItem = armor.toItemStack();
                                }
                            }
                        } else {
                            // 飾品掉落
                            com.customrpg.equipment.EquipmentManager equipMgr = plugin.getEquipmentManager();
                            if (equipMgr != null) {
                                com.customrpg.equipment.EquipmentData equip = equipMgr.createEquipment(equipDrop.getEquipmentKey());
                                if (equip != null) {
                                    dropItem = equip.toItemStack();
                                }
                            }
                        }
                        if (dropItem != null) {
                            event.getDrops().add(dropItem);
                            String itemName = dropItem.hasItemMeta() && dropItem.getItemMeta().hasDisplayName()
                                    ? dropItem.getItemMeta().getDisplayName()
                                    : equipDrop.getEquipmentKey();
                            killer.sendMessage(ChatColor.LIGHT_PURPLE + "★ 獲得稀有裝備: " + itemName);
                        }
                    }
                }
            }

            // 給予經驗值（基於等級 + 階級倍率 + 等級差距調整）
            int baseExpReward = mobData.calculateExp(mobLevel);

            // 階級經驗倍率：普通 x1, 精英 x2.5, Boss x5
            String mobTier = mobManager.getMobTier(event.getEntity());
            double tierMultiplier = switch (mobTier) {
                case "ELITE" -> 2.5;
                case "BOSS" -> 5.0;
                default -> 1.0;
            };

            // 等級差距調整：怪物等級比玩家高 → 加成，比玩家低太多 → 減少
            com.customrpg.players.PlayerStats killerStats = statsManager.getStats(killer);
            int playerLevel = killerStats.getLevel();
            int levelDiff = mobLevel - playerLevel;
            double levelMultiplier;
            if (levelDiff >= 5) {
                levelMultiplier = 1.5;  // 怪物比玩家高 5 級以上 → +50%
            } else if (levelDiff >= 0) {
                levelMultiplier = 1.0 + (levelDiff * 0.05); // 每高 1 級 +5%
            } else if (levelDiff >= -5) {
                levelMultiplier = 1.0;  // 低 1~5 級 → 正常
            } else if (levelDiff >= -10) {
                levelMultiplier = 0.5;  // 低 6~10 級 → 50%
            } else {
                levelMultiplier = 0.1;  // 低 10 級以上 → 10%（防止刷低等怪）
            }

            int finalExp = Math.max(1, (int) (baseExpReward * tierMultiplier * levelMultiplier));
            if (finalExp > 0) {
                statsManager.addExp(killer, finalExp);

                // 根據階級顯示不同顏色的訊息
                String tierTag = switch (mobTier) {
                    case "ELITE" -> ChatColor.GOLD + "[精英] ";
                    case "BOSS" -> ChatColor.RED + "[BOSS] ";
                    default -> "";
                };

                killer.sendMessage(ChatColor.YELLOW + "擊敗 " + tierTag +
                    ChatColor.YELLOW + "[Lv." + mobLevel + "] " +
                    ChatColor.stripColor(mobData.getName()) + " 獲得 " +
                    ChatColor.GREEN + finalExp + ChatColor.YELLOW + " 經驗值" +
                    (tierMultiplier > 1.0 ? ChatColor.GOLD + " (x" + tierMultiplier + ")" : ""));
            }

            // 移除 BossBar
            com.customrpg.managers.BossBarManager bossBarMgr = plugin.getBossBarManager();
            if (bossBarMgr != null) {
                bossBarMgr.onMobDeath(event.getEntity().getUniqueId());
            }

            com.customrpg.managers.BossZoneManager bossZoneManager = plugin.getBossZoneManager();
            if (bossZoneManager != null) {
                bossZoneManager.handleEntityDeath(event.getEntity());
            }
        } else {
            // 普通原版怪物：依類型給予不同經驗值
            if (killer == null) return; // 無擊殺者（跌落、其他原因死亡）
            int vanillaExp = switch (event.getEntity().getType()) {
                case ENDER_DRAGON -> 500;
                case WITHER -> 300;
                case ELDER_GUARDIAN -> 80;
                case WARDEN -> 100;
                case RAVAGER -> 50;
                case EVOKER, VINDICATOR -> 20;
                case GHAST, BLAZE, GUARDIAN -> 15;
                case ENDERMAN, PIGLIN_BRUTE -> 10;
                case CREEPER, SKELETON, ZOMBIE, SPIDER -> 5;
                case SLIME, MAGMA_CUBE -> 3;
                default -> 2;
            };
            statsManager.addExp(killer, vanillaExp);
            killer.sendMessage(ChatColor.YELLOW + "獲得 " + vanillaExp + " 經驗值");
        }
    }

    /**
     * Handle custom mob damage events (level-scaled damage)
     * 處理玩家攻擊 BlockDisplay 偽裝系統的情況
     * @param event EntityDamageByEntityEvent
     */
    @EventHandler
    public void onMobAttack(EntityDamageByEntityEvent event) {
        // === 情況 1：玩家攻擊 BlockDisplay 或名稱標籤 ArmorStand ===
        // BlockDisplay 和 ArmorStand 不是 LivingEntity，需要找到對應的隱形核心
        if (event.getDamager() instanceof Player player) {
            Entity target = event.getEntity();

            // 檢查是否攻擊到 BlockDisplay
            if (target instanceof org.bukkit.entity.BlockDisplay) {
                event.setCancelled(true); // 取消對 BlockDisplay 的傷害

                // 從 BlockDisplay 的 PersistentData 獲取核心 UUID
                String coreUuidString = target.getPersistentDataContainer().get(
                    new org.bukkit.NamespacedKey(plugin, "disguise_blockdisplay"),
                    org.bukkit.persistence.PersistentDataType.STRING
                );

                if (coreUuidString != null) {
                    java.util.UUID coreUuid = java.util.UUID.fromString(coreUuidString);
                    // 在同一世界中尋找核心實體
                    for (Entity entity : target.getWorld().getEntities()) {
                        if (entity.getUniqueId().equals(coreUuid) && entity instanceof LivingEntity core) {
                            // 找到核心，對其造成傷害

                            // 計算傷害（考慮玩家的武器）
                            double damage = 1.0;
                            ItemStack weapon = player.getInventory().getItemInMainHand();
                            if (weapon != null && !weapon.getType().isAir()) {
                                // 這裡可以加入自定義武器傷害計算
                                damage = weaponManager.getBaseDamage(weapon);
                            }

                            core.damage(damage, player);
                            plugin.getLogger().fine("玩家攻擊 BlockDisplay，轉移 " + damage + " 傷害到核心");
                            return;
                        }
                    }
                }
            }

            // 檢查是否攻擊到名稱標籤 ArmorStand
            if (target instanceof ArmorStand armorStand) {
                String coreUuidString = armorStand.getPersistentDataContainer().get(
                    new org.bukkit.NamespacedKey(plugin, "disguise_nametag"),
                    org.bukkit.persistence.PersistentDataType.STRING
                );

                if (coreUuidString != null) {
                    event.setCancelled(true); // 取消對 ArmorStand 的傷害

                    java.util.UUID coreUuid = java.util.UUID.fromString(coreUuidString);
                    // 在同一世界中尋找核心實體
                    for (Entity entity : target.getWorld().getEntities()) {
                        if (entity.getUniqueId().equals(coreUuid) && entity instanceof LivingEntity core) {
                            // 找到核心，對其造成傷害

                            // 計算傷害
                            double damage = 1.0;
                            ItemStack weapon = player.getInventory().getItemInMainHand();
                            if (weapon != null && !weapon.getType().isAir()) {
                                damage = weaponManager.getBaseDamage(weapon);
                            }

                            core.damage(damage, player);
                            plugin.getLogger().fine("玩家攻擊名稱標籤，轉移 " + damage + " 傷害到核心");
                            return;
                        }
                    }
                }
            }
        }

        // === 情況 1.5：玩家攻擊自訂 Boss 怪物（特殊防禦機制）===
        if (event.getDamager() instanceof Player player && event.getEntity() instanceof LivingEntity target) {
            String targetMobKey = mobManager.getCustomMobKey(target);
            if (targetMobKey != null) {
                MobManager.MobData targetData = mobManager.getMobData(targetMobKey);
                if (targetData != null) {
                    // 南瓜騎士：35% 格擋 → 減傷60%
                    if (targetData.getSpecialBehavior().equalsIgnoreCase("boss_pumpkin_knight")) {
                        if (random.nextDouble() < 0.35) {
                            event.setDamage(event.getDamage() * 0.4);
                            target.getWorld().spawnParticle(Particle.ENCHANTED_HIT, target.getLocation().add(0, 1, 0),
                                    10, 0.3, 0.3, 0.3, 0.05);
                            target.getWorld().playSound(target.getLocation(), Sound.ITEM_SHIELD_BLOCK, 1.0f, 1.0f);
                            player.sendMessage(ChatColor.YELLOW + " 南瓜騎士格擋了你的攻擊！");
                        }
                    }
                }

                // BossBar 顯示：玩家攻擊自訂怪物時顯示血量條
                com.customrpg.managers.BossBarManager bossBarMgr = plugin.getBossBarManager();
                if (bossBarMgr != null) {
                    // 延遲1tick更新，讓傷害先生效
                    new BukkitRunnable() {
                        @Override
                        public void run() {
                            if (!target.isDead()) {
                                bossBarMgr.onMobDamaged(target);
                            }
                        }
                    }.runTaskLater(plugin, 1L);
                }
            }
        }

        // === 情況 2：自定義生物攻擊玩家（等級化傷害）===
        // 檢查是否為自定義生物攻擊玩家
        if (!(event.getDamager() instanceof LivingEntity)) {
            return;
        }

        if (!(event.getEntity() instanceof Player)) {
            return;
        }

        LivingEntity attacker = (LivingEntity) event.getDamager();
        String mobKey = mobManager.getCustomMobKey(attacker);

        if (mobKey == null) {
            return;
        }

        MobManager.MobData mobData = mobManager.getMobData(mobKey);
        if (mobData == null) {
            return;
        }

        // 獲取生物等級並計算傷害
        int mobLevel = mobManager.getMobLevel(attacker);
        double scaledDamage = mobData.calculateDamage(mobLevel);

        // 狂戰殭屍：HP < 30% → +50% 傷害
        if (mobData.getSpecialBehavior().equalsIgnoreCase("berserker_rage")) {
            double hpPercent = attacker.getHealth() / attacker.getMaxHealth();
            if (hpPercent < 0.3) {
                scaledDamage *= 1.5;
                attacker.getWorld().spawnParticle(Particle.DAMAGE_INDICATOR, attacker.getLocation().add(0, 1.5, 0),
                        8, 0.3, 0.3, 0.3, 0.05);
                attacker.getWorld().playSound(attacker.getLocation(), Sound.ENTITY_RAVAGER_ROAR, 0.4f, 1.5f);
            }
        }

        // 潛伏蜘蛛：隱形狀態下第一擊 +80% 傷害
        if (mobData.getSpecialBehavior().equalsIgnoreCase("stalker_stealth")) {
            if (attacker.hasPotionEffect(PotionEffectType.INVISIBILITY)) {
                scaledDamage *= 1.8;
                attacker.removePotionEffect(PotionEffectType.INVISIBILITY);
                attacker.getWorld().spawnParticle(Particle.CRIT, attacker.getLocation().add(0, 1, 0),
                        15, 0.3, 0.3, 0.3, 0.1);
                attacker.getWorld().playSound(attacker.getLocation(), Sound.ENTITY_PLAYER_ATTACK_CRIT, 1.0f, 1.0f);
            }
        }

        // 設置等級化傷害（對於偽裝生物，確保傷害大於0）
        if (scaledDamage < 1.0) {
            scaledDamage = 1.0; // 最低傷害為 1
        }
        event.setDamage(scaledDamage);

        // 冰霜殭屍：攻擊附帶緩速
        if (mobData.getSpecialBehavior().equalsIgnoreCase("frost_attack")) {
            if (event.getEntity() instanceof Player victim) {
                victim.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS, 60, 1)); // 3秒 緩速II
                victim.getWorld().spawnParticle(Particle.SNOWFLAKE, victim.getLocation().add(0, 1, 0),
                        10, 0.3, 0.5, 0.3, 0.02);
                victim.getWorld().playSound(victim.getLocation(), Sound.BLOCK_GLASS_BREAK, 0.5f, 1.8f);
            }
        }

        // ═══ 南瓜騎士：30% 重擊（2倍傷害 + 擊退） ═══
        if (mobData.getSpecialBehavior().equalsIgnoreCase("boss_pumpkin_knight")) {
            if (random.nextDouble() < 0.3) {
                scaledDamage *= 2.0;
                event.setDamage(scaledDamage);
                if (event.getEntity() instanceof Player victim) {
                    Vector knockback = attacker.getLocation().getDirection().normalize().multiply(1.0).setY(0.4);
                    victim.setVelocity(knockback);
                    attacker.getWorld().playSound(attacker.getLocation(), Sound.ENTITY_IRON_GOLEM_ATTACK, 1.0f, 0.6f);
                    attacker.getWorld().spawnParticle(Particle.CRIT, victim.getLocation().add(0, 1, 0),
                            20, 0.3, 0.3, 0.3, 0.1);
                    victim.sendMessage(ChatColor.RED + "⚔ 南瓜騎士使出了重擊！");
                }
            }
        }

        // ═══ 瘋狂剪刀手：每次攻擊附帶流血（凋零 1 秒）+ 雙重攻擊（40% 機率連擊）═══
        if (mobData.getSpecialBehavior().equalsIgnoreCase("boss_scissor_frenzy")) {
            if (event.getEntity() instanceof Player victim) {
                // 流血
                victim.addPotionEffect(new PotionEffect(PotionEffectType.WITHER, 20, 0, false, true)); // 1秒凋零
                attacker.getWorld().spawnParticle(Particle.DAMAGE_INDICATOR, victim.getLocation().add(0, 1, 0),
                        5, 0.2, 0.3, 0.2, 0.02);
                attacker.getWorld().playSound(attacker.getLocation(), Sound.ENTITY_PLAYER_ATTACK_SWEEP, 1.0f, 1.5f);

                // 40% 連擊（延遲 5 tick 再打一下）
                if (random.nextDouble() < 0.4) {
                    final double comboDamage = scaledDamage * 0.6;
                    new BukkitRunnable() {
                        @Override
                        public void run() {
                            if (attacker.isDead() || victim.isDead()) return;
                            if (attacker.getLocation().distance(victim.getLocation()) > 4) return;
                            victim.damage(comboDamage, attacker);
                            attacker.getWorld().spawnParticle(Particle.SWEEP_ATTACK, victim.getLocation().add(0, 1, 0),
                                    3, 0.3, 0.3, 0.3, 0);
                            attacker.getWorld().playSound(victim.getLocation(), Sound.ENTITY_PLAYER_ATTACK_SWEEP, 0.8f, 1.8f);
                        }
                    }.runTaskLater(plugin, 5L);
                }
            }
        }

        // Debug 訊息
        plugin.getLogger().info("Custom mob " + mobData.getName() + " (Lv." + mobLevel + ") attacked player with " + scaledDamage + " damage");
    }

    /**
     * Split a giant slime into smaller ones
     * @param entity The dying entity
     * @param mobData The mob data
     */
    private void splitSlime(LivingEntity entity, MobManager.MobData mobData) {
        Location location = entity.getLocation();

        for (int i = 0; i < 4; i++) {
            Slime smallSlime = (Slime) location.getWorld().spawnEntity(location, EntityType.SLIME);
            smallSlime.setSize(1);

            Vector velocity = new Vector(
                random.nextDouble() - 0.5,
                0.5,
                random.nextDouble() - 0.5
            ).normalize().multiply(0.5);
            smallSlime.setVelocity(velocity);
        }
    }

    /**
     * Handle projectile launch events for custom mobs
     * @param event ProjectileLaunchEvent
     */
    @EventHandler
    public void onProjectileLaunch(ProjectileLaunchEvent event) {
        ProjectileSource shooter = event.getEntity().getShooter();
        if (!(shooter instanceof LivingEntity)) {
            return;
        }

        LivingEntity mob = (LivingEntity) shooter;
        String mobKey = mobManager.getCustomMobKey(mob);
        if (mobKey == null) {
            return;
        }

        MobManager.MobData mobData = mobManager.getMobData(mobKey);
        if (mobData == null) {
            return;
        }

        if (mobData.getSpecialBehavior().equalsIgnoreCase("fire_arrows")) {
            if (event.getEntity() instanceof Arrow) {
                Arrow arrow = (Arrow) event.getEntity();
                arrow.setFireTicks(1000);
            }
        }

        // 爆裂骷髏：標記箭矢為爆炸箭
        if (mobData.getSpecialBehavior().equalsIgnoreCase("explosive_arrow")) {
            if (event.getEntity() instanceof Arrow arrow) {
                arrow.getPersistentDataContainer().set(
                        new org.bukkit.NamespacedKey(plugin, "explosive_arrow"),
                        org.bukkit.persistence.PersistentDataType.BOOLEAN, true
                );
                // 火焰軌跡視覺提示
                arrow.setFireTicks(200);
            }
        }
    }

    /**
     * Throw a snowball from the mob
     * @param mob The mob entity
     */
    private void throwSnowball(LivingEntity mob) {
        Player nearestPlayer = getNearestPlayer(mob, 15.0);
        if (nearestPlayer == null) {
            return;
        }

        Location mobLocation = mob.getEyeLocation();
        Location playerLocation = nearestPlayer.getEyeLocation();

        Vector direction = playerLocation.toVector().subtract(mobLocation.toVector()).normalize();

        Snowball snowball = (Snowball) mob.getWorld().spawnEntity(mobLocation, EntityType.SNOWBALL);
        snowball.setVelocity(direction.multiply(1.5));
        snowball.setShooter(mob);
    }

    /**
     * Get the nearest player to a mob within range
     * @param mob The mob entity
     * @param range The search range
     * @return The nearest player or null
     */
    private Player getNearestPlayer(LivingEntity mob, double range) {
        Player nearest = null;
        double nearestDistance = range;

        for (Entity entity : mob.getNearbyEntities(range, range, range)) {
            if (entity instanceof Player player) {
                if (player.getGameMode() == org.bukkit.GameMode.CREATIVE || player.getGameMode() == org.bukkit.GameMode.SPECTATOR) continue;
                double distance = mob.getLocation().distance(player.getLocation());
                if (distance < nearestDistance) {
                    nearest = player;
                    nearestDistance = distance;
                }
            }
        }

        return nearest;
    }

    // ═══════════════════════════════════════
    //  新增特殊行為
    // ═══════════════════════════════════════

    /**
     * 黏液爆破者：死亡2秒後小範圍爆炸
     */
    private void delayedExplosion(Location deathLocation, int mobLevel) {
        // 生成粒子警告
        new BukkitRunnable() {
            int ticks = 0;
            @Override
            public void run() {
                if (ticks >= 40) { // 2秒 = 40 ticks
                    // 爆炸！
                    deathLocation.getWorld().spawnParticle(Particle.EXPLOSION, deathLocation, 3, 0.5, 0.5, 0.5, 0);
                    deathLocation.getWorld().spawnParticle(Particle.HAPPY_VILLAGER, deathLocation, 30, 1.5, 1.0, 1.5, 0.1);
                    deathLocation.getWorld().playSound(deathLocation, Sound.ENTITY_GENERIC_EXPLODE, 1.0f, 1.5f);

                    // 對範圍內玩家造成傷害（半徑3格）
                    double damage = 5.0 + mobLevel * 1.5;
                    for (Entity entity : deathLocation.getWorld().getNearbyEntities(deathLocation, 3, 3, 3)) {
                        if (entity instanceof Player player) {
                            if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                            player.damage(damage);
                            player.sendMessage(ChatColor.RED + " 你被黏液爆炸波及了！");
                        }
                    }
                    cancel();
                    return;
                }
                // 警告粒子 (越來越密集)
                int particleCount = 3 + (ticks / 10);
                deathLocation.getWorld().spawnParticle(Particle.FLAME, deathLocation.clone().add(0, 0.5, 0),
                        particleCount, 0.3, 0.3, 0.3, 0.02);
                if (ticks % 10 == 0) {
                    deathLocation.getWorld().playSound(deathLocation, Sound.BLOCK_NOTE_BLOCK_BASS, 0.8f, 0.5f + (ticks / 40f));
                }
                ticks += 5;
            }
        }.runTaskTimer(plugin, 0L, 5L);
    }

    /**
     * 影襲蜘蛛：短距離瞬移到玩家附近
     */
    private void shadowTeleport(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 12.0);
        if (target == null) return;

        Location playerLoc = target.getLocation();
        // 隨機在玩家周圍 2~4 格瞬移
        double angle = random.nextDouble() * Math.PI * 2;
        double dist = 2.0 + random.nextDouble() * 2.0;
        Location teleportLoc = playerLoc.clone().add(Math.cos(angle) * dist, 0, Math.sin(angle) * dist);

        // 確保目標位置安全
        teleportLoc.setY(teleportLoc.getWorld().getHighestBlockYAt(teleportLoc) + 1);

        // 起點粒子效果
        Location fromLoc = mob.getLocation();
        fromLoc.getWorld().spawnParticle(Particle.SQUID_INK, fromLoc.clone().add(0, 0.5, 0), 15, 0.3, 0.5, 0.3, 0.05);
        fromLoc.getWorld().spawnParticle(Particle.DRIPPING_OBSIDIAN_TEAR, fromLoc.clone().add(0, 1, 0), 10, 0.4, 0.6, 0.4, 0);
        fromLoc.getWorld().playSound(fromLoc, Sound.ENTITY_ENDERMAN_TELEPORT, 0.6f, 1.5f);

        // 瞬移
        mob.teleport(teleportLoc);

        // 終點粒子效果
        teleportLoc.getWorld().spawnParticle(Particle.SQUID_INK, teleportLoc.clone().add(0, 0.5, 0), 15, 0.3, 0.5, 0.3, 0.05);
        teleportLoc.getWorld().spawnParticle(Particle.DRIPPING_OBSIDIAN_TEAR, teleportLoc.clone().add(0, 1, 0), 10, 0.4, 0.6, 0.4, 0);
        teleportLoc.getWorld().playSound(teleportLoc, Sound.ENTITY_ENDERMAN_TELEPORT, 0.6f, 1.8f);
    }

    /**
     * 狂暴野豬：直線衝撞
     */
    private void chargeAttack(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 10.0);
        if (target == null) return;

        double distance = mob.getLocation().distance(target.getLocation());
        if (distance < 3.0 || distance > 10.0) return; // 太近或太遠不衝

        // 衝撞方向
        Vector direction = target.getLocation().toVector()
                .subtract(mob.getLocation().toVector()).normalize();

        // 播放音效
        mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_RAVAGER_ROAR, 0.5f, 1.5f);

        // 衝撞動畫 (粒子軌跡)
        new BukkitRunnable() {
            int ticks = 0;
            @Override
            public void run() {
                if (ticks >= 10 || mob.isDead()) {
                    cancel();
                    return;
                }
                mob.setVelocity(direction.clone().multiply(1.2).setY(0.05));
                mob.getWorld().spawnParticle(Particle.CLOUD, mob.getLocation().add(0, 0.3, 0),
                        5, 0.2, 0.1, 0.2, 0.02);

                // 碰到玩家就擊退
                for (Entity nearby : mob.getNearbyEntities(1.5, 1.5, 1.5)) {
                    if (nearby instanceof Player player) {
                        if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                        Vector knockback = direction.clone().multiply(0.8).setY(0.4);
                        player.setVelocity(knockback);
                        player.getWorld().playSound(player.getLocation(), Sound.ENTITY_PLAYER_HURT, 1.0f, 0.8f);
                        cancel();
                        return;
                    }
                }
                ticks++;
            }
        }.runTaskTimer(plugin, 0L, 2L);
    }

    /**
     * 逃跑型：遠離玩家
     */
    private void fleeFromPlayer(LivingEntity mob) {
        Player nearest = getNearestPlayer(mob, 8.0);
        if (nearest == null) return;

        // 計算遠離方向
        Vector away = mob.getLocation().toVector()
                .subtract(nearest.getLocation().toVector()).normalize();
        away.setY(0).normalize().multiply(0.5);
        if (random.nextDouble() < 0.3) {
            away.setY(0.2); // 偶爾跳一下
        }
        mob.setVelocity(away);
    }

    /**
     * 骷髏法師：丟出傷害性雪球（標記為魔法雪球）
     */
    private void throwDamagingSnowball(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 15.0);
        if (target == null) return;

        Location mobLoc = mob.getEyeLocation();
        Vector direction = target.getEyeLocation().toVector()
                .subtract(mobLoc.toVector()).normalize();

        Snowball snowball = mob.getWorld().spawn(mobLoc, Snowball.class);
        snowball.setVelocity(direction.multiply(1.2));
        snowball.setShooter(mob);

        // 標記這顆雪球為魔法雪球
        snowball.getPersistentDataContainer().set(
                new org.bukkit.NamespacedKey(plugin, "magic_snowball"),
                org.bukkit.persistence.PersistentDataType.BOOLEAN, true
        );

        // 紫色粒子
        mob.getWorld().spawnParticle(Particle.WITCH, mobLoc, 5, 0.2, 0.2, 0.2, 0.05);
        mob.getWorld().playSound(mobLoc, Sound.ENTITY_SNOWBALL_THROW, 1.0f, 0.6f);
    }

    /**
     * 處理雪球命中事件 — 骷髏法師的魔法雪球造成傷害
     */
    @EventHandler
    public void onProjectileHit(ProjectileHitEvent event) {
        // === 爆裂骷髏：爆炸箭 ===
        if (event.getEntity() instanceof Arrow arrow) {
            boolean isExplosive = arrow.getPersistentDataContainer().has(
                    new org.bukkit.NamespacedKey(plugin, "explosive_arrow"),
                    org.bukkit.persistence.PersistentDataType.BOOLEAN
            );
            if (isExplosive) {
                Location hitLoc = arrow.getLocation();
                // 小範圍爆炸 (不破壞方塊)
                hitLoc.getWorld().spawnParticle(Particle.EXPLOSION, hitLoc, 2, 0.3, 0.3, 0.3, 0);
                hitLoc.getWorld().spawnParticle(Particle.FLAME, hitLoc, 15, 0.5, 0.5, 0.5, 0.05);
                hitLoc.getWorld().playSound(hitLoc, Sound.ENTITY_GENERIC_EXPLODE, 0.7f, 1.5f);

                // 計算傷害
                double damage = 5.0;
                if (arrow.getShooter() instanceof LivingEntity shooter) {
                    String mobKey = mobManager.getCustomMobKey(shooter);
                    if (mobKey != null) {
                        MobManager.MobData data = mobManager.getMobData(mobKey);
                        int level = mobManager.getMobLevel(shooter);
                        if (data != null) {
                            damage = data.calculateDamage(level) * 0.4;
                        }
                    }
                }

                // 半徑2.5格範圍傷害
                for (Entity nearby : hitLoc.getWorld().getNearbyEntities(hitLoc, 2.5, 2.5, 2.5)) {
                    if (nearby instanceof Player player) {
                        if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                        player.damage(damage);
                    }
                }
                arrow.remove();
                return;
            }
        }

        // === 骷髏法師：魔法雪球 ===
        if (!(event.getEntity() instanceof Snowball snowball)) return;

        // 檢查是否為魔法雪球
        boolean isMagic = snowball.getPersistentDataContainer().has(
                new org.bukkit.NamespacedKey(plugin, "magic_snowball"),
                org.bukkit.persistence.PersistentDataType.BOOLEAN
        );
        if (!isMagic) return;

        // 如果命中實體
        if (event.getHitEntity() instanceof Player player) {
            if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) return;

            // 計算傷害 (根據射擊者等級)
            double damage = 4.0;
            if (snowball.getShooter() instanceof LivingEntity shooter) {
                String mobKey = mobManager.getCustomMobKey(shooter);
                if (mobKey != null) {
                    MobManager.MobData mobData = mobManager.getMobData(mobKey);
                    int level = mobManager.getMobLevel(shooter);
                    if (mobData != null) {
                        damage = mobData.calculateDamage(level) * 0.6;
                    }
                }
            }

            player.damage(damage);
            player.getWorld().spawnParticle(Particle.WITCH, player.getLocation().add(0, 1, 0),
                    10, 0.3, 0.5, 0.3, 0.05);
            player.getWorld().playSound(player.getLocation(), Sound.ENTITY_PLAYER_HURT, 0.8f, 1.2f);
        }
    }

    /**
     * 潛伏蜘蛛：靠近玩家後隱形（距離8格以內）
     */
    private void stalkerStealth(LivingEntity mob) {
        Player nearest = getNearestPlayer(mob, 12.0);
        if (nearest == null) return;

        double distance = mob.getLocation().distance(nearest.getLocation());

        // 8格以內且尚未隱形 → 進入隱形
        if (distance <= 8.0 && distance > 2.0 && !mob.hasPotionEffect(PotionEffectType.INVISIBILITY)) {
            mob.addPotionEffect(new PotionEffect(PotionEffectType.INVISIBILITY, 100, 0, false, false)); // 5秒隱形
            mob.getWorld().spawnParticle(Particle.SMOKE, mob.getLocation().add(0, 0.5, 0), 10, 0.3, 0.3, 0.3, 0.02);
            mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_ILLUSIONER_MIRROR_MOVE, 0.5f, 1.5f);
        }
    }

    /**
     * 瘟疫散播者：周圍持續毒氣（半徑4格）
     */
    private void plagueAura(LivingEntity mob) {
        Location loc = mob.getLocation();

        // 毒氣粒子效果
        mob.getWorld().spawnParticle(Particle.ITEM_SLIME, loc.clone().add(0, 0.5, 0), 5, 1.5, 0.5, 1.5, 0.01);
        mob.getWorld().spawnParticle(Particle.ENTITY_EFFECT, loc.clone().add(0, 0.3, 0), 3, 1.0, 0.3, 1.0, 0);

        // 對4格內的玩家施加中毒
        for (Entity nearby : mob.getNearbyEntities(4, 4, 4)) {
            if (nearby instanceof Player player) {
                if (player.getGameMode() == org.bukkit.GameMode.CREATIVE || player.getGameMode() == org.bukkit.GameMode.SPECTATOR) continue;
                if (!player.hasPotionEffect(PotionEffectType.POISON)) {
                    player.addPotionEffect(new PotionEffect(PotionEffectType.POISON, 80, 0)); // 4秒中毒I
                }
            }
        }
    }

    /**
     * 衝鋒野獸：鎖定後直線衝刺 (更猛烈的衝撞)
     */
    private void chargeBeastAttack(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 15.0);
        if (target == null) return;

        double distance = mob.getLocation().distance(target.getLocation());
        if (distance < 4.0 || distance > 15.0) return;

        Vector direction = target.getLocation().toVector()
                .subtract(mob.getLocation().toVector()).normalize();

        // 蓄力警告 (1秒)
        mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_RAVAGER_ROAR, 1.0f, 0.8f);
        mob.getWorld().spawnParticle(Particle.ANGRY_VILLAGER, mob.getLocation().add(0, 1.5, 0), 5, 0.3, 0.3, 0.3, 0);

        new BukkitRunnable() {
            int warmup = 20; // 1秒蓄力
            int chargeTicks = 0;
            @Override
            public void run() {
                if (mob.isDead()) { cancel(); return; }

                // 蓄力階段
                if (warmup > 0) {
                    warmup -= 2;
                    mob.getWorld().spawnParticle(Particle.CLOUD, mob.getLocation().add(0, 0.5, 0),
                            2, 0.2, 0.1, 0.2, 0.01);
                    return;
                }

                // 衝刺階段
                if (chargeTicks >= 15) { cancel(); return; }

                mob.setVelocity(direction.clone().multiply(1.5).setY(0.05));
                mob.getWorld().spawnParticle(Particle.CLOUD, mob.getLocation().add(0, 0.3, 0),
                        8, 0.3, 0.1, 0.3, 0.03);
                mob.getWorld().spawnParticle(Particle.BLOCK, mob.getLocation(),
                        5, 0.3, 0.1, 0.3, 0.1, org.bukkit.Material.DIRT.createBlockData());

                // 碰撞檢測
                for (Entity nearby : mob.getNearbyEntities(1.8, 1.8, 1.8)) {
                    if (nearby instanceof Player player) {
                        if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                        // 衝撞傷害 + 擊飛
                        Vector knockback = direction.clone().multiply(1.2).setY(0.6);
                        player.setVelocity(knockback);
                        player.getWorld().playSound(player.getLocation(), Sound.ENTITY_PLAYER_HURT_SWEET_BERRY_BUSH, 1.0f, 0.5f);
                        player.getWorld().spawnParticle(Particle.CRIT, player.getLocation().add(0, 1, 0),
                                15, 0.3, 0.3, 0.3, 0.1);
                        cancel();
                        return;
                    }
                }
                chargeTicks++;
            }
        }.runTaskTimer(plugin, 0L, 2L);
    }

    // ═══════════════════════════════════════
    //  野外 Boss 專用行為
    // ═══════════════════════════════════════

    /**
     * 豬屍獸：衝撞攻擊（10秒冷卻）
     * 使用 PersistentDataContainer 儲存上次衝撞時間
     */
    private void bossZombieBeastCharge(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 18.0);
        if (target == null) return;

        double distance = mob.getLocation().distance(target.getLocation());
        if (distance < 4.0 || distance > 18.0) return;

        // 檢查冷卻 (10秒 = 10000ms)
        org.bukkit.NamespacedKey cdKey = new org.bukkit.NamespacedKey(plugin, "beast_charge_cd");
        Long lastCharge = mob.getPersistentDataContainer().get(cdKey, org.bukkit.persistence.PersistentDataType.LONG);
        long now = System.currentTimeMillis();
        if (lastCharge != null && (now - lastCharge) < 10000) return;

        // 設定冷卻
        mob.getPersistentDataContainer().set(cdKey, org.bukkit.persistence.PersistentDataType.LONG, now);

        Vector direction = target.getLocation().toVector()
                .subtract(mob.getLocation().toVector()).normalize();

        // 蓄力警告 (1.5秒)
        mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_RAVAGER_ROAR, 1.5f, 0.5f);
        mob.getWorld().spawnParticle(Particle.ANGRY_VILLAGER, mob.getLocation().add(0, 2, 0), 8, 0.4, 0.3, 0.4, 0);

        // 通知附近玩家
        for (Entity nearby : mob.getNearbyEntities(18, 18, 18)) {
            if (nearby instanceof Player p) {
                p.sendMessage(ChatColor.RED + "⚠ 豬屍獸正在蓄力衝撞！");
            }
        }

        new BukkitRunnable() {
            int warmup = 30; // 1.5秒蓄力
            int chargeTicks = 0;
            boolean hit = false;
            @Override
            public void run() {
                if (mob.isDead()) { cancel(); return; }

                // 蓄力階段 — 身體泛紅
                if (warmup > 0) {
                    warmup -= 2;
                    mob.getWorld().spawnParticle(Particle.SMOKE, mob.getLocation().add(0, 0.5, 0),
                            3, 0.3, 0.2, 0.3, 0.02);
                    mob.getWorld().spawnParticle(Particle.LAVA, mob.getLocation().add(0, 1, 0),
                            2, 0.2, 0.2, 0.2, 0);
                    return;
                }

                // 衝刺階段
                if (chargeTicks >= 20 || hit) { cancel(); return; }

                mob.setVelocity(direction.clone().multiply(1.8).setY(0.05));
                mob.getWorld().spawnParticle(Particle.CLOUD, mob.getLocation().add(0, 0.3, 0),
                        10, 0.4, 0.1, 0.4, 0.04);
                mob.getWorld().spawnParticle(Particle.BLOCK, mob.getLocation(),
                        8, 0.4, 0.1, 0.4, 0.1, org.bukkit.Material.NETHERRACK.createBlockData());

                // 碰撞檢測 — 範圍更大、傷害更高
                for (Entity nearby : mob.getNearbyEntities(2.0, 2.0, 2.0)) {
                    if (nearby instanceof Player player) {
                        if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                        // 衝撞傷害 = 怪物傷害 * 2.5
                        int level = mobManager.getMobLevel(mob);
                        String key = mobManager.getCustomMobKey(mob);
                        double chargeDmg = 10.0;
                        if (key != null) {
                            MobManager.MobData data = mobManager.getMobData(key);
                            if (data != null) chargeDmg = data.calculateDamage(level) * 2.5;
                        }
                        player.damage(chargeDmg, mob);

                        // 擊飛
                        Vector knockback = direction.clone().multiply(1.5).setY(0.7);
                        player.setVelocity(knockback);
                        player.getWorld().playSound(player.getLocation(), Sound.ENTITY_IRON_GOLEM_ATTACK, 1.5f, 0.5f);
                        player.getWorld().spawnParticle(Particle.EXPLOSION, player.getLocation().add(0, 1, 0),
                                3, 0.3, 0.3, 0.3, 0);
                        player.sendMessage(ChatColor.RED + " 你被豬屍獸衝撞擊飛了！");
                        hit = true;
                        cancel();
                        return;
                    }
                }

                // 衝撞音效
                if (chargeTicks % 3 == 0) {
                    mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_RAVAGER_STEP, 1.0f, 0.8f);
                }

                chargeTicks++;
            }
        }.runTaskTimer(plugin, 0L, 2L);
    }

    /**
     * 防止自訂怪物被陽光燃燒
     * 殭屍、骷髏等不死生物在白天會著火，取消此行為
     */
    @EventHandler
    public void onCustomMobCombust(EntityCombustEvent event) {
        if (!(event.getEntity() instanceof LivingEntity)) return;

        String mobKey = mobManager.getCustomMobKey(event.getEntity());
        if (mobKey != null) {
            // 是自訂怪物 → 取消燃燒
            event.setCancelled(true);
        }
    }
}

package com.customrpg.managers;

import com.customrpg.CustomRPG;
import org.bukkit.ChatColor;
import org.bukkit.Location;
import org.bukkit.NamespacedKey;
import org.bukkit.World;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Entity;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.scheduler.BukkitTask;
import org.bukkit.util.Vector;

import java.io.File;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.UUID;

/**
 * BossZoneManager - 管理 Boss 區域、綁定小怪、排他生成與 Boss 邊界限制
 */
public class BossZoneManager {

    private final CustomRPG plugin;
    private final MobManager mobManager;
    private final DistanceSpawnManager distanceSpawnManager;
    private final File configFile;
    private final NamespacedKey zoneIdKey;
    private final NamespacedKey zoneRoleKey;
    private final Random random = new Random();

    private final Map<String, BossZone> zones = new LinkedHashMap<>();
    private final Map<String, UUID> activeBosses = new HashMap<>();
    private final Map<String, Set<UUID>> activeMinions = new HashMap<>();
    private final Map<String, Long> bossCooldownUntil = new HashMap<>();
    private final Map<String, Long> lastMinionSpawn = new HashMap<>();

    private BukkitTask bossTask;
    private boolean active;

    public BossZoneManager(CustomRPG plugin, MobManager mobManager, DistanceSpawnManager distanceSpawnManager) {
        this.plugin = plugin;
        this.mobManager = mobManager;
        this.distanceSpawnManager = distanceSpawnManager;
        this.configFile = new File(plugin.getDataFolder(), "config/boss_zones.yml");
        this.zoneIdKey = new NamespacedKey(plugin, "boss_zone_id");
        this.zoneRoleKey = new NamespacedKey(plugin, "boss_zone_role");
        load();
        startTask();
    }

    public void setActive(boolean active) {
        this.active = active;
    }

    public boolean isActive() {
        return active;
    }

    public void reload() {
        load();
    }

    public void shutdown() {
        if (bossTask != null) {
            bossTask.cancel();
            bossTask = null;
        }
        despawnAllTracked();
    }

    private void load() {
        zones.clear();
        if (!configFile.exists()) {
            plugin.saveResource("config/boss_zones.yml", false);
        }

        FileConfiguration config = YamlConfiguration.loadConfiguration(configFile);
        ConfigurationSection section = config.getConfigurationSection("boss-zones");
        if (section == null) {
            plugin.getLogger().warning("[BossZoneManager] No boss-zones section found in config/boss_zones.yml");
            return;
        }

        for (String id : section.getKeys(false)) {
            ConfigurationSection zoneSection = section.getConfigurationSection(id);
            if (zoneSection == null) {
                continue;
            }

            BossZone zone = new BossZone(
                    id,
                    zoneSection.getString("name", id),
                    zoneSection.getString("world", "world"),
                    zoneSection.getDouble("center.x"),
                    zoneSection.getDouble("center.y"),
                    zoneSection.getDouble("center.z"),
                    Math.max(1.0, zoneSection.getDouble("radius", 200.0)),
                    zoneSection.getString("boss-mob-key", ""),
                    zoneSection.getStringList("linked-minions"),
                    Math.max(0.0, zoneSection.getDouble("boss-spawn-chance-per-cycle", 0.35)),
                    Math.max(0, zoneSection.getInt("respawn-cooldown-seconds", 900)),
                    Math.max(0, zoneSection.getInt("max-minions", 4)),
                    Math.max(20L, zoneSection.getLong("minion-spawn-interval-ticks", 200L))
            );
            zones.put(id.toLowerCase(), zone);
        }

        plugin.getLogger().info("[BossZoneManager] Loaded " + zones.size() + " boss zones");
    }

    private void startTask() {
        if (bossTask != null) {
            bossTask.cancel();
        }

        bossTask = new BukkitRunnable() {
            @Override
            public void run() {
                if (!active) {
                    return;
                }

                for (BossZone zone : zones.values()) {
                    maintainZone(zone);
                }
            }
        }.runTaskTimer(plugin, 40L, 40L);
    }

    public void trySpawnBossForPlayer(Player player) {
        if (!active || player == null || player.getWorld() == null) {
            return;
        }
        if (player.getGameMode() == org.bukkit.GameMode.SPECTATOR || player.getGameMode() == org.bukkit.GameMode.CREATIVE) {
            return;
        }

        BossZone zone = getZoneAt(player.getLocation());
        if (zone == null || zone.getBossMobKey().isBlank()) {
            return;
        }

        if (getBossEntity(zone) != null) {
            return;
        }

        long cooldownUntil = bossCooldownUntil.getOrDefault(zone.getId(), 0L);
        if (System.currentTimeMillis() < cooldownUntil) {
            return;
        }

        if (random.nextDouble() > zone.getBossSpawnChancePerCycle()) {
            return;
        }

        Location spawnLocation = distanceSpawnManager.findSpawnNear(zone.getCenter(player.getWorld()), 8);
        if (spawnLocation == null) {
            spawnLocation = mobManager.findSafeSpawnLocation(zone.getCenter(player.getWorld()));
        }
        if (spawnLocation == null) {
            return;
        }

        int level = distanceSpawnManager.calculateLevelForLocation(spawnLocation, DistanceSpawnManager.MobTier.BOSS);
        LivingEntity boss = mobManager.spawnCustomMobWithLevel(zone.getBossMobKey(), spawnLocation, level);
        if (boss == null) {
            return;
        }

        mobManager.setMobTier(boss, DistanceSpawnManager.MobTier.BOSS.name());
        distanceSpawnManager.applyBossModifiers(boss, spawnLocation, level);
        tagEntity(boss, zone.getId(), "BOSS");
        activeBosses.put(zone.getId(), boss.getUniqueId());
        clearForbiddenCustomMobs(zone);
        announceBoss(zone, boss, level);
    }

    private void maintainZone(BossZone zone) {
        LivingEntity boss = getBossEntity(zone);
        if (boss == null) {
            activeBosses.remove(zone.getId());
            cleanupMinions(zone, false);
            return;
        }

        keepBossInsideZone(zone, boss);
        clearForbiddenCustomMobs(zone);
        maintainMinions(zone, boss);
    }

    private void keepBossInsideZone(BossZone zone, LivingEntity boss) {
        Location center = zone.getCenter(boss.getWorld());
        if (boss.getLocation().distance(center) <= zone.getRadius()) {
            return;
        }

        Vector pull = center.toVector().subtract(boss.getLocation().toVector()).normalize().multiply(Math.max(1.0, zone.getRadius() - 2.0));
        Location target = center.clone().subtract(pull);
        Location safeTarget = distanceSpawnManager.findSpawnNear(target, 6);
        if (safeTarget == null) {
            safeTarget = mobManager.findSafeSpawnLocation(center);
        }
        if (safeTarget != null) {
            boss.teleport(safeTarget);
        }
    }

    private void maintainMinions(BossZone zone, LivingEntity boss) {
        cleanupInvalidMinions(zone);
        if (zone.getLinkedMinions().isEmpty() || zone.getMaxMinions() <= 0) {
            return;
        }

        Set<UUID> tracked = activeMinions.computeIfAbsent(zone.getId(), ignored -> new HashSet<>());
        if (tracked.size() >= zone.getMaxMinions()) {
            return;
        }

        long now = System.currentTimeMillis();
        long intervalMillis = Math.max(1000L, zone.getMinionSpawnIntervalTicks() * 50L);
        long lastSpawn = lastMinionSpawn.getOrDefault(zone.getId(), 0L);
        if (now - lastSpawn < intervalMillis) {
            return;
        }

        String minionKey = zone.getLinkedMinions().get(random.nextInt(zone.getLinkedMinions().size()));
        Location spawnLocation = distanceSpawnManager.findSpawnNear(boss.getLocation(), 8);
        if (spawnLocation == null) {
            return;
        }

        int level = distanceSpawnManager.calculateLevelForLocation(spawnLocation, DistanceSpawnManager.MobTier.NORMAL);
        LivingEntity minion = mobManager.spawnCustomMobWithLevel(minionKey, spawnLocation, level);
        if (minion == null) {
            return;
        }

        tagEntity(minion, zone.getId(), "MINION");
        mobManager.setMobTier(minion, DistanceSpawnManager.MobTier.NORMAL.name());
        tracked.add(minion.getUniqueId());
        lastMinionSpawn.put(zone.getId(), now);
    }

    private void clearForbiddenCustomMobs(BossZone zone) {
        World world = plugin.getServer().getWorld(zone.getWorld());
        if (world == null) {
            return;
        }

        Location center = zone.getCenter(world);
        for (Entity entity : world.getNearbyEntities(center, zone.getRadius(), zone.getRadius(), zone.getRadius())) {
            if (!(entity instanceof LivingEntity living)) {
                continue;
            }
            String customMobKey = mobManager.getCustomMobKey(living);
            if (customMobKey == null) {
                continue;
            }
            if (!zone.isAllowedMob(customMobKey)) {
                living.remove();
            }
        }
    }

    public boolean isInsideBossZone(Location location) {
        return getZoneAt(location) != null;
    }

    public BossZone getZoneAt(Location location) {
        if (location == null || location.getWorld() == null) {
            return null;
        }
        String worldName = location.getWorld().getName();
        for (BossZone zone : zones.values()) {
            if (zone.contains(worldName, location.getX(), location.getY(), location.getZ())) {
                return zone;
            }
        }
        return null;
    }

    public boolean canSpawnCustomMob(Location location, String mobKey) {
        BossZone zone = getZoneAt(location);
        return zone == null || zone.isAllowedMob(mobKey);
    }

    private void tagEntity(LivingEntity entity, String zoneId, String role) {
        entity.getPersistentDataContainer().set(zoneIdKey, PersistentDataType.STRING, zoneId);
        entity.getPersistentDataContainer().set(zoneRoleKey, PersistentDataType.STRING, role);
    }

    public void handleEntityDeath(LivingEntity entity) {
        if (entity == null) {
            return;
        }

        String zoneId = entity.getPersistentDataContainer().get(zoneIdKey, PersistentDataType.STRING);
        String role = entity.getPersistentDataContainer().get(zoneRoleKey, PersistentDataType.STRING);
        if (zoneId == null || role == null) {
            return;
        }

        if ("BOSS".equalsIgnoreCase(role)) {
            activeBosses.remove(zoneId);
            BossZone zone = zones.get(zoneId.toLowerCase());
            if (zone != null) {
                bossCooldownUntil.put(zoneId, System.currentTimeMillis() + (zone.getRespawnCooldownSeconds() * 1000L));
                cleanupMinions(zone, true);
            }
        } else if ("MINION".equalsIgnoreCase(role)) {
            Set<UUID> tracked = activeMinions.get(zoneId);
            if (tracked != null) {
                tracked.remove(entity.getUniqueId());
            }
        }
    }

    private void cleanupMinions(BossZone zone, boolean removeEntities) {
        Set<UUID> tracked = activeMinions.remove(zone.getId());
        if (tracked == null) {
            return;
        }

        if (!removeEntities) {
            return;
        }

        for (UUID uuid : tracked) {
            Entity entity = plugin.getServer().getEntity(uuid);
            if (entity != null && !entity.isDead()) {
                entity.remove();
            }
        }
    }

    private void cleanupInvalidMinions(BossZone zone) {
        Set<UUID> tracked = activeMinions.computeIfAbsent(zone.getId(), ignored -> new HashSet<>());
        tracked.removeIf(uuid -> {
            Entity entity = plugin.getServer().getEntity(uuid);
            return entity == null || entity.isDead();
        });
    }

    private LivingEntity getBossEntity(BossZone zone) {
        UUID uuid = activeBosses.get(zone.getId());
        if (uuid == null) {
            return null;
        }
        Entity entity = plugin.getServer().getEntity(uuid);
        if (entity instanceof LivingEntity living && !living.isDead()) {
            return living;
        }
        return null;
    }

    private void announceBoss(BossZone zone, LivingEntity boss, int level) {
        String name = boss.getCustomName() != null ? boss.getCustomName() : zone.getBossMobKey();
        for (Player player : boss.getWorld().getPlayers()) {
            if (player.getGameMode() == org.bukkit.GameMode.SPECTATOR) {
                continue;
            }
            if (player.getLocation().distance(zone.getCenter(player.getWorld())) <= zone.getRadius() * 2.0) {
                player.sendMessage(ChatColor.DARK_RED + "[Boss Zone] " + ChatColor.RED + name + ChatColor.GRAY + " Lv." + level + ChatColor.YELLOW + " 已出現在 " + zone.getName());
            }
        }
    }

    private void despawnAllTracked() {
        for (UUID uuid : activeBosses.values()) {
            Entity entity = plugin.getServer().getEntity(uuid);
            if (entity != null && !entity.isDead()) {
                entity.remove();
            }
        }
        for (Set<UUID> uuids : activeMinions.values()) {
            for (UUID uuid : uuids) {
                Entity entity = plugin.getServer().getEntity(uuid);
                if (entity != null && !entity.isDead()) {
                    entity.remove();
                }
            }
        }
        activeBosses.clear();
        activeMinions.clear();
    }

    public int getZoneCount() {
        return zones.size();
    }

    public Collection<BossZone> getZones() {
        return new ArrayList<>(zones.values());
    }

    public static class BossZone {
        private final String id;
        private final String name;
        private final String world;
        private final double centerX;
        private final double centerY;
        private final double centerZ;
        private final double radius;
        private final double radiusSquared;
        private final String bossMobKey;
        private final List<String> linkedMinions;
        private final double bossSpawnChancePerCycle;
        private final int respawnCooldownSeconds;
        private final int maxMinions;
        private final long minionSpawnIntervalTicks;

        public BossZone(String id, String name, String world,
                        double centerX, double centerY, double centerZ,
                        double radius, String bossMobKey, List<String> linkedMinions,
                        double bossSpawnChancePerCycle, int respawnCooldownSeconds,
                        int maxMinions, long minionSpawnIntervalTicks) {
            this.id = id;
            this.name = name;
            this.world = world;
            this.centerX = centerX;
            this.centerY = centerY;
            this.centerZ = centerZ;
            this.radius = radius;
            this.radiusSquared = radius * radius;
            this.bossMobKey = bossMobKey;
            this.linkedMinions = linkedMinions != null ? linkedMinions : new ArrayList<>();
            this.bossSpawnChancePerCycle = bossSpawnChancePerCycle;
            this.respawnCooldownSeconds = respawnCooldownSeconds;
            this.maxMinions = maxMinions;
            this.minionSpawnIntervalTicks = minionSpawnIntervalTicks;
        }

        public boolean contains(String worldName, double x, double y, double z) {
            if (!world.equalsIgnoreCase(worldName)) {
                return false;
            }
            double dx = x - centerX;
            double dy = y - centerY;
            double dz = z - centerZ;
            return (dx * dx) + (dy * dy) + (dz * dz) <= radiusSquared;
        }

        public boolean isAllowedMob(String mobKey) {
            return bossMobKey.equalsIgnoreCase(mobKey) || linkedMinions.stream().anyMatch(key -> key.equalsIgnoreCase(mobKey));
        }

        public Location getCenter(World world) {
            return new Location(world, centerX, centerY, centerZ);
        }

        public String getId() {
            return id;
        }

        public String getName() {
            return name;
        }

        public String getWorld() {
            return world;
        }

        public double getRadius() {
            return radius;
        }

        public String getBossMobKey() {
            return bossMobKey;
        }

        public List<String> getLinkedMinions() {
            return linkedMinions;
        }

        public double getBossSpawnChancePerCycle() {
            return bossSpawnChancePerCycle;
        }

        public int getRespawnCooldownSeconds() {
            return respawnCooldownSeconds;
        }

        public int getMaxMinions() {
            return maxMinions;
        }

        public long getMinionSpawnIntervalTicks() {
            return minionSpawnIntervalTicks;
        }
    }
}

package com.customrpg.managers;

import com.customrpg.CustomRPG;
import org.bukkit.ChatColor;
import org.bukkit.Difficulty;
import org.bukkit.Location;
import org.bukkit.NamespacedKey;
import org.bukkit.Particle;
import org.bukkit.Registry;
import org.bukkit.Sound;
import org.bukkit.World;
import org.bukkit.block.Block;
import org.bukkit.block.BlockFace;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Entity;
import org.bukkit.entity.EntityType;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.scheduler.BukkitTask;

import java.io.File;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Random;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.ThreadLocalRandom;
import java.util.logging.Logger;

public class DistanceSpawnManager {

    public enum MobTier {
        NORMAL("普通", ChatColor.WHITE),
        ELITE("精英", ChatColor.GOLD),
        BOSS("BOSS", ChatColor.RED);

        private final String displayName;
        private final ChatColor color;

        MobTier(String displayName, ChatColor color) {
            this.displayName = displayName;
            this.color = color;
        }

        public String getDisplayName() {
            return displayName;
        }

        public ChatColor getColor() {
            return color;
        }
    }

    private final CustomRPG plugin;
    private final MobManager mobManager;
    private final SafeZoneManager safeZoneManager;
    private final Logger log;
    private final Random random = new Random();
    private final Set<UUID> spawnedMobs = new HashSet<>();

    private BossZoneManager bossZoneManager;
    private BukkitTask spawnTask;

    private boolean enabled;
    private boolean active;
    private boolean debug;
    private int intervalTicks;
    private int spawnsPerCycle;
    private int spawnRadiusMin;
    private int spawnRadiusMax;
    private int maxMobsPerPlayer;
    private Set<String> disabledWorlds = new HashSet<>();

    private String originWorld;
    private double originX;
    private double originY;
    private double originZ;
    private int baseLevel;
    private double blocksPerLevel;

    private int normalLevelOffsetMin;
    private int normalLevelOffsetMax;
    private String normalNamePrefix;

    private double eliteChance;
    private int eliteLevelOffsetMin;
    private int eliteLevelOffsetMax;
    private double eliteStatMultiplier;
    private String eliteNamePrefix;

    private int bossLevelOffsetMin;
    private int bossLevelOffsetMax;
    private double bossStatMultiplier;
    private String bossNamePrefix;
    private String bossSpawnParticle;
    private int bossParticleCount;
    private String bossSpawnSound;
    private float bossSoundVolume;
    private float bossSoundPitch;

    private boolean nightOnly;
    private int maxLightLevel;
    private boolean requireSolidGround;
    private boolean requireAirSpace;

    private int totalSpawnAttempts;
    private int totalSpawnSuccess;
    private int totalLocationFails;
    private String lastSkipReason = "尚未執行 /finishrpg";

    public DistanceSpawnManager(CustomRPG plugin, MobManager mobManager, SafeZoneManager safeZoneManager) {
        this.plugin = plugin;
        this.mobManager = mobManager;
        this.safeZoneManager = safeZoneManager;
        this.log = plugin.getLogger();
        loadConfig();
        startSpawnTask();
    }

    public void setBossZoneManager(BossZoneManager bossZoneManager) {
        this.bossZoneManager = bossZoneManager;
    }

    private void loadConfig() {
        File configFile = new File(plugin.getDataFolder(), "config/mob_spawner.yml");
        if (!configFile.exists()) {
            plugin.saveResource("config/mob_spawner.yml", false);
        }

        FileConfiguration config = YamlConfiguration.loadConfiguration(configFile);
        enabled = config.getBoolean("enabled", true);
        active = false;
        debug = config.getBoolean("debug", false);
        intervalTicks = config.getInt("interval-ticks", 60);
        spawnsPerCycle = config.getInt("spawns-per-cycle", 3);
        spawnRadiusMin = config.getInt("spawn-radius.min", 10);
        spawnRadiusMax = config.getInt("spawn-radius.max", 35);
        maxMobsPerPlayer = config.getInt("limits.max-mobs-per-player", 10);
        disabledWorlds = new HashSet<>(config.getStringList("disabled-worlds"));

        originWorld = config.getString("difficulty-scaling.origin.world", "world");
        originX = config.getDouble("difficulty-scaling.origin.x", 192.0);
        originY = config.getDouble("difficulty-scaling.origin.y", 73.0);
        originZ = config.getDouble("difficulty-scaling.origin.z", -70.0);
        baseLevel = Math.max(1, config.getInt("difficulty-scaling.base-level", 1));
        blocksPerLevel = Math.max(1.0, config.getDouble("difficulty-scaling.blocks-per-level", 80.0));

        normalLevelOffsetMin = config.getInt("tiers.normal.level-offset-min", 0);
        normalLevelOffsetMax = config.getInt("tiers.normal.level-offset-max", 1);
        normalNamePrefix = ChatColor.translateAlternateColorCodes('&', config.getString("tiers.normal.name-prefix", ""));

        eliteChance = config.getDouble("tiers.elite.chance", 0.20);
        eliteLevelOffsetMin = config.getInt("tiers.elite.level-offset-min", 1);
        eliteLevelOffsetMax = config.getInt("tiers.elite.level-offset-max", 4);
        eliteStatMultiplier = config.getDouble("tiers.elite.stat-multiplier", 1.5);
        eliteNamePrefix = ChatColor.translateAlternateColorCodes('&', config.getString("tiers.elite.name-prefix", "&6⚔ "));

        bossLevelOffsetMin = config.getInt("tiers.boss.level-offset-min", 3);
        bossLevelOffsetMax = config.getInt("tiers.boss.level-offset-max", 8);
        bossStatMultiplier = config.getDouble("tiers.boss.stat-multiplier", 3.0);
        bossNamePrefix = ChatColor.translateAlternateColorCodes('&', config.getString("tiers.boss.name-prefix", "&c✦ BOSS ✦ "));
        bossSpawnParticle = config.getString("tiers.boss.spawn-particle", "FLAME");
        bossParticleCount = config.getInt("tiers.boss.spawn-particle-count", 100);
        bossSpawnSound = config.getString("tiers.boss.spawn-sound", "ENTITY_ENDER_DRAGON_GROWL");
        bossSoundVolume = (float) config.getDouble("tiers.boss.spawn-sound-volume", 2.0);
        bossSoundPitch = (float) config.getDouble("tiers.boss.spawn-sound-pitch", 0.5);

        nightOnly = config.getBoolean("conditions.night-only", false);
        maxLightLevel = config.getInt("conditions.max-light-level", 15);
        requireSolidGround = config.getBoolean("conditions.require-solid-ground", true);
        requireAirSpace = config.getBoolean("conditions.require-air-space", true);
    }

    private void startSpawnTask() {
        if (spawnTask != null) {
            spawnTask.cancel();
        }

        spawnTask = new BukkitRunnable() {
            @Override
            public void run() {
                if (!enabled || !active) {
                    return;
                }

                for (Player player : plugin.getServer().getOnlinePlayers()) {
                    processPlayer(player);
                }
            }
        }.runTaskTimer(plugin, 40L, intervalTicks);
    }

    public boolean activateSystem() {
        if (!enabled) {
            return false;
        }

        active = true;
        lastSkipReason = "系統已啟動";
        if (bossZoneManager != null) {
            bossZoneManager.setActive(true);
        }
        return true;
    }

    public void deactivateSystem() {
        active = false;
        if (bossZoneManager != null) {
            bossZoneManager.setActive(false);
        }
    }

    public boolean isActive() {
        return active;
    }

    public boolean isEnabled() {
        return enabled;
    }

    private void processPlayer(Player player) {
        if (player.getGameMode() == org.bukkit.GameMode.SPECTATOR || player.getGameMode() == org.bukkit.GameMode.CREATIVE) {
            lastSkipReason = "玩家模式不生成";
            return;
        }

        if (disabledWorlds.contains(player.getWorld().getName())) {
            lastSkipReason = "世界禁用: " + player.getWorld().getName();
            return;
        }

        if (safeZoneManager.isInSafeZone(player.getLocation())) {
            lastSkipReason = "玩家位於安全區";
            return;
        }

        if (nightOnly) {
            long time = player.getWorld().getTime();
            if (time < 13000 || time > 23000) {
                lastSkipReason = "白天不生成";
                return;
            }
        }

        ProtectionAreaManager protectionAreaManager = plugin.getProtectionAreaManager();
        if (protectionAreaManager != null && protectionAreaManager.isInProtectedArea(player.getLocation())) {
            lastSkipReason = "玩家位於保護區域";
            return;
        }

        if (bossZoneManager != null) {
            bossZoneManager.trySpawnBossForPlayer(player);
        }

        int nearbyMobCount = countNearbyCustomMobs(player);
        if (nearbyMobCount >= maxMobsPerPlayer) {
            lastSkipReason = "附近自訂怪已達上限";
            return;
        }

        List<String> availableMobKeys = new ArrayList<>(mobManager.getNormalMobKeys());
        if (player.getWorld().getDifficulty() == Difficulty.PEACEFUL) {
            availableMobKeys.removeIf(mobManager::willBeRemovedInPeaceful);
        }

        if (availableMobKeys.isEmpty()) {
            lastSkipReason = player.getWorld().getDifficulty() == Difficulty.PEACEFUL
                    ? "和平模式下沒有可生成的敵對自訂怪"
                    : "沒有可用的普通自訂怪";
            return;
        }

        int toSpawn = Math.min(spawnsPerCycle, maxMobsPerPlayer - nearbyMobCount);
        for (int i = 0; i < toSpawn; i++) {
            attemptSpawn(player, availableMobKeys);
        }
    }

    private boolean attemptSpawn(Player player, List<String> availableMobKeys) {
        totalSpawnAttempts++;

        Location spawnLoc = findSpawnLocation(player);
        if (spawnLoc == null) {
            totalLocationFails++;
            lastSkipReason = "找不到有效生成位置";
            return false;
        }

        if (bossZoneManager != null && bossZoneManager.isInsideBossZone(spawnLoc)) {
            lastSkipReason = "Boss 區域排他範圍內";
            return false;
        }

        MobTier tier = determineNaturalTier();
        int level = calculateLevelForLocation(spawnLoc, tier);
        String mobKey = selectMobTypeForLevel(filterBySpawnTime(availableMobKeys, spawnLoc.getWorld()), level);

        if (mobKey == null) {
            lastSkipReason = "沒有符合當前等級的怪物";
            return false;
        }

        boolean success = spawnTieredMob(mobKey, spawnLoc, level, tier);
        if (success) {
            totalSpawnSuccess++;
            lastSkipReason = "成功";
        }
        return success;
    }

    private List<String> filterBySpawnTime(List<String> mobKeys, World world) {
        long worldTime = world.getTime();
        boolean isNight = worldTime >= 13000 && worldTime < 23000;
        List<String> filtered = new ArrayList<>();
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data == null) {
                continue;
            }
            String spawnTime = data.getSpawnTime();
            if ("all".equalsIgnoreCase(spawnTime)
                    || ("night".equalsIgnoreCase(spawnTime) && isNight)
                    || ("day".equalsIgnoreCase(spawnTime) && !isNight)) {
                filtered.add(key);
            }
        }
        return filtered.isEmpty() ? mobKeys : filtered;
    }

    private MobTier determineNaturalTier() {
        return random.nextDouble() < eliteChance ? MobTier.ELITE : MobTier.NORMAL;
    }

    public int calculateBaseLevel(Location location) {
        double distance = calculateDistanceFromOrigin(location);
        return Math.max(1, baseLevel + (int) Math.floor(distance / blocksPerLevel));
    }

    public int calculateLevelForLocation(Location location, MobTier tier) {
        return Math.max(1, calculateBaseLevel(location) + calculateTierLevelOffset(tier));
    }

    public double calculateDistanceFromOrigin(Location location) {
        if (location == null || location.getWorld() == null) {
            return 0.0;
        }
        if (!location.getWorld().getName().equalsIgnoreCase(originWorld)) {
            return 0.0;
        }
        double dx = location.getX() - originX;
        double dy = location.getY() - originY;
        double dz = location.getZ() - originZ;
        return Math.sqrt(dx * dx + dy * dy + dz * dz);
    }

    private int calculateTierLevelOffset(MobTier tier) {
        return switch (tier) {
            case ELITE -> ThreadLocalRandom.current().nextInt(eliteLevelOffsetMin, eliteLevelOffsetMax + 1);
            case BOSS -> ThreadLocalRandom.current().nextInt(bossLevelOffsetMin, bossLevelOffsetMax + 1);
            default -> ThreadLocalRandom.current().nextInt(normalLevelOffsetMin, normalLevelOffsetMax + 1);
        };
    }

    private Location findSpawnLocation(Player player) {
        Location playerLoc = player.getLocation();
        World world = player.getWorld();

        for (int attempt = 0; attempt < 8; attempt++) {
            double angle = random.nextDouble() * Math.PI * 2;
            double distance = spawnRadiusMin + random.nextDouble() * Math.max(1.0, spawnRadiusMax - spawnRadiusMin);
            double x = playerLoc.getX() + Math.cos(angle) * distance;
            double z = playerLoc.getZ() + Math.sin(angle) * distance;

            int chunkX = ((int) Math.floor(x)) >> 4;
            int chunkZ = ((int) Math.floor(z)) >> 4;
            if (!world.isChunkLoaded(chunkX, chunkZ)) {
                continue;
            }

            int highestY = world.getHighestBlockYAt((int) Math.floor(x), (int) Math.floor(z));
            Location desired = new Location(world, Math.floor(x) + 0.5, highestY + 1, Math.floor(z) + 0.5);
            Location candidate = mobManager.findSafeSpawnLocation(desired);
            if (candidate == null || !isValidSpawnLocation(candidate)) {
                continue;
            }

            if (safeZoneManager.isInSafeZone(candidate)) {
                continue;
            }

            ProtectionAreaManager protectionAreaManager = plugin.getProtectionAreaManager();
            if (protectionAreaManager != null && protectionAreaManager.isInProtectedArea2D(candidate)) {
                continue;
            }

            if (bossZoneManager != null && bossZoneManager.isInsideBossZone(candidate)) {
                continue;
            }

            if (maxLightLevel < 15 && candidate.getBlock().getLightLevel() > maxLightLevel) {
                continue;
            }

            return candidate;
        }

        return null;
    }

    public Location findSpawnNear(Location center, int horizontalRadius) {
        if (center == null || center.getWorld() == null) {
            return null;
        }

        World world = center.getWorld();
        LinkedHashSet<Location> candidates = new LinkedHashSet<>();
        Location safeCenter = mobManager.findSafeSpawnLocation(center.clone());
        if (safeCenter != null) {
            candidates.add(safeCenter);
        }

        for (int attempt = 0; attempt < 10; attempt++) {
            double angle = random.nextDouble() * Math.PI * 2;
            double distance = random.nextDouble() * horizontalRadius;
            double x = center.getX() + Math.cos(angle) * distance;
            double z = center.getZ() + Math.sin(angle) * distance;
            int highestY = world.getHighestBlockYAt((int) Math.floor(x), (int) Math.floor(z));
            Location test = new Location(world, Math.floor(x) + 0.5, highestY + 1, Math.floor(z) + 0.5);
            Location safe = mobManager.findSafeSpawnLocation(test);
            if (safe != null) {
                candidates.add(safe);
            }
        }

        for (Location candidate : candidates) {
            if (!isValidSpawnLocation(candidate)) {
                continue;
            }
            if (safeZoneManager.isInSafeZone(candidate)) {
                continue;
            }
            return candidate;
        }
        return null;
    }

    private boolean isValidSpawnLocation(Location location) {
        Block feetBlock = location.getBlock();
        Block groundBlock = feetBlock.getRelative(BlockFace.DOWN);
        Block headBlock = feetBlock.getRelative(BlockFace.UP);

        if (requireSolidGround && !groundBlock.getType().isSolid()) {
            return false;
        }
        if (requireAirSpace && (!feetBlock.getType().isAir() || !headBlock.getType().isAir())) {
            return false;
        }
        if (groundBlock.isLiquid() || feetBlock.isLiquid()) {
            return false;
        }
        return true;
    }

    private String selectMobTypeForLevel(List<String> mobKeys, int level) {
        if (mobKeys == null || mobKeys.isEmpty()) {
            return null;
        }

        List<String> exactMatches = new ArrayList<>();
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data != null && level >= data.getMinLevel() && level <= data.getMaxLevel()) {
                exactMatches.add(key);
            }
        }
        if (!exactMatches.isEmpty()) {
            return exactMatches.get(random.nextInt(exactMatches.size()));
        }

        List<String> nearMatches = new ArrayList<>();
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data != null && level >= data.getMinLevel() - 5 && level <= data.getMaxLevel() + 5) {
                nearMatches.add(key);
            }
        }
        if (!nearMatches.isEmpty()) {
            return nearMatches.get(random.nextInt(nearMatches.size()));
        }

        String closest = null;
        int closestDistance = Integer.MAX_VALUE;
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data == null) {
                continue;
            }
            int distance = Math.min(Math.abs(level - data.getMinLevel()), Math.abs(level - data.getMaxLevel()));
            if (distance < closestDistance) {
                closestDistance = distance;
                closest = key;
            }
        }
        return closest;
    }

    public boolean spawnTieredMob(String mobKey, Location location, int level, MobTier tier) {
        LivingEntity mob = mobManager.spawnCustomMobWithLevel(mobKey, location, level);
        if (mob == null) {
            return false;
        }

        mobManager.setMobTier(mob, tier.name());
        spawnedMobs.add(mob.getUniqueId());

        switch (tier) {
            case ELITE -> applyEliteModifiers(mob);
            case BOSS -> applyBossModifiers(mob, location, level);
            default -> {
                if (!normalNamePrefix.isEmpty() && mob.getCustomName() != null) {
                    mob.setCustomName(normalNamePrefix + mob.getCustomName());
                }
            }
        }
        return true;
    }

    private void applyEliteModifiers(LivingEntity mob) {
        double newMaxHealth = mob.getMaxHealth() * eliteStatMultiplier;
        mob.setMaxHealth(newMaxHealth);
        mob.setHealth(newMaxHealth);
        if (mob.getCustomName() != null) {
            mob.setCustomName(eliteNamePrefix + ChatColor.translateAlternateColorCodes('&', "&e[精英] ") + mob.getCustomName());
        }
        mob.setGlowing(true);
    }

    public void applyBossModifiers(LivingEntity mob, Location location, int level) {
        double newMaxHealth = mob.getMaxHealth() * bossStatMultiplier;
        mob.setMaxHealth(newMaxHealth);
        mob.setHealth(newMaxHealth);
        if (mob.getCustomName() != null) {
            mob.setCustomName(bossNamePrefix + mob.getCustomName());
        }
        mob.setGlowing(true);

        try {
            Particle particle = Particle.valueOf(bossSpawnParticle);
            location.getWorld().spawnParticle(particle, location.clone().add(0, 1, 0), bossParticleCount, 1.5, 1.5, 1.5, 0.1);
        } catch (Exception ignored) {
            location.getWorld().spawnParticle(Particle.FLAME, location.clone().add(0, 1, 0), bossParticleCount, 1.5, 1.5, 1.5, 0.1);
        }

        Sound sound = resolveConfiguredSound(bossSpawnSound);
        if (sound != null) {
            location.getWorld().playSound(location, sound, bossSoundVolume, bossSoundPitch);
        } else {
            location.getWorld().playSound(location, Sound.ENTITY_ENDER_DRAGON_GROWL, 2.0f, 0.5f);
        }

        BossBarManager bossBarManager = plugin.getBossBarManager();
        if (bossBarManager != null) {
            bossBarManager.createBossBossBar(mob, level);
        }
    }

    private Sound resolveConfiguredSound(String configuredValue) {
        if (configuredValue == null || configuredValue.isBlank()) {
            return null;
        }

        String trimmed = configuredValue.trim();
        for (Sound sound : Sound.values()) {
            if (sound.name().equalsIgnoreCase(trimmed)) {
                return sound;
            }
        }

        String normalized = trimmed.toLowerCase();
        NamespacedKey key = normalized.contains(":")
                ? NamespacedKey.fromString(normalized)
                : NamespacedKey.minecraft(normalized);

        return key != null ? Registry.SOUNDS.get(key) : null;
    }

    public String forceSpawn(Player player, String mobKey, MobTier tier) {
        List<String> mobKeys = new ArrayList<>(mobManager.getMobKeys());
        if (mobKeys.isEmpty()) {
            return ChatColor.RED + "沒有已註冊的怪物類型！";
        }

        if (mobKey == null || mobKey.isBlank()) {
            mobKey = mobKeys.get(random.nextInt(mobKeys.size()));
        } else if (mobManager.getMobData(mobKey) == null) {
            return ChatColor.RED + "未知的怪物類型: " + mobKey;
        }

        if (player.getWorld().getDifficulty() == Difficulty.PEACEFUL && mobManager.willBeRemovedInPeaceful(mobKey)) {
            EntityType actualType = mobManager.getActualSpawnEntityType(mobKey);
            return ChatColor.RED + "此怪物在 Peaceful 世界中會被 Minecraft 立刻移除：" + mobKey
                    + ChatColor.GRAY + " (" + (actualType != null ? actualType.name() : "unknown") + ")";
        }

        Location desired = player.getLocation().clone().add(player.getLocation().getDirection().multiply(8));
        Location spawnLocation = mobManager.findSafeSpawnLocation(desired);
        if (spawnLocation == null) {
            return ChatColor.RED + "找不到安全生成位置，請前往空曠地區再試一次。";
        }

        int level = calculateLevelForLocation(spawnLocation, tier);
        boolean success = spawnTieredMob(mobKey, spawnLocation, level, tier);
        if (!success) {
            return ChatColor.RED + "生成失敗: " + mobKey;
        }

        return ChatColor.GREEN + "✓ 成功生成 " + tier.getColor() + "[" + tier.getDisplayName() + "] "
                + ChatColor.WHITE + mobKey + " Lv." + level
                + ChatColor.GRAY + " 距離中心 " + String.format("%.1f", calculateDistanceFromOrigin(spawnLocation));
    }

    private int countNearbyCustomMobs(Player player) {
        int count = 0;
        int searchRadius = Math.max(spawnRadiusMax, 64);
        NamespacedKey key = mobManager.getCustomMobNamespacedKey();
        for (Entity entity : player.getNearbyEntities(searchRadius, searchRadius, searchRadius)) {
            if (entity instanceof LivingEntity mob && mob.getPersistentDataContainer().has(key, PersistentDataType.STRING)) {
                count++;
            }
        }
        return count;
    }

    public List<String> getDebugStatus(Player player) {
        List<String> lines = new ArrayList<>();
        lines.add(ChatColor.GOLD + "========= DistanceSpawnManager 診斷 =========");
        lines.add(ChatColor.YELLOW + "配置啟用: " + (enabled ? ChatColor.GREEN + "是" : ChatColor.RED + "否"));
        lines.add(ChatColor.YELLOW + "RPG 已完成: " + (active ? ChatColor.GREEN + "是 (/finishrpg 已執行)" : ChatColor.RED + "否"));
        lines.add(ChatColor.YELLOW + "重生點中心: " + ChatColor.WHITE + originWorld + " (" + originX + ", " + originY + ", " + originZ + ")");
        lines.add(ChatColor.YELLOW + "等級公式: " + ChatColor.WHITE + "Lv = " + baseLevel + " + distance / " + String.format("%.1f", blocksPerLevel));
        lines.add(ChatColor.YELLOW + "安全區數量: " + ChatColor.WHITE + safeZoneManager.getZoneCount());
        lines.add(ChatColor.YELLOW + "Boss 區域數量: " + ChatColor.WHITE + (bossZoneManager != null ? bossZoneManager.getZoneCount() : 0));
        lines.add(ChatColor.YELLOW + "已註冊怪物: " + ChatColor.WHITE + mobManager.getMobKeys().size());
        lines.add(ChatColor.YELLOW + "最後狀態: " + ChatColor.WHITE + lastSkipReason);

        if (player != null) {
            lines.add("");
            lines.add(ChatColor.AQUA + "--- 你的位置 ---");
            lines.add(ChatColor.YELLOW + "世界: " + ChatColor.WHITE + player.getWorld().getName());
            lines.add(ChatColor.YELLOW + "難度: " + ChatColor.WHITE + player.getWorld().getDifficulty().name());
            lines.add(ChatColor.YELLOW + "距離中心: " + ChatColor.WHITE + String.format("%.2f", calculateDistanceFromOrigin(player.getLocation())));
            lines.add(ChatColor.YELLOW + "當前基礎怪物等級: " + ChatColor.WHITE + "Lv." + calculateLevelForLocation(player.getLocation(), MobTier.NORMAL));

            SafeZoneManager.SafeZone safeZone = safeZoneManager.getZoneAt(player.getLocation());
            if (safeZone != null) {
                lines.add(ChatColor.YELLOW + "安全區: " + ChatColor.GREEN + safeZone.getName() + ChatColor.GRAY + " (" + safeZone.getType() + ")");
            } else {
                lines.add(ChatColor.YELLOW + "安全區: " + ChatColor.RED + "不在安全區內");
            }

            if (bossZoneManager != null) {
                BossZoneManager.BossZone bossZone = bossZoneManager.getZoneAt(player.getLocation());
                if (bossZone != null) {
                    lines.add(ChatColor.YELLOW + "Boss 區域: " + ChatColor.LIGHT_PURPLE + bossZone.getName());
                    lines.add(ChatColor.YELLOW + "Boss: " + ChatColor.WHITE + bossZone.getBossMobKey());
                    lines.add(ChatColor.YELLOW + "綁定小怪: " + ChatColor.WHITE + String.join(", ", bossZone.getLinkedMinions()));
                }
            }
        }

        lines.add("");
        lines.add(ChatColor.AQUA + "--- 統計 ---");
        lines.add(ChatColor.YELLOW + "總嘗試: " + ChatColor.WHITE + totalSpawnAttempts);
        lines.add(ChatColor.YELLOW + "總成功: " + ChatColor.GREEN + totalSpawnSuccess);
        lines.add(ChatColor.YELLOW + "位置失敗: " + ChatColor.RED + totalLocationFails);
        lines.add(ChatColor.YELLOW + "追蹤中怪物: " + ChatColor.WHITE + getSpawnedMobCount());
        lines.add(ChatColor.GOLD + "===========================================");
        return lines;
    }

    public int clearAllSpawnedMobs() {
        int removed = 0;
        for (UUID uuid : new HashSet<>(spawnedMobs)) {
            Entity entity = plugin.getServer().getEntity(uuid);
            if (entity != null && !entity.isDead()) {
                entity.remove();
                removed++;
            }
        }
        spawnedMobs.clear();
        return removed;
    }

    public boolean toggleDebug() {
        debug = !debug;
        return debug;
    }

    public void reload() {
        boolean wasActive = active;
        loadConfig();
        active = wasActive && enabled;
        safeZoneManager.reload();
        if (bossZoneManager != null) {
            bossZoneManager.reload();
            bossZoneManager.setActive(active);
        }
        startSpawnTask();
    }

    public void shutdown() {
        if (spawnTask != null) {
            spawnTask.cancel();
            spawnTask = null;
        }
        clearAllSpawnedMobs();
    }

    public int getSpawnedMobCount() {
        spawnedMobs.removeIf(uuid -> {
            Entity entity = plugin.getServer().getEntity(uuid);
            return entity == null || entity.isDead();
        });
        return spawnedMobs.size();
    }
}

package com.customrpg.managers;

import com.customrpg.CustomRPG;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.Particle;
import org.bukkit.Sound;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.scheduler.BukkitRunnable;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * FocusManager — 風獵者專注系統
 *
 * 管理：
 * 1. 專注值 (0-10)  → 狙擊者支線用
 * 2. 連擊數 (0-10)  → 遊俠支線用
 * 3. 靜止偵測       → 判斷玩家是否未移動
 * 4. 追蹤標記       → 標記特定目標增傷
 */
public class FocusManager {

    private final CustomRPG plugin;

    // 專注值 Map<PlayerUUID, focus>
    private final Map<UUID, Integer> focusMap = new ConcurrentHashMap<>();
    // 連擊數 Map<PlayerUUID, combo>
    private final Map<UUID, Integer> comboMap = new ConcurrentHashMap<>();
    // 上次獲得專注的時間（用於衰減延遲）
    private final Map<UUID, Long> lastFocusGainTime = new ConcurrentHashMap<>();
    // 上次命中時間（用於連擊衰減）
    private final Map<UUID, Long> lastComboTime = new ConcurrentHashMap<>();
    // 上次記錄位置（靜止偵測）
    private final Map<UUID, Location> lastPositions = new ConcurrentHashMap<>();
    // 標記目標 Map<PlayerUUID, TargetUUID>
    private final Map<UUID, UUID> markedTargets = new ConcurrentHashMap<>();
    // 標記到期時間 Map<PlayerUUID, expiryMs>
    private final Map<UUID, Long> markExpiries = new ConcurrentHashMap<>();

    public static final int MAX_FOCUS = 10;
    public static final int MAX_COMBO = 10;

    /** 專注衰減延遲（毫秒） */
    private static final long FOCUS_DECAY_DELAY_MS = 5000L;
    /** 連擊衰減延遲（毫秒） */
    private static final long COMBO_DECAY_DELAY_MS = 5000L;

    public FocusManager(CustomRPG plugin) {
        this.plugin = plugin;
        startDecayTask();
        startPositionSnapshotTask();
    }

    // ══════════════════════════════════════════
    //  專注值管理
    // ══════════════════════════════════════════

    /**
     * 增加玩家專注值
     */
    public void addFocus(Player player, int amount) {
        UUID pid = player.getUniqueId();
        int current = focusMap.getOrDefault(pid, 0);
        int newFocus = Math.min(MAX_FOCUS, current + amount);
        focusMap.put(pid, newFocus);
        lastFocusGainTime.put(pid, System.currentTimeMillis());

        showFocusBar(player, newFocus);

        if (newFocus == MAX_FOCUS && current < MAX_FOCUS) {
            player.sendMessage("§e§l[專注] §6MAX FOCUS！終極技能已解鎖！");
            player.playSound(player.getLocation(), Sound.ENTITY_EXPERIENCE_ORB_PICKUP, 1.0f, 1.6f);
            player.getWorld().spawnParticle(Particle.ENCHANT,
                    player.getLocation().add(0, 1.2, 0), 25, 0.4, 0.6, 0.4, 0.6);
        }
    }

    /** 消耗指定數量的專注 */
    public void consumeFocus(Player player, int amount) {
        UUID pid = player.getUniqueId();
        focusMap.put(pid, Math.max(0, focusMap.getOrDefault(pid, 0) - amount));
    }

    /** 消耗全部專注，回傳消耗前的數量 */
    public int consumeAllFocus(Player player) {
        UUID pid = player.getUniqueId();
        int before = focusMap.getOrDefault(pid, 0);
        focusMap.put(pid, 0);
        return before;
    }

    /** 取得玩家目前專注值 */
    public int getFocus(Player player) {
        return focusMap.getOrDefault(player.getUniqueId(), 0);
    }

    /** 直接重置專注 */
    public void resetFocus(Player player) {
        focusMap.put(player.getUniqueId(), 0);
    }

    // ══════════════════════════════════════════
    //  連擊管理
    // ══════════════════════════════════════════

    /** 增加一層連擊 */
    public void addCombo(Player player) {
        UUID pid = player.getUniqueId();
        int current = comboMap.getOrDefault(pid, 0);
        comboMap.put(pid, Math.min(MAX_COMBO, current + 1));
        lastComboTime.put(pid, System.currentTimeMillis());
    }

    /** 取得當前連擊數 */
    public int getCombo(Player player) {
        return comboMap.getOrDefault(player.getUniqueId(), 0);
    }

    /** 消耗全部連擊，回傳消耗前數量 */
    public int consumeAllCombo(Player player) {
        UUID pid = player.getUniqueId();
        int before = comboMap.getOrDefault(pid, 0);
        comboMap.put(pid, 0);
        return before;
    }

    /** 重置連擊 */
    public void resetCombo(Player player) {
        comboMap.put(player.getUniqueId(), 0);
    }

    // ══════════════════════════════════════════
    //  靜止偵測
    // ══════════════════════════════════════════

    /**
     * 判斷玩家是否在過去 0.5 秒內靜止不動（XZ 位移 < 0.15 格）
     */
    public boolean isStill(Player player) {
        Location last = lastPositions.get(player.getUniqueId());
        if (last == null) return false;
        Location cur = player.getLocation();
        double dx = cur.getX() - last.getX();
        double dz = cur.getZ() - last.getZ();
        return Math.sqrt(dx * dx + dz * dz) < 0.15;
    }

    // ══════════════════════════════════════════
    //  追蹤標記系統
    // ══════════════════════════════════════════

    /**
     * 標記目標
     * @param player 標記者
     * @param target 被標記實體
     * @param durationTicks 持續 tick 數
     */
    public void markTarget(Player player, LivingEntity target, int durationTicks) {
        UUID pid = player.getUniqueId();
        markedTargets.put(pid, target.getUniqueId());
        markExpiries.put(pid, System.currentTimeMillis() + durationTicks * 50L);

        target.setGlowing(true);
        Bukkit.getScheduler().runTaskLater(plugin, () -> {
            if (!isMarked(player, target)) {
                target.setGlowing(false);
            }
        }, durationTicks);
    }

    /**
     * 判斷指定實體是否被該玩家標記
     */
    public boolean isMarked(Player player, LivingEntity entity) {
        UUID pid = player.getUniqueId();
        UUID targetId = markedTargets.get(pid);
        if (targetId == null) return false;
        Long expiry = markExpiries.get(pid);
        if (expiry == null || System.currentTimeMillis() > expiry) {
            markedTargets.remove(pid);
            markExpiries.remove(pid);
            return false;
        }
        return targetId.equals(entity.getUniqueId());
    }

    // ══════════════════════════════════════════
    //  清理
    // ══════════════════════════════════════════

    /** 玩家下線時清理所有狀態 */
    public void cleanup(Player player) {
        UUID pid = player.getUniqueId();
        focusMap.remove(pid);
        comboMap.remove(pid);
        lastFocusGainTime.remove(pid);
        lastComboTime.remove(pid);
        lastPositions.remove(pid);
        markedTargets.remove(pid);
        markExpiries.remove(pid);
    }

    // ══════════════════════════════════════════
    //  內部工具
    // ══════════════════════════════════════════

    /** 在 ActionBar 顯示專注條 */
    public void showFocusBar(Player player, int focus) {
        StringBuilder bar = new StringBuilder("§e[專注] ");
        for (int i = 0; i < MAX_FOCUS; i++) {
            bar.append(i < focus ? "§6◆" : "§8◇");
        }
        bar.append("  §f").append(focus).append("/").append(MAX_FOCUS);
        player.sendActionBar(bar.toString());
    }

    /** 啟動專注 & 連擊衰減任務（每 40 ticks / 2 秒） */
    private void startDecayTask() {
        new BukkitRunnable() {
            @Override
            public void run() {
                long now = System.currentTimeMillis();

                // 專注衰減：每次掉 1 點，直到歸零
                for (Map.Entry<UUID, Integer> entry : focusMap.entrySet()) {
                    if (entry.getValue() <= 0) continue;
                    Long last = lastFocusGainTime.get(entry.getKey());
                    if (last == null || now - last > FOCUS_DECAY_DELAY_MS) {
                        entry.setValue(entry.getValue() - 1);
                        if (entry.getValue() > 0) {
                            // 每衰減一次，重新計時（保持每 2 秒衰減一點的速度）
                            lastFocusGainTime.put(entry.getKey(), now);
                        }
                        Player p = Bukkit.getPlayer(entry.getKey());
                        if (p != null && entry.getValue() > 0) {
                            showFocusBar(p, entry.getValue());
                        }
                    }
                }

                // 連擊衰減：超過延遲後直接清零
                for (Map.Entry<UUID, Integer> entry : comboMap.entrySet()) {
                    if (entry.getValue() <= 0) continue;
                    Long last = lastComboTime.get(entry.getKey());
                    if (last == null || now - last > COMBO_DECAY_DELAY_MS) {
                        entry.setValue(0);
                    }
                }
            }
        }.runTaskTimer(plugin, 40L, 40L);
    }

    /** 啟動位置快照任務（每 10 ticks 更新一次，用於靜止偵測） */
    private void startPositionSnapshotTask() {
        new BukkitRunnable() {
            @Override
            public void run() {
                for (Player p : Bukkit.getOnlinePlayers()) {
                    lastPositions.put(p.getUniqueId(), p.getLocation().clone());
                }
            }
        }.runTaskTimer(plugin, 10L, 10L);
    }
}

package com.customrpg.managers;

import com.customrpg.CustomRPG;
import org.bukkit.GameMode;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.enchantments.Enchantment;
import org.bukkit.entity.*;
import org.bukkit.inventory.EntityEquipment;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.NamespacedKey;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.util.EulerAngle;
import org.bukkit.util.Vector;
import org.bukkit.util.Transformation;
import org.joml.AxisAngle4f;
import org.joml.Vector3f;

import java.util.*;

/**
 * MobManager - Manages custom mob types and spawning
 *
 * This class handles the registration and spawning of custom mobs with unique
 * properties and behaviors. Custom mobs are marked with persistent data to
 * identify them and trigger special mechanics.
 *
 * Example custom mobs:
 * - Snow Zombie: Throws snowballs
 * - Fire Skeleton: Shoots fire arrows
 * - Giant Slime: Extra large, splits on death
 */
public class MobManager {

    private final CustomRPG plugin;
    private final Map<String, MobData> mobTypes;
    private final NamespacedKey customMobKey;
    private final NamespacedKey mobLevelKey;
    private final NamespacedKey mobTierKey;
    private final ConfigManager configManager;
    private final Random random;

    /**
     * Constructor for MobManager
     * @param plugin Main plugin instance
     * @param configManager Config manager for loading mob configs
     */
    public MobManager(CustomRPG plugin, ConfigManager configManager) {
        this.plugin = plugin;
        this.configManager = configManager;
        this.mobTypes = new HashMap<>();
        this.customMobKey = new NamespacedKey(plugin, "custom_mob_type");
        this.mobLevelKey = new NamespacedKey(plugin, "mob_level");
        this.mobTierKey = new NamespacedKey(plugin, "mob_tier");
        this.random = new Random();
        loadMobTypes();
    }

    /**
     * Load all custom mob types from config/mobs/types/ folder
     */
    private void loadMobTypes() {
        Map<String, Map<String, Object>> allMobs = configManager.getAllMobs();

        if (allMobs.isEmpty()) {
            plugin.getLogger().warning("No mobs found in config/mobs/types/ folder");
            return;
        }

        for (Map.Entry<String, Map<String, Object>> entry : allMobs.entrySet()) {
            String mobKey = entry.getKey();
            Map<String, Object> mobConfig = entry.getValue();

            try {
                MobData mobData = parseMobData(mobKey, mobConfig);
                mobTypes.put(mobKey, mobData);
                plugin.getLogger().info("Loaded custom mob: " + mobData.getName() +
                    (mobData.hasLevelSystem() ? " (Lv." + mobData.getMinLevel() + "-" + mobData.getMaxLevel() + ")" : ""));
            } catch (Exception e) {
                plugin.getLogger().warning("Failed to load mob '" + mobKey + "': " + e.getMessage());
                e.printStackTrace();
            }
        }
    }

    /**
     * Parse mob data from config (supports both old and new formats)
     */
    private MobData parseMobData(String key, Map<String, Object> config) {
        String name = (String) config.getOrDefault("name", key);
        EntityType entityType = EntityType.valueOf((String) config.get("type"));
        String specialBehavior = (String) config.getOrDefault("special-behavior", "none");

        // 檢查是否為新格式（包含 level-range 或 base-stats）
        boolean isNewFormat = config.containsKey("level-range") || config.containsKey("base-stats");

        if (isNewFormat) {
            return parseEnhancedMobData(key, name, entityType, specialBehavior, config);
        } else {
            // 舊格式（向後兼容）
            double health = getDouble(config, "health", 20.0);
            double damage = getDouble(config, "damage", 1.0);
            int exp = getInt(config, "exp", 0);
            return new MobData(key, name, entityType, health, damage, specialBehavior, exp);
        }
    }

    /**
     * Parse enhanced mob data (new format)
     */
    @SuppressWarnings("unchecked")
    private MobData parseEnhancedMobData(String key, String name, EntityType entityType,
                                          String specialBehavior, Map<String, Object> config) {
        // 等級範圍
        int minLevel = 1;
        int maxLevel = 1;
        if (config.containsKey("level-range")) {
            Map<String, Object> levelRange = (Map<String, Object>) config.get("level-range");
            minLevel = getInt(levelRange, "min", 1);
            maxLevel = getInt(levelRange, "max", 1);
        }

        // 基礎屬性
        double baseHealth = 20.0;
        double baseDamage = 1.0;
        if (config.containsKey("base-stats")) {
            Map<String, Object> baseStats = (Map<String, Object>) config.get("base-stats");
            baseHealth = getDouble(baseStats, "health", 20.0);
            baseDamage = getDouble(baseStats, "damage", 1.0);
        }

        // 屬性成長
        double healthPerLevel = 0;
        double damagePerLevel = 0;
        if (config.containsKey("stat-scaling")) {
            Map<String, Object> scaling = (Map<String, Object>) config.get("stat-scaling");
            healthPerLevel = getDouble(scaling, "health-per-level", 0);
            damagePerLevel = getDouble(scaling, "damage-per-level", 0);
        }

        // 經驗值
        int baseExp = 0;
        int expPerLevel = 0;
        if (config.containsKey("exp")) {
            Object expObj = config.get("exp");
            if (expObj instanceof Map) {
                // 新格式：exp 是一個 Map
                Map<String, Object> expConfig = (Map<String, Object>) expObj;
                baseExp = getInt(expConfig, "base", 0);
                expPerLevel = getInt(expConfig, "per-level", 0);
            } else {
                // 舊格式或簡化格式：exp 是一個整數
                baseExp = getInt(config, "exp", 0);
                expPerLevel = 0;
            }
        }

        // 裝備
        Map<String, ItemStack> equipment = parseEquipment(config);

        // 掉落物
        List<DropItem> vanillaDrops = new ArrayList<>();
        List<WeaponDrop> weaponDrops = new ArrayList<>();
        List<EquipmentDrop> equipmentDrops = new ArrayList<>();
        if (config.containsKey("drops")) {
            Map<String, Object> drops = (Map<String, Object>) config.get("drops");
            vanillaDrops = parseVanillaDrops(drops);
            weaponDrops = parseWeaponDrops(drops);
            equipmentDrops = parseEquipmentDrops(drops);
        }

        // 偽裝
        DisguiseConfig disguise = parseDisguise(config);

        // 其他設定
        boolean showLevelInName = (boolean) config.getOrDefault("show-level-in-name", false);

        // 生態域標籤
        List<String> tags = new ArrayList<>();
        Object tagsObj = config.get("tags");
        if (tagsObj instanceof List) {
            for (Object t : (List<?>) tagsObj) {
                if (t != null) tags.add(t.toString().toLowerCase());
            }
        }

        // 是否為 Boss 怪物
        boolean isBoss = Boolean.TRUE.equals(config.get("boss"));

        // 生成時段 (all / night / day)
        String spawnTime = config.getOrDefault("spawn-time", "all").toString().toLowerCase();

        return new MobData(key, name, entityType, minLevel, maxLevel,
                          baseHealth, baseDamage, healthPerLevel, damagePerLevel,
                          baseExp, expPerLevel, equipment, vanillaDrops, weaponDrops,
                          equipmentDrops, disguise, specialBehavior, showLevelInName, tags, isBoss, spawnTime);
    }

    /**
     * Parse equipment from config
     */
    @SuppressWarnings("unchecked")
    private Map<String, ItemStack> parseEquipment(Map<String, Object> config) {
        Map<String, ItemStack> equipment = new HashMap<>();

        if (!config.containsKey("equipment")) {
            return equipment;
        }

        Map<String, Object> equipConfig = (Map<String, Object>) config.get("equipment");
        String[] slots = {"helmet", "chestplate", "leggings", "boots", "main-hand", "off-hand"};

        for (String slot : slots) {
            if (equipConfig.containsKey(slot)) {
                Map<String, Object> itemConfig = (Map<String, Object>) equipConfig.get(slot);
                ItemStack item = parseItemStack(itemConfig);
                if (item != null) {
                    equipment.put(slot, item);
                }
            }
        }

        return equipment;
    }

    /**
     * Parse ItemStack from config
     */
    @SuppressWarnings("unchecked")
    private ItemStack parseItemStack(Map<String, Object> config) {
        try {
            Material material = Material.valueOf((String) config.get("material"));
            ItemStack item = new ItemStack(material);

            // 附魔
            if (config.containsKey("enchantments")) {
                List<Map<String, Object>> enchants = (List<Map<String, Object>>) config.get("enchantments");
                ItemMeta meta = item.getItemMeta();
                for (Map<String, Object> enchant : enchants) {
                    String enchantName = (String) enchant.get("type");
                    int level = getInt(enchant, "level", 1);
                    Enchantment enchantment = Enchantment.getByName(enchantName);
                    if (enchantment != null && meta != null) {
                        meta.addEnchant(enchantment, level, true);
                    }
                }
                item.setItemMeta(meta);
            }

            // 玩家頭顱 (skull-owner)
            if (material == Material.PLAYER_HEAD && config.containsKey("skull-owner")) {
                String owner = (String) config.get("skull-owner");
                org.bukkit.inventory.meta.SkullMeta skullMeta = (org.bukkit.inventory.meta.SkullMeta) item.getItemMeta();
                if (skullMeta != null) {
                    skullMeta.setOwner(owner);
                    item.setItemMeta(skullMeta);
                }
            }

            // 皮革裝甲染色 (color)
            if (config.containsKey("color") && item.getItemMeta() instanceof org.bukkit.inventory.meta.LeatherArmorMeta leatherMeta) {
                String colorStr = (String) config.get("color");
                try {
                    String[] rgb = colorStr.split(",");
                    org.bukkit.Color color = org.bukkit.Color.fromRGB(
                            Integer.parseInt(rgb[0].trim()),
                            Integer.parseInt(rgb[1].trim()),
                            Integer.parseInt(rgb[2].trim()));
                    leatherMeta.setColor(color);
                    item.setItemMeta(leatherMeta);
                } catch (Exception e) {
                    plugin.getLogger().warning("Failed to parse leather color: " + colorStr);
                }
            }

            return item;
        } catch (Exception e) {
            plugin.getLogger().warning("Failed to parse item: " + e.getMessage());
            return null;
        }
    }

    /**
     * Parse vanilla drops from config
     */
    @SuppressWarnings("unchecked")
    private List<DropItem> parseVanillaDrops(Map<String, Object> drops) {
        List<DropItem> vanillaDrops = new ArrayList<>();

        if (!drops.containsKey("vanilla-items")) {
            return vanillaDrops;
        }

        List<Map<String, Object>> items = (List<Map<String, Object>>) drops.get("vanilla-items");
        for (Map<String, Object> itemConfig : items) {
            try {
                Material material = Material.valueOf((String) itemConfig.get("material"));
                String amountStr = (String) itemConfig.getOrDefault("amount", "1");
                double chance = getDouble(itemConfig, "chance", 1.0);

                int minAmount = 1;
                int maxAmount = 1;
                if (amountStr.contains("-")) {
                    String[] parts = amountStr.split("-");
                    minAmount = Integer.parseInt(parts[0]);
                    maxAmount = Integer.parseInt(parts[1]);
                } else {
                    minAmount = maxAmount = Integer.parseInt(amountStr);
                }

                vanillaDrops.add(new DropItem(material, minAmount, maxAmount, chance));
            } catch (Exception e) {
                plugin.getLogger().warning("Failed to parse drop item: " + e.getMessage());
            }
        }

        return vanillaDrops;
    }

    /**
     * Parse weapon drops from config
     */
    @SuppressWarnings("unchecked")
    private List<WeaponDrop> parseWeaponDrops(Map<String, Object> drops) {
        List<WeaponDrop> weaponDrops = new ArrayList<>();

        if (!drops.containsKey("custom-weapons")) {
            return weaponDrops;
        }

        List<Map<String, Object>> weapons = (List<Map<String, Object>>) drops.get("custom-weapons");
        for (Map<String, Object> weaponConfig : weapons) {
            String weaponKey = (String) weaponConfig.get("weapon-key");
            double chance = getDouble(weaponConfig, "chance", 0.01);
            weaponDrops.add(new WeaponDrop(weaponKey, chance));
        }

        return weaponDrops;
    }

    /**
     * Parse equipment drops (accessories & armor) from config
     */
    @SuppressWarnings("unchecked")
    private List<EquipmentDrop> parseEquipmentDrops(Map<String, Object> drops) {
        List<EquipmentDrop> equipmentDrops = new ArrayList<>();

        if (!drops.containsKey("custom-equipment")) {
            return equipmentDrops;
        }

        List<Map<String, Object>> equipList = (List<Map<String, Object>>) drops.get("custom-equipment");
        for (Map<String, Object> equipConfig : equipList) {
            String equipKey = (String) equipConfig.get("equipment-key");
            String type = (String) equipConfig.getOrDefault("type", "accessory"); // "accessory" 或 "armor"
            double chance = getDouble(equipConfig, "chance", 0.01);
            equipmentDrops.add(new EquipmentDrop(equipKey, type, chance));
        }

        return equipmentDrops;
    }

    /**
     * Parse disguise config
     */
    @SuppressWarnings("unchecked")
    private DisguiseConfig parseDisguise(Map<String, Object> config) {
        if (!config.containsKey("disguise")) {
            return null;
        }

        Map<String, Object> disguiseConfig = (Map<String, Object>) config.get("disguise");
        boolean enabled = (boolean) disguiseConfig.getOrDefault("enabled", false);

        if (!enabled) {
            return null;
        }

        EntityType disguiseType = EntityType.valueOf((String) disguiseConfig.getOrDefault("type", "PIG"));
        double babyChance = getDouble(disguiseConfig, "baby-chance", 0);

        return new DisguiseConfig(enabled, disguiseType, babyChance);
    }

    // 輔助方法
    private double getDouble(Map<String, Object> map, String key, double defaultValue) {
        Object value = map.get(key);
        if (value instanceof Number) {
            return ((Number) value).doubleValue();
        }
        return defaultValue;
    }

    private int getInt(Map<String, Object> map, String key, int defaultValue) {
        Object value = map.get(key);
        if (value instanceof Number) {
            return ((Number) value).intValue();
        }
        return defaultValue;
    }

    /**
     * Spawn a custom mob at the specified location
     * @param mobKey The mob type identifier
     * @param location The spawn location
     * @return The spawned entity, or null if mob type not found
     */
    public LivingEntity spawnCustomMob(String mobKey, Location location) {
        MobData mobData = mobTypes.get(mobKey);
        if (mobData == null) {
            return null;
        }

        // 生成隨機等級
        int level = mobData.getMinLevel();
        if (mobData.getMaxLevel() > mobData.getMinLevel()) {
            level = random.nextInt(mobData.getMaxLevel() - mobData.getMinLevel() + 1) + mobData.getMinLevel();
        }

        // 檢查是否需要偽裝
        LivingEntity mob;
        if (mobData.getDisguise() != null && mobData.getDisguise().isEnabled()) {
            mob = spawnDisguisedMob(mobData, location, level);
        } else {
            mob = spawnNormalMob(mobData, location, level);
        }

        if (mob == null) {
            return null;
        }

        // 設置持久化數據
        mob.getPersistentDataContainer().set(customMobKey, PersistentDataType.STRING, mobKey);
        mob.getPersistentDataContainer().set(mobLevelKey, PersistentDataType.INTEGER, level);

        plugin.getLogger().info("Spawned custom mob: " + mobData.getName() + " (Lv." + level + ") at " + location);
        return mob;
    }

    /**
     * Spawn a custom mob at a specified location with a specified level
     * @param mobKey The mob type identifier
     * @param location The spawn location
     * @param level The desired level for the mob
     * @return The spawned entity, or null if mob type not found
     */
    public LivingEntity spawnCustomMobWithLevel(String mobKey, Location location, int level) {
        MobData mobData = mobTypes.get(mobKey);
        if (mobData == null) {
            return null;
        }

        // Clamp level to at least 1
        level = Math.max(1, level);

        // 檢查是否需要偽裝
        LivingEntity mob;
        if (mobData.getDisguise() != null && mobData.getDisguise().isEnabled()) {
            mob = spawnDisguisedMob(mobData, location, level);
        } else {
            mob = spawnNormalMob(mobData, location, level);
        }

        if (mob == null) {
            return null;
        }

        // 設置持久化數據
        mob.getPersistentDataContainer().set(customMobKey, PersistentDataType.STRING, mobKey);
        mob.getPersistentDataContainer().set(mobLevelKey, PersistentDataType.INTEGER, level);

        return mob;
    }

    /**
     * Set the tier tag on a mob entity
     * @param entity The entity
     * @param tier The tier string (NORMAL, ELITE, BOSS)
     */
    public void setMobTier(LivingEntity entity, String tier) {
        entity.getPersistentDataContainer().set(mobTierKey, PersistentDataType.STRING, tier);
    }

    /**
     * Get the tier of a custom mob
     * @param entity The entity to check
     * @return Tier string ("NORMAL", "ELITE", "BOSS"), or "NORMAL" if not set
     */
    public String getMobTier(Entity entity) {
        if (!(entity instanceof LivingEntity mob)) {
            return "NORMAL";
        }
        String tier = mob.getPersistentDataContainer().get(mobTierKey, PersistentDataType.STRING);
        return tier != null ? tier : "NORMAL";
    }

    /**
     * Get all registered mob types
     * @return Collection of MobData
     */
    public java.util.Collection<MobData> getMobTypes() {
        return mobTypes.values();
    }

    /**
     * Get the custom mob NamespacedKey (for external checks)
     */
    public NamespacedKey getCustomMobNamespacedKey() {
        return customMobKey;
    }

    /**
     * Spawn a normal (non-disguised) mob
     */
    private LivingEntity spawnNormalMob(MobData mobData, Location location, int level) {
        Entity entity = location.getWorld().spawnEntity(location, mobData.getEntityType());
        if (!(entity instanceof LivingEntity)) {
            entity.remove();
            return null;
        }

        LivingEntity mob = (LivingEntity) entity;

        // 設置名稱
        String displayName = mobData.getName();
        if (mobData.shouldShowLevelInName() && mobData.hasLevelSystem()) {
            displayName = "&8[&eLv." + level + "&8] " + mobData.getName();
        }
        mob.setCustomName(org.bukkit.ChatColor.translateAlternateColorCodes('&', displayName));
        mob.setCustomNameVisible(true);

        // 設置等級化屬性
        double health = mobData.calculateHealth(level);
        mob.setMaxHealth(health);
        mob.setHealth(health);

        // 裝備物品
        applyEquipment(mob, mobData);

        return mob;
    }

    /**
     * Spawn a disguised mob (directly spawn as disguise type with custom behavior)
     * 直接生成偽裝類型的生物，根據類型決定實現方式
     */
    private LivingEntity spawnDisguisedMob(MobData mobData, Location location, int level) {
        DisguiseConfig disguise = mobData.getDisguise();

        // 特殊處理：盔甲架偽裝（用於創建純視覺效果，如行走的仙人掌方塊）
        if (disguise.getDisguiseType() == EntityType.ARMOR_STAND) {
            return spawnArmorStandDisguise(mobData, location, level);
        }

        // 特殊處理：檢查是否配置了方塊材質的 helmet（用於創建行走的方塊）
        // 當裝備中的 helmet 是方塊類型時，使用 BlockDisplay 方式顯示
        if (mobData.getEquipment().containsKey("helmet")) {
            ItemStack helmetItem = mobData.getEquipment().get("helmet");
            Material helmetMaterial = helmetItem.getType();

            // 檢查是否為適合當 BlockDisplay 的方塊材料
            // (isBlock() 足夠判斷，不需要排除 isItem()，因為很多方塊同時也是物品)
            if (helmetMaterial.isBlock() && isBlockDisplayCandidate(helmetMaterial)) {
                plugin.getLogger().info("檢測到方塊材質頭盔: " + helmetMaterial.name() + "，使用 BlockDisplay 模式");
                return spawnArmorStandDisguise(mobData, location, level);
            }
        }

        // 一般偽裝：直接生成偽裝實體（例如：豬）
        Entity disguiseEntity = location.getWorld().spawnEntity(location, disguise.getDisguiseType());
        if (!(disguiseEntity instanceof LivingEntity)) {
            disguiseEntity.remove();
            return null;
        }

        LivingEntity mob = (LivingEntity) disguiseEntity;

        // 設置名稱
        String displayName = mobData.getName();
        if (mobData.shouldShowLevelInName() && mobData.hasLevelSystem()) {
            displayName = "&8[&eLv." + level + "&8] " + mobData.getName();
        }
        mob.setCustomName(org.bukkit.ChatColor.translateAlternateColorCodes('&', displayName));
        mob.setCustomNameVisible(true);

        // 設置等級化屬性
        double health = mobData.calculateHealth(level);
        mob.setMaxHealth(health);
        mob.setHealth(health);

        // 隨機幼年
        if (disguise.getBabyChance() > 0 && random.nextDouble() < disguise.getBabyChance()) {
            if (mob instanceof org.bukkit.entity.Ageable) {
                ((org.bukkit.entity.Ageable) mob).setBaby();
            }
        }

        // 裝備物品
        applyEquipment(mob, mobData);

        // 只有當生物是被動類型且設置了傷害值時，才賦予攻擊行為
        if (isPassiveMob(disguise.getDisguiseType()) && mobData.getBaseDamage() > 0) {
            applyAggressiveBehavior(mob);
        }

        return mob;
    }

    /**
     * Spawn BlockDisplay disguise - creates a walking block (like cactus)
     * 使用 BlockDisplay 生成會行走的方塊偽裝（如仙人掌）
     *
     * 架構說明：
     * 1. 隱形殭屍作為移動核心（提供 AI 和碰撞）
     * 2. BlockDisplay 作為視覺顯示（精準位置控制）
     * 3. ArmorStand 作為名稱標籤（顯示名稱和等級）
     *
     * BlockDisplay 的優勢：
     * - 不受乘客系統限制，可以精準設置位置
     * - 支援 Transformation 調整偏移、旋轉、縮放
     * - 平滑插值移動（setTeleportDuration）
     * - 可以顯示任何方塊類型
     */
    private LivingEntity spawnArmorStandDisguise(MobData mobData, Location location, int level) {
        plugin.getLogger().info("=== 開始生成 BlockDisplay 行走方塊 ===");

        // ===== 第一步：生成隱形殭屍核心 =====
        Entity coreEntity = location.getWorld().spawnEntity(location, EntityType.ZOMBIE);
        if (!(coreEntity instanceof Zombie core)) {
            coreEntity.remove();
            plugin.getLogger().severe("✗ 無法生成殭屍核心");
            return null;
        }

        // 設置殭屍屬性（隱形、靜音、保持 AI）
        core.setAdult();
        core.setInvisible(true);
        core.setSilent(true);
        core.setAI(true);
        core.setRemoveWhenFarAway(false);
        core.setCanPickupItems(false);
        core.setShouldBurnInDay(false); // 殭屍不會在白天燃燒

        // 清空裝備、掉落率歸零（不戴任何東西，避免看到裝備）
        if (core.getEquipment() != null) {
            core.getEquipment().clear();
            core.getEquipment().setHelmetDropChance(0f);
            core.getEquipment().setChestplateDropChance(0f);
            core.getEquipment().setLeggingsDropChance(0f);
            core.getEquipment().setBootsDropChance(0f);
            core.getEquipment().setItemInMainHandDropChance(0f);
            core.getEquipment().setItemInOffHandDropChance(0f);
        }

        // 設置生命值和傷害（等級化）
        double health = mobData.calculateHealth(level);
        core.getAttribute(org.bukkit.attribute.Attribute.MAX_HEALTH).setBaseValue(health);
        core.setHealth(health);

        // 設置攻擊力（等級化）
        double damage = mobData.calculateDamage(level);
        core.getAttribute(org.bukkit.attribute.Attribute.ATTACK_DAMAGE).setBaseValue(damage);

        plugin.getLogger().info("✓ 殭屍核心已生成 (隱形, Lv." + level + ", HP:" + health + ", ATK:" + damage + ")");

        // **重要：標記殭屍核心為自定義怪物**
        // 這樣 MobListener 才能識別並正確處理傷害、掉落物、經驗值
        core.getPersistentDataContainer().set(customMobKey, PersistentDataType.STRING, mobData.getKey());
        core.getPersistentDataContainer().set(mobLevelKey, PersistentDataType.INTEGER, level);
        plugin.getLogger().info("✓ 殭屍核心已標記為自定義怪物: " + mobData.getKey() + " (Lv." + level + ")");

        // ===== 第二步：獲取方塊類型 =====
        Material blockMaterial = Material.CACTUS;
        if (mobData.getEquipment().containsKey("helmet")) {
            ItemStack helmetItem = mobData.getEquipment().get("helmet");
            blockMaterial = helmetItem.getType();
        }
        plugin.getLogger().info("✓ 方塊材質: " + blockMaterial.name());

        // ===== 第三步：生成 BlockDisplay =====
        Location displayLocation = location.clone();
        BlockDisplay blockDisplay = (BlockDisplay) location.getWorld().spawnEntity(
            displayLocation,
            EntityType.BLOCK_DISPLAY
        );

        // 設置方塊數據
        blockDisplay.setBlock(blockMaterial.createBlockData());

        // 設置 Transformation（精準位置控制的關鍵）
        // BlockDisplay 從座標角落開始渲染 (1x1x1 方塊)
        // 殭屍碰撞箱中心在 spawn 點，寬 0.6
        // 所以 X/Z 各偏移 -0.5 讓方塊中心對齊殭屍中心
        // Y=0 讓方塊底部對齊殭屍腳底（地面）
        Vector3f translation = new Vector3f(-0.5f, 0f, -0.5f);
        AxisAngle4f leftRotation = new AxisAngle4f(0, 0, 1, 0); // 無旋轉
        Vector3f scale = new Vector3f(1.0f, 1.0f, 1.0f); // 原始大小
        AxisAngle4f rightRotation = new AxisAngle4f(0, 0, 1, 0); // 無旋轉

        Transformation transformation = new Transformation(translation, leftRotation, scale, rightRotation);
        blockDisplay.setTransformation(transformation);

        // 設置顯示屬性
        blockDisplay.setTeleportDuration(2); // 平滑傳送（2 ticks = 0.1秒）
        blockDisplay.setInterpolationDuration(2); // 插值時間
        blockDisplay.setInterpolationDelay(0); // 立即開始插值
        blockDisplay.setViewRange(128.0f); // 可視範圍 128 格
        blockDisplay.setBrightness(new org.bukkit.entity.Display.Brightness(15, 15)); // 最大亮度（不受環境影響）
        blockDisplay.setShadowRadius(0.5f); // 陰影半徑
        blockDisplay.setShadowStrength(1.0f); // 陰影強度

        // 標記為偽裝實體（用於清理和識別）
        blockDisplay.getPersistentDataContainer().set(
            new NamespacedKey(plugin, "disguise_blockdisplay"),
            PersistentDataType.STRING,
            core.getUniqueId().toString()
        );

        plugin.getLogger().info("✓ BlockDisplay 已生成（平滑移動: 2 ticks）");

        // ===== 第四步：生成名稱標籤 ArmorStand =====
        Location nameLocation = location.clone().add(0, 1.3, 0); // 方塊頂部上方
        ArmorStand nameTag = (ArmorStand) location.getWorld().spawnEntity(
            nameLocation,
            EntityType.ARMOR_STAND
        );

        // 設置為隱形 marker（不占空間、不碰撞、不受重力）
        nameTag.setVisible(false);
        nameTag.setGravity(false);
        nameTag.setInvulnerable(true);
        nameTag.setMarker(true);
        nameTag.setSmall(true);
        nameTag.setBasePlate(false);
        nameTag.setArms(false);

        // 設置名稱
        String displayName = mobData.getName();
        if (mobData.shouldShowLevelInName() && mobData.hasLevelSystem()) {
            displayName = "&8[&eLv." + level + "&8] " + mobData.getName();
        }
        nameTag.customName(net.kyori.adventure.text.Component.text(
            org.bukkit.ChatColor.translateAlternateColorCodes('&', displayName)
        ));
        nameTag.setCustomNameVisible(true);

        // 標記為偽裝名稱標籤
        nameTag.getPersistentDataContainer().set(
            new NamespacedKey(plugin, "disguise_nametag"),
            PersistentDataType.STRING,
            core.getUniqueId().toString()
        );

        plugin.getLogger().info("✓ 名稱標籤已生成: " + displayName);

        // ===== 第五步：建立位置同步系統 =====
        // 使用高頻率更新（每 tick）確保 BlockDisplay 跟隨殭屍移動
        // 這是精準控制位置的關鍵
        new BukkitRunnable() {
            private Location lastCoreLoc = null;
            private int tickCounter = 0;

            @Override
            public void run() {
                // 檢查核心是否還存在
                if (core.isDead() || !core.isValid()) {
                    // 清理所有關聯實體
                    if (blockDisplay.isValid()) blockDisplay.remove();
                    if (nameTag.isValid()) nameTag.remove();
                    this.cancel();
                    plugin.getLogger().info("✗ BlockDisplay 已清理（核心死亡）");
                    return;
                }

                // 獲取殭屍當前位置
                Location coreLoc = core.getLocation();
                tickCounter++;

                // 同步 BlockDisplay 位置
                if (blockDisplay.isValid()) {
                    // 檢查位置是否改變（優化性能）
                    boolean moved = lastCoreLoc == null ||
                                  lastCoreLoc.getX() != coreLoc.getX() ||
                                  lastCoreLoc.getY() != coreLoc.getY() ||
                                  lastCoreLoc.getZ() != coreLoc.getZ();

                    if (moved) {
                        // 精準設置 BlockDisplay 位置
                        // BlockDisplay 的 transformation 已經處理了 Y 軸偏移
                        Location blockLoc = coreLoc.clone();
                        blockLoc.setYaw(0); // BlockDisplay 不需要旋轉（方塊是立方體）
                        blockLoc.setPitch(0);
                        blockDisplay.teleport(blockLoc);

                        lastCoreLoc = coreLoc.clone();
                    }
                } else {
                    // BlockDisplay 消失，清理所有
                    if (nameTag.isValid()) nameTag.remove();
                    core.remove();
                    this.cancel();
                    return;
                }

                // 同步名稱標籤位置（在方塊上方）
                if (nameTag.isValid()) {
                    Location nameLoc = coreLoc.clone().add(0, 1.3, 0);
                    nameLoc.setYaw(0);
                    nameLoc.setPitch(0);
                    nameTag.teleport(nameLoc);
                } else {
                    // 名稱標籤消失，清理所有
                    if (blockDisplay.isValid()) blockDisplay.remove();
                    core.remove();
                    this.cancel();
                    return;
                }

                // 每 100 ticks（5秒）輸出一次調試信息
                if (tickCounter % 100 == 0) {
                    plugin.getLogger().fine("BlockDisplay 同步中 (tick " + tickCounter + ")");
                }
            }
        }.runTaskTimer(plugin, 0L, 1L); // 每 tick 更新（20 次/秒）

        plugin.getLogger().info("=== BlockDisplay 行走方塊生成完成 ===");
        plugin.getLogger().info("  實體 UUID: " + core.getUniqueId());
        plugin.getLogger().info("  方塊類型: " + blockMaterial.name());
        plugin.getLogger().info("  顯示名稱: " + displayName);
        plugin.getLogger().info("  等級: " + level + " | HP: " + health + " | ATK: " + damage);

        return core;
    }

    /**
     * Check if an entity type is a passive mob
     * 檢查生物類型是否為被動生物
     */
    private boolean isPassiveMob(EntityType type) {
        switch (type) {
            // 被動生物
            case PIG:
            case COW:
            case SHEEP:
            case CHICKEN:
            case RABBIT:
            case HORSE:
            case DONKEY:
            case MULE:
            case LLAMA:
            case PARROT:
            case BAT:
            case OCELOT:
            case CAT:
            case PANDA:
            case FOX:
            case VILLAGER:
            case WANDERING_TRADER:
            case IRON_GOLEM:
            case SNOW_GOLEM:
            case TURTLE:
            case MOOSHROOM:
            case SQUID:
            case GLOW_SQUID:
            case COD:
            case SALMON:
            case TROPICAL_FISH:
            case PUFFERFISH:
            case DOLPHIN:
            case AXOLOTL:
            case STRIDER:
                return true;
            default:
                return false;
        }
    }

    /**
     * 判斷材料是否適合做 BlockDisplay 偽裝
     * (非穿戴型方塊，如仙人掌、TNT、南瓜等)
     */
    private boolean isBlockDisplayCandidate(Material mat) {
        // 非方塊材料一律不行
        if (!mat.isBlock()) return false;

        // 排除正常盔甲 / 頭顱（這些應該直接穿戴）
        String name = mat.name();
        if (name.contains("HELMET") || name.contains("CHESTPLATE")
                || name.contains("LEGGINGS") || name.contains("BOOTS")
                || name.contains("_HEAD") || name.contains("_SKULL")) {
            return false;
        }

        // 其餘方塊都視為 BlockDisplay 候選
        return true;
    }

    /**
     * Apply aggressive behavior to passive mobs
     * 讓被動生物（如豬、雞等）能夠攻擊玩家
     */
    private void applyAggressiveBehavior(LivingEntity mob) {
        try {
            // 使用 Bukkit API 讓生物主動尋找附近的玩家並攻擊
            // 透過定期任務模擬攻擊行為
            new BukkitRunnable() {
                @Override
                public void run() {
                    if (mob.isDead() || !mob.isValid()) {
                        this.cancel();
                        return;
                    }

                    // 檢查附近是否有玩家
                    Player target = findNearestPlayer(mob, 16.0);
                    if (target != null && target.getGameMode() != org.bukkit.GameMode.CREATIVE &&
                        target.getGameMode() != org.bukkit.GameMode.SPECTATOR) {

                        // 設置生物的目標為玩家
                        if (mob instanceof Mob) {
                            ((Mob) mob).setTarget(target);
                        }

                        // 讓生物朝玩家移動
                        Location targetLoc = target.getLocation();
                        Location mobLoc = mob.getLocation();

                        double distance = mobLoc.distance(targetLoc);

                        // 計算朝向玩家的角度
                        Vector direction = targetLoc.toVector().subtract(mobLoc.toVector());
                        double yaw = Math.toDegrees(Math.atan2(-direction.getX(), direction.getZ()));
                        double pitch = Math.toDegrees(Math.atan2(-direction.getY(),
                            Math.sqrt(direction.getX() * direction.getX() + direction.getZ() * direction.getZ())));

                        // 設置生物朝向玩家
                        Location newLoc = mobLoc.clone();
                        newLoc.setYaw((float) yaw);
                        newLoc.setPitch((float) pitch);
                        mob.teleport(newLoc);

                        // 如果在攻擊範圍內（2格內），則進行攻擊
                        if (distance <= 2.0) {
                            // 透過 EntityDamageByEntityEvent 處理傷害
                            // 這裡只需要標記，實際傷害由事件處理
                            target.damage(0.1, mob); // 極小傷害，實際傷害在事件中設置
                        } else if (distance <= 16.0) {
                            // 計算移動方向（水平）
                            direction.normalize();
                            direction.setY(0); // 保持在水平面移動

                            // 設置速度（追逐玩家）
                            Vector velocity = direction.multiply(0.3);
                            velocity.setY(mob.getVelocity().getY()); // 保持原有的Y軸速度（重力）
                            mob.setVelocity(velocity);
                        }
                    }
                }
            }.runTaskTimer(plugin, 0L, 10L); // 每 0.5 秒執行一次

        } catch (Exception e) {
            plugin.getLogger().warning("Failed to apply aggressive behavior: " + e.getMessage());
        }
    }

    /**
     * Find the nearest player to a mob within range
     */
    private Player findNearestPlayer(LivingEntity mob, double range) {
        Player nearest = null;
        double nearestDistance = range * range; // 使用平方距離避免開方運算

        for (Player player : mob.getWorld().getPlayers()) {
            if (player.getGameMode() == org.bukkit.GameMode.CREATIVE ||
                player.getGameMode() == org.bukkit.GameMode.SPECTATOR) {
                continue;
            }

            double distanceSquared = player.getLocation().distanceSquared(mob.getLocation());
            if (distanceSquared < nearestDistance) {
                nearest = player;
                nearestDistance = distanceSquared;
            }
        }

        return nearest;
    }

    /**
     * Apply equipment to a mob
     */
    private void applyEquipment(LivingEntity mob, MobData mobData) {
        EntityEquipment equipment = mob.getEquipment();
        if (equipment == null) {
            return;
        }

        Map<String, ItemStack> equipmentMap = mobData.getEquipment();

        if (equipmentMap.containsKey("helmet")) {
            equipment.setHelmet(equipmentMap.get("helmet"));
            equipment.setHelmetDropChance(0.0f);
        }
        if (equipmentMap.containsKey("chestplate")) {
            equipment.setChestplate(equipmentMap.get("chestplate"));
            equipment.setChestplateDropChance(0.0f);
        }
        if (equipmentMap.containsKey("leggings")) {
            equipment.setLeggings(equipmentMap.get("leggings"));
            equipment.setLeggingsDropChance(0.0f);
        }
        if (equipmentMap.containsKey("boots")) {
            equipment.setBoots(equipmentMap.get("boots"));
            equipment.setBootsDropChance(0.0f);
        }
        if (equipmentMap.containsKey("main-hand")) {
            equipment.setItemInMainHand(equipmentMap.get("main-hand"));
            equipment.setItemInMainHandDropChance(0.0f);
        }
        if (equipmentMap.containsKey("off-hand")) {
            equipment.setItemInOffHand(equipmentMap.get("off-hand"));
            equipment.setItemInOffHandDropChance(0.0f);
        }
    }

    /**
     * Check if an entity is a custom mob
     * @param entity The entity to check
     * @return Mob key if it's a custom mob, null otherwise
     */
    public String getCustomMobKey(Entity entity) {
        if (!(entity instanceof LivingEntity)) {
            return null;
        }

        LivingEntity mob = (LivingEntity) entity;
        return mob.getPersistentDataContainer().get(customMobKey, PersistentDataType.STRING);
    }

    /**
     * Get the level of a custom mob
     * @param entity The entity to check
     * @return Mob level, or 1 if not found
     */
    public int getMobLevel(Entity entity) {
        if (!(entity instanceof LivingEntity)) {
            return 1;
        }

        LivingEntity mob = (LivingEntity) entity;
        Integer level = mob.getPersistentDataContainer().get(mobLevelKey, PersistentDataType.INTEGER);
        return level != null ? level : 1;
    }

    /**
     * Get mob data by key
     * @param mobKey The mob identifier
     * @return MobData or null if not found
     */
    public MobData getMobData(String mobKey) {
        return mobTypes.get(mobKey);
    }

    /**
     * Get the number of registered custom mob types
     * @return Number of custom mob types
     */
    public int getMobTypeCount() {
        return mobTypes.size();
    }

    /**
     * Get all mob keys
     * @return List of mob keys
     */
    public List<String> getMobKeys() {
        return new ArrayList<>(mobTypes.keySet());
    }

    /**
     * Get all boss mob keys (mobs with boss: true in config)
     * @return List of boss mob keys
     */
    public List<String> getBossMobKeys() {
        List<String> bossKeys = new ArrayList<>();
        for (Map.Entry<String, MobData> entry : mobTypes.entrySet()) {
            if (entry.getValue().isBoss()) {
                bossKeys.add(entry.getKey());
            }
        }
        return bossKeys;
    }

    /**
     * Get all non-boss mob keys (normal mobs)
     * @return List of non-boss mob keys
     */
    public List<String> getNormalMobKeys() {
        List<String> normalKeys = new ArrayList<>();
        for (Map.Entry<String, MobData> entry : mobTypes.entrySet()) {
            if (!entry.getValue().isBoss()) {
                normalKeys.add(entry.getKey());
            }
        }
        return normalKeys;
    }

    /**
     * Inner class to store custom mob data
     */
    public static class MobData {
        private final String key;
        private final String name;
        private final EntityType entityType;

        // 基礎屬性 (向後兼容)
        private final double health;
        private final double damage;

        // 等級系統
        private final int minLevel;
        private final int maxLevel;
        private final double baseHealth;
        private final double baseDamage;
        private final double healthPerLevel;
        private final double damagePerLevel;

        // 經驗值
        private final int exp;
        private final int baseExp;
        private final int expPerLevel;

        // 裝備
        private final Map<String, ItemStack> equipment;

        // 掉落物
        private final List<DropItem> vanillaDrops;
        private final List<WeaponDrop> weaponDrops;
        private final List<EquipmentDrop> equipmentDrops;

        // 偽裝
        private final DisguiseConfig disguise;

        // 其他
        private final String specialBehavior;
        private final boolean showLevelInName;
        private final List<String> tags; // 生態域標籤 (如 "ice", "fire", "forest")
        private final boolean isBoss; // 是否為 Boss 怪物（只會在 Boss 生成機制中被選擇）
        private final String spawnTime; // 生成時段: "all"(全天), "night"(夜晚), "day"(白天)

        // 向後兼容的構造函數 (舊格式)
        public MobData(String key, String name, EntityType entityType, double health, double damage, String specialBehavior) {
            this(key, name, entityType, health, damage, specialBehavior, 0);
        }

        public MobData(String key, String name, EntityType entityType, double health, double damage, String specialBehavior, int exp) {
            this.key = key;
            this.name = name;
            this.entityType = entityType;
            this.health = health;
            this.damage = damage;
            this.baseHealth = health;
            this.baseDamage = damage;
            this.specialBehavior = specialBehavior;
            this.exp = exp;

            // 預設值（無等級系統）
            this.minLevel = 1;
            this.maxLevel = 1;
            this.healthPerLevel = 0;
            this.damagePerLevel = 0;
            this.baseExp = exp;
            this.expPerLevel = 0;
            this.equipment = new HashMap<>();
            this.vanillaDrops = new ArrayList<>();
            this.weaponDrops = new ArrayList<>();
            this.equipmentDrops = new ArrayList<>();
            this.disguise = null;
            this.showLevelInName = false;
            this.tags = new ArrayList<>();
            this.isBoss = false;
            this.spawnTime = "all";
        }

        // 新格式的完整構造函數
        public MobData(String key, String name, EntityType entityType,
                       int minLevel, int maxLevel,
                       double baseHealth, double baseDamage,
                       double healthPerLevel, double damagePerLevel,
                       int baseExp, int expPerLevel,
                       Map<String, ItemStack> equipment,
                       List<DropItem> vanillaDrops, List<WeaponDrop> weaponDrops,
                       List<EquipmentDrop> equipmentDrops,
                       DisguiseConfig disguise,
                       String specialBehavior, boolean showLevelInName,
                       List<String> tags, boolean isBoss, String spawnTime) {
            this.key = key;
            this.name = name;
            this.entityType = entityType;
            this.minLevel = minLevel;
            this.maxLevel = maxLevel;
            this.baseHealth = baseHealth;
            this.baseDamage = baseDamage;
            this.healthPerLevel = healthPerLevel;
            this.damagePerLevel = damagePerLevel;
            this.baseExp = baseExp;
            this.expPerLevel = expPerLevel;
            this.equipment = equipment;
            this.vanillaDrops = vanillaDrops;
            this.weaponDrops = weaponDrops;
            this.equipmentDrops = equipmentDrops != null ? equipmentDrops : new ArrayList<>();
            this.disguise = disguise;
            this.specialBehavior = specialBehavior;
            this.showLevelInName = showLevelInName;
            this.tags = tags != null ? tags : new ArrayList<>();
            this.isBoss = isBoss;
            this.spawnTime = spawnTime != null ? spawnTime : "all";

            // 計算舊格式的值（向後兼容）
            this.health = baseHealth;
            this.damage = baseDamage;
            this.exp = baseExp;
        }

        // Getters
        public String getKey() { return key; }
        public String getName() { return name; }
        public EntityType getEntityType() { return entityType; }
        public double getHealth() { return health; }
        public double getDamage() { return damage; }
        public int getExp() { return exp; }
        public String getSpecialBehavior() { return specialBehavior; }

        // 新 Getters
        public int getMinLevel() { return minLevel; }
        public int getMaxLevel() { return maxLevel; }
        public double getBaseHealth() { return baseHealth; }
        public double getBaseDamage() { return baseDamage; }
        public double getHealthPerLevel() { return healthPerLevel; }
        public double getDamagePerLevel() { return damagePerLevel; }
        public int getBaseExp() { return baseExp; }
        public int getExpPerLevel() { return expPerLevel; }
        public Map<String, ItemStack> getEquipment() { return equipment; }
        public List<DropItem> getVanillaDrops() { return vanillaDrops; }
        public List<WeaponDrop> getWeaponDrops() { return weaponDrops; }
        public List<EquipmentDrop> getEquipmentDrops() { return equipmentDrops; }
        public DisguiseConfig getDisguise() { return disguise; }
        public boolean shouldShowLevelInName() { return showLevelInName; }
        public List<String> getTags() { return tags; }
        public boolean isBoss() { return isBoss; }
        public String getSpawnTime() { return spawnTime; }

        // 計算等級化屬性
        public double calculateHealth(int level) {
            return baseHealth + (level - 1) * healthPerLevel;
        }

        public double calculateDamage(int level) {
            return baseDamage + (level - 1) * damagePerLevel;
        }

        public int calculateExp(int level) {
            return baseExp + level * expPerLevel;
        }

        public boolean hasLevelSystem() {
            return maxLevel > 1 || healthPerLevel > 0 || damagePerLevel > 0;
        }
    }

    /**
     * 掉落物品配置
     */
    public static class DropItem {
        private final Material material;
        private final int minAmount;
        private final int maxAmount;
        private final double chance;

        public DropItem(Material material, int minAmount, int maxAmount, double chance) {
            this.material = material;
            this.minAmount = minAmount;
            this.maxAmount = maxAmount;
            this.chance = chance;
        }

        public Material getMaterial() { return material; }
        public int getMinAmount() { return minAmount; }
        public int getMaxAmount() { return maxAmount; }
        public double getChance() { return chance; }
    }

    /**
     * 自定義武器掉落配置
     */
    public static class WeaponDrop {
        private final String weaponKey;
        private final double chance;

        public WeaponDrop(String weaponKey, double chance) {
            this.weaponKey = weaponKey;
            this.chance = chance;
        }

        public String getWeaponKey() { return weaponKey; }
        public double getChance() { return chance; }
    }

    /**
     * 自定義裝備/飾品/裝甲掉落配置
     * type: "accessory" / "armor"
     */
    public static class EquipmentDrop {
        private final String equipmentKey;
        private final String type; // "accessory" 或 "armor"
        private final double chance;

        public EquipmentDrop(String equipmentKey, String type, double chance) {
            this.equipmentKey = equipmentKey;
            this.type = type;
            this.chance = chance;
        }

        public String getEquipmentKey() { return equipmentKey; }
        public String getType() { return type; }
        public double getChance() { return chance; }
    }

    /**
     * 偽裝配置
     */
    public static class DisguiseConfig {
        private final boolean enabled;
        private final EntityType disguiseType;
        private final double babyChance;

        public DisguiseConfig(boolean enabled, EntityType disguiseType, double babyChance) {
            this.enabled = enabled;
            this.disguiseType = disguiseType;
            this.babyChance = babyChance;
        }

        public boolean isEnabled() { return enabled; }
        public EntityType getDisguiseType() { return disguiseType; }
        public double getBabyChance() { return babyChance; }
    }
}

package com.customrpg.managers;

import com.customrpg.CustomRPG;
import org.bukkit.Location;
import org.bukkit.Material;
import org.bukkit.World;
import org.bukkit.enchantments.Enchantment;
import org.bukkit.entity.*;
import org.bukkit.inventory.EntityEquipment;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.NamespacedKey;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.util.Vector;
import org.bukkit.util.Transformation;
import org.joml.AxisAngle4f;
import org.joml.Vector3f;

import java.util.*;

/**
 * MobManager - Manages custom mob types and spawning
 *
 * This class handles the registration and spawning of custom mobs with unique
 * properties and behaviors. Custom mobs are marked with persistent data to
 * identify them and trigger special mechanics.
 *
 * Example custom mobs:
 * - Snow Zombie: Throws snowballs
 * - Fire Skeleton: Shoots fire arrows
 * - Giant Slime: Extra large, splits on death
 */
public class MobManager {

    private final CustomRPG plugin;
    private final Map<String, MobData> mobTypes;
    private final NamespacedKey customMobKey;
    private final NamespacedKey mobLevelKey;
    private final NamespacedKey mobTierKey;
    private final ConfigManager configManager;
    private final Random random;

    /**
     * Constructor for MobManager
     * @param plugin Main plugin instance
     * @param configManager Config manager for loading mob configs
     */
    public MobManager(CustomRPG plugin, ConfigManager configManager) {
        this.plugin = plugin;
        this.configManager = configManager;
        this.mobTypes = new HashMap<>();
        this.customMobKey = new NamespacedKey(plugin, "custom_mob_type");
        this.mobLevelKey = new NamespacedKey(plugin, "mob_level");
        this.mobTierKey = new NamespacedKey(plugin, "mob_tier");
        this.random = new Random();
        loadMobTypes();
    }

    /**
     * Load all custom mob types from config/mobs/types/ folder
     */
    private void loadMobTypes() {
        Map<String, Map<String, Object>> allMobs = configManager.getAllMobs();

        if (allMobs.isEmpty()) {
            plugin.getLogger().warning("No mobs found in config/mobs/types/ folder");
            return;
        }

        for (Map.Entry<String, Map<String, Object>> entry : allMobs.entrySet()) {
            String mobKey = entry.getKey();
            Map<String, Object> mobConfig = entry.getValue();

            try {
                MobData mobData = parseMobData(mobKey, mobConfig);
                mobTypes.put(mobKey, mobData);
                plugin.getLogger().info("Loaded custom mob: " + mobData.getName() +
                    (mobData.hasLevelSystem() ? " (Lv." + mobData.getMinLevel() + "-" + mobData.getMaxLevel() + ")" : ""));
            } catch (Exception e) {
                plugin.getLogger().warning("Failed to load mob '" + mobKey + "': " + e.getMessage());
                e.printStackTrace();
            }
        }
    }

    /**
     * Parse mob data from config (supports both old and new formats)
     */
    private MobData parseMobData(String key, Map<String, Object> config) {
        String name = (String) config.getOrDefault("name", key);
        EntityType entityType = EntityType.valueOf((String) config.get("type"));
        String specialBehavior = (String) config.getOrDefault("special-behavior", "none");

        // 檢查是否為新格式（包含 level-range 或 base-stats）
        boolean isNewFormat = config.containsKey("level-range") || config.containsKey("base-stats");

        if (isNewFormat) {
            return parseEnhancedMobData(key, name, entityType, specialBehavior, config);
        } else {
            // 舊格式（向後兼容）
            double health = getDouble(config, "health", 20.0);
            double damage = getDouble(config, "damage", 1.0);
            int exp = getInt(config, "exp", 0);
            return new MobData(key, name, entityType, health, damage, specialBehavior, exp);
        }
    }

    /**
     * Parse enhanced mob data (new format)
     */
    @SuppressWarnings("unchecked")
    private MobData parseEnhancedMobData(String key, String name, EntityType entityType,
                                          String specialBehavior, Map<String, Object> config) {
        // 等級範圍
        int minLevel = 1;
        int maxLevel = 1;
        if (config.containsKey("level-range")) {
            Map<String, Object> levelRange = (Map<String, Object>) config.get("level-range");
            minLevel = getInt(levelRange, "min", 1);
            maxLevel = getInt(levelRange, "max", 1);
        }

        // 基礎屬性
        double baseHealth = 20.0;
        double baseDamage = 1.0;
        if (config.containsKey("base-stats")) {
            Map<String, Object> baseStats = (Map<String, Object>) config.get("base-stats");
            baseHealth = getDouble(baseStats, "health", 20.0);
            baseDamage = getDouble(baseStats, "damage", 1.0);
        }

        // 屬性成長
        double healthPerLevel = 0;
        double damagePerLevel = 0;
        if (config.containsKey("stat-scaling")) {
            Map<String, Object> scaling = (Map<String, Object>) config.get("stat-scaling");
            healthPerLevel = getDouble(scaling, "health-per-level", 0);
            damagePerLevel = getDouble(scaling, "damage-per-level", 0);
        }

        // 經驗值
        int baseExp = 0;
        int expPerLevel = 0;
        if (config.containsKey("exp")) {
            Object expObj = config.get("exp");
            if (expObj instanceof Map) {
                // 新格式：exp 是一個 Map
                Map<String, Object> expConfig = (Map<String, Object>) expObj;
                baseExp = getInt(expConfig, "base", 0);
                expPerLevel = getInt(expConfig, "per-level", 0);
            } else {
                // 舊格式或簡化格式：exp 是一個整數
                baseExp = getInt(config, "exp", 0);
                expPerLevel = 0;
            }
        }

        // 裝備
        Map<String, ItemStack> equipment = parseEquipment(config);

        // 掉落物
        List<DropItem> vanillaDrops = new ArrayList<>();
        List<WeaponDrop> weaponDrops = new ArrayList<>();
        List<EquipmentDrop> equipmentDrops = new ArrayList<>();
        if (config.containsKey("drops")) {
            Map<String, Object> drops = (Map<String, Object>) config.get("drops");
            vanillaDrops = parseVanillaDrops(drops);
            weaponDrops = parseWeaponDrops(drops);
            equipmentDrops = parseEquipmentDrops(drops);
        }

        // 偽裝
        DisguiseConfig disguise = parseDisguise(config);

        // 其他設定
        boolean showLevelInName = (boolean) config.getOrDefault("show-level-in-name", false);

        // 生態域標籤
        List<String> tags = new ArrayList<>();
        Object tagsObj = config.get("tags");
        if (tagsObj instanceof List) {
            for (Object t : (List<?>) tagsObj) {
                if (t != null) tags.add(t.toString().toLowerCase());
            }
        }

        // 是否為 Boss 怪物
        boolean isBoss = Boolean.TRUE.equals(config.get("boss"));

        // 生成時段 (all / night / day)
        String spawnTime = config.getOrDefault("spawn-time", "all").toString().toLowerCase();

        return new MobData(key, name, entityType, minLevel, maxLevel,
                          baseHealth, baseDamage, healthPerLevel, damagePerLevel,
                          baseExp, expPerLevel, equipment, vanillaDrops, weaponDrops,
                          equipmentDrops, disguise, specialBehavior, showLevelInName, tags, isBoss, spawnTime);
    }

    /**
     * Parse equipment from config
     */
    @SuppressWarnings("unchecked")
    private Map<String, ItemStack> parseEquipment(Map<String, Object> config) {
        Map<String, ItemStack> equipment = new HashMap<>();

        if (!config.containsKey("equipment")) {
            return equipment;
        }

        Map<String, Object> equipConfig = (Map<String, Object>) config.get("equipment");
        String[] slots = {"helmet", "chestplate", "leggings", "boots", "main-hand", "off-hand"};

        for (String slot : slots) {
            if (equipConfig.containsKey(slot)) {
                Map<String, Object> itemConfig = (Map<String, Object>) equipConfig.get(slot);
                ItemStack item = parseItemStack(itemConfig);
                if (item != null) {
                    equipment.put(slot, item);
                }
            }
        }

        return equipment;
    }

    /**
     * Parse ItemStack from config
     */
    @SuppressWarnings("unchecked")
    private ItemStack parseItemStack(Map<String, Object> config) {
        try {
            Material material = Material.valueOf((String) config.get("material"));
            ItemStack item = new ItemStack(material);

            // 附魔
            if (config.containsKey("enchantments")) {
                List<Map<String, Object>> enchants = (List<Map<String, Object>>) config.get("enchantments");
                ItemMeta meta = item.getItemMeta();
                for (Map<String, Object> enchant : enchants) {
                    String enchantName = (String) enchant.get("type");
                    int level = getInt(enchant, "level", 1);
                    Enchantment enchantment = Enchantment.getByName(enchantName);
                    if (enchantment != null && meta != null) {
                        meta.addEnchant(enchantment, level, true);
                    }
                }
                item.setItemMeta(meta);
            }

            // 玩家頭顱 (skull-owner)
            if (material == Material.PLAYER_HEAD && config.containsKey("skull-owner")) {
                String owner = (String) config.get("skull-owner");
                org.bukkit.inventory.meta.SkullMeta skullMeta = (org.bukkit.inventory.meta.SkullMeta) item.getItemMeta();
                if (skullMeta != null) {
                    skullMeta.setOwner(owner);
                    item.setItemMeta(skullMeta);
                }
            }

            // 皮革裝甲染色 (color)
            if (config.containsKey("color") && item.getItemMeta() instanceof org.bukkit.inventory.meta.LeatherArmorMeta leatherMeta) {
                String colorStr = (String) config.get("color");
                try {
                    String[] rgb = colorStr.split(",");
                    org.bukkit.Color color = org.bukkit.Color.fromRGB(
                            Integer.parseInt(rgb[0].trim()),
                            Integer.parseInt(rgb[1].trim()),
                            Integer.parseInt(rgb[2].trim()));
                    leatherMeta.setColor(color);
                    item.setItemMeta(leatherMeta);
                } catch (Exception e) {
                    plugin.getLogger().warning("Failed to parse leather color: " + colorStr);
                }
            }

            return item;
        } catch (Exception e) {
            plugin.getLogger().warning("Failed to parse item: " + e.getMessage());
            return null;
        }
    }

    /**
     * Parse vanilla drops from config
     */
    @SuppressWarnings("unchecked")
    private List<DropItem> parseVanillaDrops(Map<String, Object> drops) {
        List<DropItem> vanillaDrops = new ArrayList<>();

        if (!drops.containsKey("vanilla-items")) {
            return vanillaDrops;
        }

        List<Map<String, Object>> items = (List<Map<String, Object>>) drops.get("vanilla-items");
        for (Map<String, Object> itemConfig : items) {
            try {
                Material material = Material.valueOf((String) itemConfig.get("material"));
                String amountStr = (String) itemConfig.getOrDefault("amount", "1");
                double chance = getDouble(itemConfig, "chance", 1.0);

                int minAmount = 1;
                int maxAmount = 1;
                if (amountStr.contains("-")) {
                    String[] parts = amountStr.split("-");
                    minAmount = Integer.parseInt(parts[0]);
                    maxAmount = Integer.parseInt(parts[1]);
                } else {
                    minAmount = maxAmount = Integer.parseInt(amountStr);
                }

                vanillaDrops.add(new DropItem(material, minAmount, maxAmount, chance));
            } catch (Exception e) {
                plugin.getLogger().warning("Failed to parse drop item: " + e.getMessage());
            }
        }

        return vanillaDrops;
    }

    /**
     * Parse weapon drops from config
     */
    @SuppressWarnings("unchecked")
    private List<WeaponDrop> parseWeaponDrops(Map<String, Object> drops) {
        List<WeaponDrop> weaponDrops = new ArrayList<>();

        if (!drops.containsKey("custom-weapons")) {
            return weaponDrops;
        }

        List<Map<String, Object>> weapons = (List<Map<String, Object>>) drops.get("custom-weapons");
        for (Map<String, Object> weaponConfig : weapons) {
            String weaponKey = (String) weaponConfig.get("weapon-key");
            double chance = getDouble(weaponConfig, "chance", 0.01);
            weaponDrops.add(new WeaponDrop(weaponKey, chance));
        }

        return weaponDrops;
    }

    /**
     * Parse equipment drops (accessories & armor) from config
     */
    @SuppressWarnings("unchecked")
    private List<EquipmentDrop> parseEquipmentDrops(Map<String, Object> drops) {
        List<EquipmentDrop> equipmentDrops = new ArrayList<>();

        if (!drops.containsKey("custom-equipment")) {
            return equipmentDrops;
        }

        List<Map<String, Object>> equipList = (List<Map<String, Object>>) drops.get("custom-equipment");
        for (Map<String, Object> equipConfig : equipList) {
            String equipKey = (String) equipConfig.get("equipment-key");
            String type = (String) equipConfig.getOrDefault("type", "accessory"); // "accessory" 或 "armor"
            double chance = getDouble(equipConfig, "chance", 0.01);
            equipmentDrops.add(new EquipmentDrop(equipKey, type, chance));
        }

        return equipmentDrops;
    }

    /**
     * Parse disguise config
     */
    @SuppressWarnings("unchecked")
    private DisguiseConfig parseDisguise(Map<String, Object> config) {
        if (!config.containsKey("disguise")) {
            return null;
        }

        Map<String, Object> disguiseConfig = (Map<String, Object>) config.get("disguise");
        boolean enabled = (boolean) disguiseConfig.getOrDefault("enabled", false);

        if (!enabled) {
            return null;
        }

        EntityType disguiseType = EntityType.valueOf((String) disguiseConfig.getOrDefault("type", "PIG"));
        double babyChance = getDouble(disguiseConfig, "baby-chance", 0);

        return new DisguiseConfig(enabled, disguiseType, babyChance);
    }

    // 輔助方法
    private double getDouble(Map<String, Object> map, String key, double defaultValue) {
        Object value = map.get(key);
        if (value instanceof Number) {
            return ((Number) value).doubleValue();
        }
        return defaultValue;
    }

    private int getInt(Map<String, Object> map, String key, int defaultValue) {
        Object value = map.get(key);
        if (value instanceof Number) {
            return ((Number) value).intValue();
        }
        return defaultValue;
    }

    /**
     * Spawn a custom mob at the specified location
     * @param mobKey The mob type identifier
     * @param location The spawn location
     * @return The spawned entity, or null if mob type not found
     */
    public LivingEntity spawnCustomMob(String mobKey, Location location) {
        MobData mobData = mobTypes.get(mobKey);
        if (mobData == null) {
            return null;
        }

        Location spawnLocation = findSafeSpawnLocation(location);
        if (spawnLocation == null) {
            plugin.getLogger().warning("Failed to find safe spawn location for custom mob '" + mobKey + "' near " + location);
            return null;
        }

        // 生成隨機等級
        int level = mobData.getMinLevel();
        if (mobData.getMaxLevel() > mobData.getMinLevel()) {
            level = random.nextInt(mobData.getMaxLevel() - mobData.getMinLevel() + 1) + mobData.getMinLevel();
        }

        // 檢查是否需要偽裝
        LivingEntity mob;
        if (mobData.getDisguise() != null && mobData.getDisguise().isEnabled()) {
            mob = spawnDisguisedMob(mobData, spawnLocation, level);
        } else {
            mob = spawnNormalMob(mobData, spawnLocation, level);
        }

        if (mob == null) {
            return null;
        }

        // 設置持久化數據
        mob.getPersistentDataContainer().set(customMobKey, PersistentDataType.STRING, mobKey);
        mob.getPersistentDataContainer().set(mobLevelKey, PersistentDataType.INTEGER, level);

        plugin.getLogger().info("Spawned custom mob: " + mobData.getName() + " (Lv." + level + ") at " + spawnLocation);
        return mob;
    }

    /**
     * Spawn a custom mob at a specified location with a specified level
     * @param mobKey The mob type identifier
     * @param location The spawn location
     * @param level The desired level for the mob
     * @return The spawned entity, or null if mob type not found
     */
    public LivingEntity spawnCustomMobWithLevel(String mobKey, Location location, int level) {
        MobData mobData = mobTypes.get(mobKey);
        if (mobData == null) {
            return null;
        }

        Location spawnLocation = findSafeSpawnLocation(location);
        if (spawnLocation == null) {
            plugin.getLogger().warning("Failed to find safe spawn location for custom mob '" + mobKey + "' near " + location);
            return null;
        }

        // Clamp level to at least 1
        level = Math.max(1, level);

        // 檢查是否需要偽裝
        LivingEntity mob;
        if (mobData.getDisguise() != null && mobData.getDisguise().isEnabled()) {
            mob = spawnDisguisedMob(mobData, spawnLocation, level);
        } else {
            mob = spawnNormalMob(mobData, spawnLocation, level);
        }

        if (mob == null) {
            return null;
        }

        // 設置持久化數據
        mob.getPersistentDataContainer().set(customMobKey, PersistentDataType.STRING, mobKey);
        mob.getPersistentDataContainer().set(mobLevelKey, PersistentDataType.INTEGER, level);

        return mob;
    }

    private String buildMobDisplayName(MobData mobData, int level) {
        if (mobData == null) {
            return "&8[&eLv." + level + "&8] 未知怪物";
        }
        return "&8[&eLv." + level + "&8] " + mobData.getName();
    }

    /**
     * Resolve a safe spawn position near the requested location.
     * 優先保留玩家原本想生成的高度；若空間不足，再回退到該欄位最高方塊上方。
     */
    public Location findSafeSpawnLocation(Location location) {
        if (location == null) {
            return null;
        }

        World world = location.getWorld();
        if (world == null) {
            return null;
        }

        int blockX = location.getBlockX();
        int blockZ = location.getBlockZ();
        int minY = world.getMinHeight() + 1;
        int maxY = world.getMaxHeight() - 2;
        int highestY = Math.min(maxY, Math.max(minY, world.getHighestBlockYAt(blockX, blockZ) + 1));

        LinkedHashSet<Integer> candidateYs = new LinkedHashSet<>();
        candidateYs.add(Math.min(maxY, Math.max(minY, location.getBlockY())));
        candidateYs.add(Math.min(maxY, Math.max(minY, location.getBlockY() + 1)));
        candidateYs.add(highestY);

        for (int offset = 1; offset <= 4; offset++) {
            candidateYs.add(Math.min(maxY, highestY + offset));
        }

        for (int y : candidateYs) {
            Location candidate = new Location(world, blockX + 0.5, y, blockZ + 0.5, location.getYaw(), location.getPitch());
            if (isSafeSpawnLocation(candidate)) {
                return candidate;
            }
        }

        return null;
    }

    private boolean isSafeSpawnLocation(Location location) {
        if (location == null || location.getWorld() == null) {
            return false;
        }

        org.bukkit.block.Block feetBlock = location.getBlock();
        org.bukkit.block.Block headBlock = feetBlock.getRelative(org.bukkit.block.BlockFace.UP);
        org.bukkit.block.Block groundBlock = feetBlock.getRelative(org.bukkit.block.BlockFace.DOWN);

        return feetBlock.getType().isAir()
                && headBlock.getType().isAir()
                && groundBlock.getType().isSolid()
                && !groundBlock.isLiquid()
                && !feetBlock.isLiquid();
    }

    /**
     * 取得自訂怪實際會生成出的原版實體類型（考慮 disguise / BlockDisplay 核心）
     */
    public EntityType getActualSpawnEntityType(String mobKey) {
        MobData mobData = mobTypes.get(mobKey);
        return mobData == null ? null : getActualSpawnEntityType(mobData);
    }

    public EntityType getActualSpawnEntityType(MobData mobData) {
        if (mobData == null) {
            return null;
        }

        DisguiseConfig disguise = mobData.getDisguise();
        if (disguise != null && disguise.isEnabled()) {
            return disguise.getDisguiseType() == EntityType.ARMOR_STAND ? EntityType.ZOMBIE : disguise.getDisguiseType();
        }

        return mobData.getEntityType();
    }

    /**
     * 判斷該自訂怪在 Peaceful 世界中是否會被原版 Minecraft 立刻移除。
     */
    public boolean willBeRemovedInPeaceful(String mobKey) {
        MobData mobData = mobTypes.get(mobKey);
        return mobData != null && willBeRemovedInPeaceful(mobData);
    }

    public boolean willBeRemovedInPeaceful(MobData mobData) {
        return isPeacefulRestricted(getActualSpawnEntityType(mobData));
    }

    private boolean isPeacefulRestricted(EntityType entityType) {
        if (entityType == null) {
            return false;
        }

        return switch (entityType) {
            case BLAZE, BOGGED, BREEZE, CAVE_SPIDER, CREEPER, DROWNED, ELDER_GUARDIAN,
                    ENDERMAN, ENDERMITE, EVOKER, GHAST, GIANT, GUARDIAN, HOGLIN, HUSK,
                    MAGMA_CUBE, PHANTOM, PIGLIN, PIGLIN_BRUTE, PILLAGER, RAVAGER,
                    SHULKER, SILVERFISH, SKELETON, SLIME, SPIDER, STRAY, VEX, VINDICATOR,
                    WARDEN, WITCH, WITHER, WITHER_SKELETON, ZOGLIN, ZOMBIE,
                    ZOMBIE_VILLAGER, ZOMBIFIED_PIGLIN -> true;
            default -> false;
        };
    }

    /**
     * Set the tier tag on a mob entity
     * @param entity The entity
     * @param tier The tier string (NORMAL, ELITE, BOSS)
     */
    public void setMobTier(LivingEntity entity, String tier) {
        entity.getPersistentDataContainer().set(mobTierKey, PersistentDataType.STRING, tier);
    }

    /**
     * Get the tier of a custom mob
     * @param entity The entity to check
     * @return Tier string ("NORMAL", "ELITE", "BOSS"), or "NORMAL" if not set
     */
    public String getMobTier(Entity entity) {
        if (!(entity instanceof LivingEntity mob)) {
            return "NORMAL";
        }
        String tier = mob.getPersistentDataContainer().get(mobTierKey, PersistentDataType.STRING);
        return tier != null ? tier : "NORMAL";
    }

    /**
     * Get all registered mob types
     * @return Collection of MobData
     */
    public java.util.Collection<MobData> getMobTypes() {
        return mobTypes.values();
    }

    /**
     * Get the custom mob NamespacedKey (for external checks)
     */
    public NamespacedKey getCustomMobNamespacedKey() {
        return customMobKey;
    }

    /**
     * Spawn a normal (non-disguised) mob
     */
    private LivingEntity spawnNormalMob(MobData mobData, Location location, int level) {
        Entity entity = location.getWorld().spawnEntity(location, mobData.getEntityType());
        if (!(entity instanceof LivingEntity)) {
            entity.remove();
            return null;
        }

        LivingEntity mob = (LivingEntity) entity;

        // 設置名稱
        String displayName = buildMobDisplayName(mobData, level);
        mob.setCustomName(org.bukkit.ChatColor.translateAlternateColorCodes('&', displayName));
        mob.setCustomNameVisible(true);

        // 設置等級化屬性
        double health = mobData.calculateHealth(level);
        mob.setMaxHealth(health);
        mob.setHealth(health);

        // 裝備物品
        applyEquipment(mob, mobData);
        applySpawnPersistence(mob);

        return mob;
    }

    /**
     * Spawn a disguised mob (directly spawn as disguise type with custom behavior)
     * 直接生成偽裝類型的生物，根據類型決定實現方式
     */
    private LivingEntity spawnDisguisedMob(MobData mobData, Location location, int level) {
        DisguiseConfig disguise = mobData.getDisguise();

        // 特殊處理：盔甲架偽裝（用於創建純視覺效果，如行走的仙人掌方塊）
        if (disguise.getDisguiseType() == EntityType.ARMOR_STAND) {
            return spawnArmorStandDisguise(mobData, location, level);
        }

        // 特殊處理：檢查是否配置了方塊材質的 helmet（用於創建行走的方塊）
        // 當裝備中的 helmet 是方塊類型時，使用 BlockDisplay 方式顯示
        if (mobData.getEquipment().containsKey("helmet")) {
            ItemStack helmetItem = mobData.getEquipment().get("helmet");
            Material helmetMaterial = helmetItem.getType();

            // 檢查是否為適合當 BlockDisplay 的方塊材料
            // (isBlock() 足夠判斷，不需要排除 isItem()，因為很多方塊同時也是物品)
            if (helmetMaterial.isBlock() && isBlockDisplayCandidate(helmetMaterial)) {
                plugin.getLogger().info("檢測到方塊材質頭盔: " + helmetMaterial.name() + "，使用 BlockDisplay 模式");
                return spawnArmorStandDisguise(mobData, location, level);
            }
        }

        // 一般偽裝：直接生成偽裝實體（例如：豬）
        Entity disguiseEntity = location.getWorld().spawnEntity(location, disguise.getDisguiseType());
        if (!(disguiseEntity instanceof LivingEntity)) {
            disguiseEntity.remove();
            return null;
        }

        LivingEntity mob = (LivingEntity) disguiseEntity;

        // 設置名稱
        String displayName = buildMobDisplayName(mobData, level);
        mob.setCustomName(org.bukkit.ChatColor.translateAlternateColorCodes('&', displayName));
        mob.setCustomNameVisible(true);

        // 設置等級化屬性
        double health = mobData.calculateHealth(level);
        mob.setMaxHealth(health);
        mob.setHealth(health);

        // 隨機幼年
        if (disguise.getBabyChance() > 0 && random.nextDouble() < disguise.getBabyChance()) {
            if (mob instanceof org.bukkit.entity.Ageable) {
                ((org.bukkit.entity.Ageable) mob).setBaby();
            }
        }

        // 裝備物品
        applyEquipment(mob, mobData);
        applySpawnPersistence(mob);

        // 只有當生物是被動類型且設置了傷害值時，才賦予攻擊行為
        if (isPassiveMob(disguise.getDisguiseType()) && mobData.getBaseDamage() > 0) {
            applyAggressiveBehavior(mob);
        }

        return mob;
    }

    /**
     * Spawn BlockDisplay disguise - creates a walking block (like cactus)
     * 使用 BlockDisplay 生成會行走的方塊偽裝（如仙人掌）
     *
     * 架構說明：
     * 1. 隱形殭屍作為移動核心（提供 AI 和碰撞）
     * 2. BlockDisplay 作為視覺顯示（精準位置控制）
     * 3. ArmorStand 作為名稱標籤（顯示名稱和等級）
     *
     * BlockDisplay 的優勢：
     * - 不受乘客系統限制，可以精準設置位置
     * - 支援 Transformation 調整偏移、旋轉、縮放
     * - 平滑插值移動（setTeleportDuration）
     * - 可以顯示任何方塊類型
     */
    private LivingEntity spawnArmorStandDisguise(MobData mobData, Location location, int level) {
        plugin.getLogger().info("=== 開始生成 BlockDisplay 行走方塊 ===");

        // ===== 第一步：生成隱形殭屍核心 =====
        Entity coreEntity = location.getWorld().spawnEntity(location, EntityType.ZOMBIE);
        if (!(coreEntity instanceof Zombie core)) {
            coreEntity.remove();
            plugin.getLogger().severe("✗ 無法生成殭屍核心");
            return null;
        }

        // 設置殭屍屬性（隱形、靜音、保持 AI）
        core.setAdult();
        core.setInvisible(true);
        core.setSilent(true);
        core.setAI(true);
        core.setRemoveWhenFarAway(false);
        core.setCanPickupItems(false);
        core.setShouldBurnInDay(false); // 殭屍不會在白天燃燒

        // 清空裝備、掉落率歸零（不戴任何東西，避免看到裝備）
        if (core.getEquipment() != null) {
            core.getEquipment().clear();
            core.getEquipment().setHelmetDropChance(0f);
            core.getEquipment().setChestplateDropChance(0f);
            core.getEquipment().setLeggingsDropChance(0f);
            core.getEquipment().setBootsDropChance(0f);
            core.getEquipment().setItemInMainHandDropChance(0f);
            core.getEquipment().setItemInOffHandDropChance(0f);
        }

        // 設置生命值和傷害（等級化）
        double health = mobData.calculateHealth(level);
        core.getAttribute(org.bukkit.attribute.Attribute.MAX_HEALTH).setBaseValue(health);
        core.setHealth(health);

        // 設置攻擊力（等級化）
        double damage = mobData.calculateDamage(level);
        core.getAttribute(org.bukkit.attribute.Attribute.ATTACK_DAMAGE).setBaseValue(damage);

        plugin.getLogger().info("✓ 殭屍核心已生成 (隱形, Lv." + level + ", HP:" + health + ", ATK:" + damage + ")");

        // **重要：標記殭屍核心為自定義怪物**
        // 這樣 MobListener 才能識別並正確處理傷害、掉落物、經驗值
        core.getPersistentDataContainer().set(customMobKey, PersistentDataType.STRING, mobData.getKey());
        core.getPersistentDataContainer().set(mobLevelKey, PersistentDataType.INTEGER, level);
        plugin.getLogger().info("✓ 殭屍核心已標記為自定義怪物: " + mobData.getKey() + " (Lv." + level + ")");

        // ===== 第二步：獲取方塊類型 =====
        Material blockMaterial = Material.CACTUS;
        if (mobData.getEquipment().containsKey("helmet")) {
            ItemStack helmetItem = mobData.getEquipment().get("helmet");
            blockMaterial = helmetItem.getType();
        }
        plugin.getLogger().info("✓ 方塊材質: " + blockMaterial.name());

        // ===== 第三步：生成 BlockDisplay =====
        Location displayLocation = location.clone();
        BlockDisplay blockDisplay = (BlockDisplay) location.getWorld().spawnEntity(
            displayLocation,
            EntityType.BLOCK_DISPLAY
        );

        // 設置方塊數據
        blockDisplay.setBlock(blockMaterial.createBlockData());

        // 設置 Transformation（精準位置控制的關鍵）
        // BlockDisplay 從座標角落開始渲染 (1x1x1 方塊)
        // 殭屍碰撞箱中心在 spawn 點，寬 0.6
        // 所以 X/Z 各偏移 -0.5 讓方塊中心對齊殭屍中心
        // Y=0 讓方塊底部對齊殭屍腳底（地面）
        Vector3f translation = new Vector3f(-0.5f, 0f, -0.5f);
        AxisAngle4f leftRotation = new AxisAngle4f(0, 0, 1, 0); // 無旋轉
        Vector3f scale = new Vector3f(1.0f, 1.0f, 1.0f); // 原始大小
        AxisAngle4f rightRotation = new AxisAngle4f(0, 0, 1, 0); // 無旋轉

        Transformation transformation = new Transformation(translation, leftRotation, scale, rightRotation);
        blockDisplay.setTransformation(transformation);

        // 設置顯示屬性
        blockDisplay.setTeleportDuration(2); // 平滑傳送（2 ticks = 0.1秒）
        blockDisplay.setInterpolationDuration(2); // 插值時間
        blockDisplay.setInterpolationDelay(0); // 立即開始插值
        blockDisplay.setViewRange(128.0f); // 可視範圍 128 格
        blockDisplay.setBrightness(new org.bukkit.entity.Display.Brightness(15, 15)); // 最大亮度（不受環境影響）
        blockDisplay.setShadowRadius(0.5f); // 陰影半徑
        blockDisplay.setShadowStrength(1.0f); // 陰影強度

        // 標記為偽裝實體（用於清理和識別）
        blockDisplay.getPersistentDataContainer().set(
            new NamespacedKey(plugin, "disguise_blockdisplay"),
            PersistentDataType.STRING,
            core.getUniqueId().toString()
        );

        plugin.getLogger().info("✓ BlockDisplay 已生成（平滑移動: 2 ticks）");

        // ===== 第四步：生成名稱標籤 ArmorStand =====
        Location nameLocation = location.clone().add(0, 1.3, 0); // 方塊頂部上方
        ArmorStand nameTag = (ArmorStand) location.getWorld().spawnEntity(
            nameLocation,
            EntityType.ARMOR_STAND
        );

        // 設置為隱形 marker（不占空間、不碰撞、不受重力）
        nameTag.setVisible(false);
        nameTag.setGravity(false);
        nameTag.setInvulnerable(true);
        nameTag.setMarker(true);
        nameTag.setSmall(true);
        nameTag.setBasePlate(false);
        nameTag.setArms(false);

        // 設置名稱
        String displayName = buildMobDisplayName(mobData, level);
        nameTag.customName(net.kyori.adventure.text.Component.text(
            org.bukkit.ChatColor.translateAlternateColorCodes('&', displayName)
        ));
        nameTag.setCustomNameVisible(true);

        // 標記為偽裝名稱標籤
        nameTag.getPersistentDataContainer().set(
            new NamespacedKey(plugin, "disguise_nametag"),
            PersistentDataType.STRING,
            core.getUniqueId().toString()
        );

        plugin.getLogger().info("✓ 名稱標籤已生成: " + displayName);

        // ===== 第五步：建立位置同步系統 =====
        // 使用高頻率更新（每 tick）確保 BlockDisplay 跟隨殭屍移動
        // 這是精準控制位置的關鍵
        new BukkitRunnable() {
            private Location lastCoreLoc = null;
            private int tickCounter = 0;

            @Override
            public void run() {
                // 檢查核心是否還存在
                if (core.isDead() || !core.isValid()) {
                    // 清理所有關聯實體
                    if (blockDisplay.isValid()) blockDisplay.remove();
                    if (nameTag.isValid()) nameTag.remove();
                    this.cancel();
                    plugin.getLogger().info("✗ BlockDisplay 已清理（核心死亡）");
                    return;
                }

                // 獲取殭屍當前位置
                Location coreLoc = core.getLocation();
                tickCounter++;

                // 同步 BlockDisplay 位置
                if (blockDisplay.isValid()) {
                    // 檢查位置是否改變（優化性能）
                    boolean moved = lastCoreLoc == null ||
                                  lastCoreLoc.getX() != coreLoc.getX() ||
                                  lastCoreLoc.getY() != coreLoc.getY() ||
                                  lastCoreLoc.getZ() != coreLoc.getZ();

                    if (moved) {
                        // 精準設置 BlockDisplay 位置
                        // BlockDisplay 的 transformation 已經處理了 Y 軸偏移
                        Location blockLoc = coreLoc.clone();
                        blockLoc.setYaw(0); // BlockDisplay 不需要旋轉（方塊是立方體）
                        blockLoc.setPitch(0);
                        blockDisplay.teleport(blockLoc);

                        lastCoreLoc = coreLoc.clone();
                    }
                } else {
                    // BlockDisplay 消失，清理所有
                    if (nameTag.isValid()) nameTag.remove();
                    core.remove();
                    this.cancel();
                    return;
                }

                // 同步名稱標籤位置（在方塊上方）
                if (nameTag.isValid()) {
                    Location nameLoc = coreLoc.clone().add(0, 1.3, 0);
                    nameLoc.setYaw(0);
                    nameLoc.setPitch(0);
                    nameTag.teleport(nameLoc);
                } else {
                    // 名稱標籤消失，清理所有
                    if (blockDisplay.isValid()) blockDisplay.remove();
                    core.remove();
                    this.cancel();
                    return;
                }

                // 每 100 ticks（5秒）輸出一次調試信息
                if (tickCounter % 100 == 0) {
                    plugin.getLogger().fine("BlockDisplay 同步中 (tick " + tickCounter + ")");
                }
            }
        }.runTaskTimer(plugin, 0L, 1L); // 每 tick 更新（20 次/秒）

        plugin.getLogger().info("=== BlockDisplay 行走方塊生成完成 ===");
        plugin.getLogger().info("  實體 UUID: " + core.getUniqueId());
        plugin.getLogger().info("  方塊類型: " + blockMaterial.name());
        plugin.getLogger().info("  顯示名稱: " + displayName);
        plugin.getLogger().info("  等級: " + level + " | HP: " + health + " | ATK: " + damage);

        return core;
    }

    /**
     * Check if an entity type is a passive mob
     * 檢查生物類型是否為被動生物
     */
    private boolean isPassiveMob(EntityType type) {
        switch (type) {
            // 被動生物
            case PIG:
            case COW:
            case SHEEP:
            case CHICKEN:
            case RABBIT:
            case HORSE:
            case DONKEY:
            case MULE:
            case LLAMA:
            case PARROT:
            case BAT:
            case OCELOT:
            case CAT:
            case PANDA:
            case FOX:
            case VILLAGER:
            case WANDERING_TRADER:
            case IRON_GOLEM:
            case SNOW_GOLEM:
            case TURTLE:
            case MOOSHROOM:
            case SQUID:
            case GLOW_SQUID:
            case COD:
            case SALMON:
            case TROPICAL_FISH:
            case PUFFERFISH:
            case DOLPHIN:
            case AXOLOTL:
            case STRIDER:
                return true;
            default:
                return false;
        }
    }

    /**
     * 判斷材料是否適合做 BlockDisplay 偽裝
     * (非穿戴型方塊，如仙人掌、TNT、南瓜等)
     */
    private boolean isBlockDisplayCandidate(Material mat) {
        // 非方塊材料一律不行
        if (!mat.isBlock()) return false;

        // 排除正常盔甲 / 頭顱（這些應該直接穿戴）
        String name = mat.name();
        if (name.contains("HELMET") || name.contains("CHESTPLATE")
                || name.contains("LEGGINGS") || name.contains("BOOTS")
                || name.contains("_HEAD") || name.contains("_SKULL")) {
            return false;
        }

        // 其餘方塊都視為 BlockDisplay 候選
        return true;
    }

    /**
     * Apply aggressive behavior to passive mobs
     * 讓被動生物（如豬、雞等）能夠攻擊玩家
     */
    private void applyAggressiveBehavior(LivingEntity mob) {
        try {
            // 使用 Bukkit API 讓生物主動尋找附近的玩家並攻擊
            // 透過定期任務模擬攻擊行為
            new BukkitRunnable() {
                @Override
                public void run() {
                    if (mob.isDead() || !mob.isValid()) {
                        this.cancel();
                        return;
                    }

                    // 檢查附近是否有玩家
                    Player target = findNearestPlayer(mob, 16.0);
                    if (target != null && target.getGameMode() != org.bukkit.GameMode.CREATIVE &&
                        target.getGameMode() != org.bukkit.GameMode.SPECTATOR) {

                        // 設置生物的目標為玩家
                        if (mob instanceof Mob) {
                            ((Mob) mob).setTarget(target);
                        }

                        // 讓生物朝玩家移動
                        Location targetLoc = target.getLocation();
                        Location mobLoc = mob.getLocation();

                        double distance = mobLoc.distance(targetLoc);

                        // 計算朝向玩家的角度
                        Vector direction = targetLoc.toVector().subtract(mobLoc.toVector());
                        double yaw = Math.toDegrees(Math.atan2(-direction.getX(), direction.getZ()));
                        double pitch = Math.toDegrees(Math.atan2(-direction.getY(),
                            Math.sqrt(direction.getX() * direction.getX() + direction.getZ() * direction.getZ())));

                        // 設置生物朝向玩家
                        Location newLoc = mobLoc.clone();
                        newLoc.setYaw((float) yaw);
                        newLoc.setPitch((float) pitch);
                        mob.teleport(newLoc);

                        // 如果在攻擊範圍內（2格內），則進行攻擊
                        if (distance <= 2.0) {
                            // 透過 EntityDamageByEntityEvent 處理傷害
                            // 這裡只需要標記，實際傷害由事件處理
                            target.damage(0.1, mob); // 極小傷害，實際傷害在事件中設置
                        } else if (distance <= 16.0) {
                            // 計算移動方向（水平）
                            direction.normalize();
                            direction.setY(0); // 保持在水平面移動

                            // 設置速度（追逐玩家）
                            Vector velocity = direction.multiply(0.3);
                            velocity.setY(mob.getVelocity().getY()); // 保持原有的Y軸速度（重力）
                            mob.setVelocity(velocity);
                        }
                    }
                }
            }.runTaskTimer(plugin, 0L, 10L); // 每 0.5 秒執行一次

        } catch (Exception e) {
            plugin.getLogger().warning("Failed to apply aggressive behavior: " + e.getMessage());
        }
    }

    /**
     * Find the nearest player to a mob within range
     */
    private Player findNearestPlayer(LivingEntity mob, double range) {
        Player nearest = null;
        double nearestDistance = range * range; // 使用平方距離避免開方運算

        for (Player player : mob.getWorld().getPlayers()) {
            if (player.getGameMode() == org.bukkit.GameMode.CREATIVE ||
                player.getGameMode() == org.bukkit.GameMode.SPECTATOR) {
                continue;
            }

            double distanceSquared = player.getLocation().distanceSquared(mob.getLocation());
            if (distanceSquared < nearestDistance) {
                nearest = player;
                nearestDistance = distanceSquared;
            }
        }

        return nearest;
    }

    /**
     * Apply equipment to a mob
     */
    private void applyEquipment(LivingEntity mob, MobData mobData) {
        EntityEquipment equipment = mob.getEquipment();
        if (equipment == null) {
            return;
        }

        Map<String, ItemStack> equipmentMap = mobData.getEquipment();

        if (equipmentMap.containsKey("helmet")) {
            equipment.setHelmet(equipmentMap.get("helmet"));
            equipment.setHelmetDropChance(0.0f);
        }
        if (equipmentMap.containsKey("chestplate")) {
            equipment.setChestplate(equipmentMap.get("chestplate"));
            equipment.setChestplateDropChance(0.0f);
        }
        if (equipmentMap.containsKey("leggings")) {
            equipment.setLeggings(equipmentMap.get("leggings"));
            equipment.setLeggingsDropChance(0.0f);
        }
        if (equipmentMap.containsKey("boots")) {
            equipment.setBoots(equipmentMap.get("boots"));
            equipment.setBootsDropChance(0.0f);
        }
        if (equipmentMap.containsKey("main-hand")) {
            equipment.setItemInMainHand(equipmentMap.get("main-hand"));
            equipment.setItemInMainHandDropChance(0.0f);
        }
        if (equipmentMap.containsKey("off-hand")) {
            equipment.setItemInOffHand(equipmentMap.get("off-hand"));
            equipment.setItemInOffHandDropChance(0.0f);
        }
    }

    private void applySpawnPersistence(LivingEntity mob) {
        if (mob instanceof Mob spawnedMob) {
            spawnedMob.setRemoveWhenFarAway(false);
            spawnedMob.setCanPickupItems(false);
        }
    }

    /**
     * Check if an entity is a custom mob
     * @param entity The entity to check
     * @return Mob key if it's a custom mob, null otherwise
     */
    public String getCustomMobKey(Entity entity) {
        if (!(entity instanceof LivingEntity)) {
            return null;
        }

        LivingEntity mob = (LivingEntity) entity;
        return mob.getPersistentDataContainer().get(customMobKey, PersistentDataType.STRING);
    }

    /**
     * Get the level of a custom mob
     * @param entity The entity to check
     * @return Mob level, or 1 if not found
     */
    public int getMobLevel(Entity entity) {
        if (!(entity instanceof LivingEntity)) {
            return 1;
        }

        LivingEntity mob = (LivingEntity) entity;
        Integer level = mob.getPersistentDataContainer().get(mobLevelKey, PersistentDataType.INTEGER);
        return level != null ? level : 1;
    }

    /**
     * Get mob data by key
     * @param mobKey The mob identifier
     * @return MobData or null if not found
     */
    public MobData getMobData(String mobKey) {
        return mobTypes.get(mobKey);
    }

    /**
     * Get the number of registered custom mob types
     * @return Number of custom mob types
     */
    public int getMobTypeCount() {
        return mobTypes.size();
    }

    /**
     * Get all mob keys
     * @return List of mob keys
     */
    public List<String> getMobKeys() {
        return new ArrayList<>(mobTypes.keySet());
    }

    /**
     * Get all boss mob keys (mobs with boss: true in config)
     * @return List of boss mob keys
     */
    public List<String> getBossMobKeys() {
        List<String> bossKeys = new ArrayList<>();
        for (Map.Entry<String, MobData> entry : mobTypes.entrySet()) {
            if (entry.getValue().isBoss()) {
                bossKeys.add(entry.getKey());
            }
        }
        return bossKeys;
    }

    /**
     * Get all non-boss mob keys (normal mobs)
     * @return List of non-boss mob keys
     */
    public List<String> getNormalMobKeys() {
        List<String> normalKeys = new ArrayList<>();
        for (Map.Entry<String, MobData> entry : mobTypes.entrySet()) {
            if (!entry.getValue().isBoss()) {
                normalKeys.add(entry.getKey());
            }
        }
        return normalKeys;
    }

    /**
     * Inner class to store custom mob data
     */
    public static class MobData {
        private final String key;
        private final String name;
        private final EntityType entityType;

        // 基礎屬性 (向後兼容)
        private final double health;
        private final double damage;

        // 等級系統
        private final int minLevel;
        private final int maxLevel;
        private final double baseHealth;
        private final double baseDamage;
        private final double healthPerLevel;
        private final double damagePerLevel;

        // 經驗值
        private final int exp;
        private final int baseExp;
        private final int expPerLevel;

        // 裝備
        private final Map<String, ItemStack> equipment;

        // 掉落物
        private final List<DropItem> vanillaDrops;
        private final List<WeaponDrop> weaponDrops;
        private final List<EquipmentDrop> equipmentDrops;

        // 偽裝
        private final DisguiseConfig disguise;

        // 其他
        private final String specialBehavior;
        private final boolean showLevelInName;
        private final List<String> tags; // 生態域標籤 (如 "ice", "fire", "forest")
        private final boolean isBoss; // 是否為 Boss 怪物（只會在 Boss 生成機制中被選擇）
        private final String spawnTime; // 生成時段: "all"(全天), "night"(夜晚), "day"(白天)

        // 向後兼容的構造函數 (舊格式)
        public MobData(String key, String name, EntityType entityType, double health, double damage, String specialBehavior) {
            this(key, name, entityType, health, damage, specialBehavior, 0);
        }

        public MobData(String key, String name, EntityType entityType, double health, double damage, String specialBehavior, int exp) {
            this.key = key;
            this.name = name;
            this.entityType = entityType;
            this.health = health;
            this.damage = damage;
            this.baseHealth = health;
            this.baseDamage = damage;
            this.specialBehavior = specialBehavior;
            this.exp = exp;

            // 預設值（無等級系統）
            this.minLevel = 1;
            this.maxLevel = 1;
            this.healthPerLevel = 0;
            this.damagePerLevel = 0;
            this.baseExp = exp;
            this.expPerLevel = 0;
            this.equipment = new HashMap<>();
            this.vanillaDrops = new ArrayList<>();
            this.weaponDrops = new ArrayList<>();
            this.equipmentDrops = new ArrayList<>();
            this.disguise = null;
            this.showLevelInName = false;
            this.tags = new ArrayList<>();
            this.isBoss = false;
            this.spawnTime = "all";
        }

        // 新格式的完整構造函數
        public MobData(String key, String name, EntityType entityType,
                       int minLevel, int maxLevel,
                       double baseHealth, double baseDamage,
                       double healthPerLevel, double damagePerLevel,
                       int baseExp, int expPerLevel,
                       Map<String, ItemStack> equipment,
                       List<DropItem> vanillaDrops, List<WeaponDrop> weaponDrops,
                       List<EquipmentDrop> equipmentDrops,
                       DisguiseConfig disguise,
                       String specialBehavior, boolean showLevelInName,
                       List<String> tags, boolean isBoss, String spawnTime) {
            this.key = key;
            this.name = name;
            this.entityType = entityType;
            this.minLevel = minLevel;
            this.maxLevel = maxLevel;
            this.baseHealth = baseHealth;
            this.baseDamage = baseDamage;
            this.healthPerLevel = healthPerLevel;
            this.damagePerLevel = damagePerLevel;
            this.baseExp = baseExp;
            this.expPerLevel = expPerLevel;
            this.equipment = equipment;
            this.vanillaDrops = vanillaDrops;
            this.weaponDrops = weaponDrops;
            this.equipmentDrops = equipmentDrops != null ? equipmentDrops : new ArrayList<>();
            this.disguise = disguise;
            this.specialBehavior = specialBehavior;
            this.showLevelInName = showLevelInName;
            this.tags = tags != null ? tags : new ArrayList<>();
            this.isBoss = isBoss;
            this.spawnTime = spawnTime != null ? spawnTime : "all";

            // 計算舊格式的值（向後兼容）
            this.health = baseHealth;
            this.damage = baseDamage;
            this.exp = baseExp;
        }

        // Getters
        public String getKey() { return key; }
        public String getName() { return name; }
        public EntityType getEntityType() { return entityType; }
        public double getHealth() { return health; }
        public double getDamage() { return damage; }
        public int getExp() { return exp; }
        public String getSpecialBehavior() { return specialBehavior; }

        // 新 Getters
        public int getMinLevel() { return minLevel; }
        public int getMaxLevel() { return maxLevel; }
        public double getBaseHealth() { return baseHealth; }
        public double getBaseDamage() { return baseDamage; }
        public double getHealthPerLevel() { return healthPerLevel; }
        public double getDamagePerLevel() { return damagePerLevel; }
        public int getBaseExp() { return baseExp; }
        public int getExpPerLevel() { return expPerLevel; }
        public Map<String, ItemStack> getEquipment() { return equipment; }
        public List<DropItem> getVanillaDrops() { return vanillaDrops; }
        public List<WeaponDrop> getWeaponDrops() { return weaponDrops; }
        public List<EquipmentDrop> getEquipmentDrops() { return equipmentDrops; }
        public DisguiseConfig getDisguise() { return disguise; }
        public boolean shouldShowLevelInName() { return showLevelInName; }
        public List<String> getTags() { return tags; }
        public boolean isBoss() { return isBoss; }
        public String getSpawnTime() { return spawnTime; }

        // 計算等級化屬性
        public double calculateHealth(int level) {
            return baseHealth + (level - 1) * healthPerLevel;
        }

        public double calculateDamage(int level) {
            return baseDamage + (level - 1) * damagePerLevel;
        }

        public int calculateExp(int level) {
            return baseExp + level * expPerLevel;
        }

        public boolean hasLevelSystem() {
            return maxLevel > 1 || healthPerLevel > 0 || damagePerLevel > 0;
        }
    }

    /**
     * 掉落物品配置
     */
    public static class DropItem {
        private final Material material;
        private final int minAmount;
        private final int maxAmount;
        private final double chance;

        public DropItem(Material material, int minAmount, int maxAmount, double chance) {
            this.material = material;
            this.minAmount = minAmount;
            this.maxAmount = maxAmount;
            this.chance = chance;
        }

        public Material getMaterial() { return material; }
        public int getMinAmount() { return minAmount; }
        public int getMaxAmount() { return maxAmount; }
        public double getChance() { return chance; }
    }

    /**
     * 自定義武器掉落配置
     */
    public static class WeaponDrop {
        private final String weaponKey;
        private final double chance;

        public WeaponDrop(String weaponKey, double chance) {
            this.weaponKey = weaponKey;
            this.chance = chance;
        }

        public String getWeaponKey() { return weaponKey; }
        public double getChance() { return chance; }
    }

    /**
     * 自定義裝備/飾品/裝甲掉落配置
     * type: "accessory" / "armor"
     */
    public static class EquipmentDrop {
        private final String equipmentKey;
        private final String type; // "accessory" 或 "armor"
        private final double chance;

        public EquipmentDrop(String equipmentKey, String type, double chance) {
            this.equipmentKey = equipmentKey;
            this.type = type;
            this.chance = chance;
        }

        public String getEquipmentKey() { return equipmentKey; }
        public String getType() { return type; }
        public double getChance() { return chance; }
    }

    /**
     * 偽裝配置
     */
    public static class DisguiseConfig {
        private final boolean enabled;
        private final EntityType disguiseType;
        private final double babyChance;

        public DisguiseConfig(boolean enabled, EntityType disguiseType, double babyChance) {
            this.enabled = enabled;
            this.disguiseType = disguiseType;
            this.babyChance = babyChance;
        }

        public boolean isEnabled() { return enabled; }
        public EntityType getDisguiseType() { return disguiseType; }
        public double getBabyChance() { return babyChance; }
    }
}

package com.customrpg.managers;

import com.customrpg.CustomRPG;
import com.customrpg.players.PlayerStats;
import org.bukkit.*;
import org.bukkit.block.Block;
import org.bukkit.block.BlockFace;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Entity;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.scheduler.BukkitTask;

import java.io.File;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.logging.Logger;

/**
 * MobSpawnManager - 區域式動態怪物生成系統
 *
 * Zone-Based 生成：
 * - 玩家在 zone 內 → 不生成怪物
 * - 玩家在 zone 外 → 依距離計算怪物等級 (tier 系統)
 * - 保留 BOSS / ELITE / NORMAL 階級系統
 * - 保留累積機率 (pity) 系統
 */
public class MobSpawnManager {

    public enum MobTier {
        NORMAL("普通", ChatColor.WHITE),
        ELITE("精英", ChatColor.GOLD),
        BOSS("BOSS", ChatColor.RED);

        private final String displayName;
        private final ChatColor color;

        MobTier(String displayName, ChatColor color) {
            this.displayName = displayName;
            this.color = color;
        }

        public String getDisplayName() { return displayName; }
        public ChatColor getColor() { return color; }
    }

    private final CustomRPG plugin;
    private final MobManager mobManager;
    private final PlayerStatsManager statsManager;
    private final Logger log;
    private BukkitTask spawnTask;

    // Debug mode
    private boolean debug = false;

    // ===== Configuration =====
    private boolean enabled;
    private int intervalTicks;
    private int spawnsPerCycle;
    private int spawnRadiusMin;
    private int spawnRadiusMax;
    private int maxMobsPerPlayer;

    // Tier settings
    private int normalLevelOffsetMin, normalLevelOffsetMax;
    private String normalNamePrefix;

    private double eliteChance;
    private int eliteLevelOffsetMin, eliteLevelOffsetMax;
    private double eliteStatMultiplier;
    private String eliteNamePrefix;

    // Boss — 累積機率系統 (pity system)
    private double bossBaseChance;
    private double bossPityIncrement;
    private int bossCooldownSeconds;
    private int bossSpawnRadiusMin;
    private int bossSpawnRadiusMax;
    private int bossLevelOffsetMin, bossLevelOffsetMax;
    private double bossStatMultiplier;
    private String bossNamePrefix;
    private String bossSpawnParticle;
    private int bossParticleCount;
    private String bossSpawnSound;
    private float bossSoundVolume, bossSoundPitch;

    // Boss pity 運行時狀態 (per-player)
    private final Map<UUID, Double> playerPityChance = new HashMap<>();
    private final Map<UUID, Long> playerBossCooldown = new HashMap<>();

    // Conditions
    private boolean nightOnly;
    private int maxLightLevel;
    private boolean requireSolidGround;
    private boolean requireAirSpace;

    // Disabled worlds
    private Set<String> disabledWorlds;

    // Track spawned mobs
    private final Set<UUID> spawnedMobs = new HashSet<>();
    private final Random random = new Random();

    // 統計用
    private int totalSpawnAttempts = 0;
    private int totalSpawnSuccess = 0;
    private int totalLocationFails = 0;
    private String lastSkipReason = "無";

    public MobSpawnManager(CustomRPG plugin, MobManager mobManager, PlayerStatsManager statsManager) {
        this.plugin = plugin;
        this.mobManager = mobManager;
        this.statsManager = statsManager;
        this.log = plugin.getLogger();

        loadConfig();

        if (enabled) {
            startSpawnTask();
        } else {
            log.info("[MobSpawnManager] ✗ 動態怪物生成系統已停用 (config: enabled=false)");
        }
    }

    private void loadConfig() {
        File configFile = new File(plugin.getDataFolder(), "config/mob_spawner.yml");
        if (!configFile.exists()) {
            plugin.saveResource("config/mob_spawner.yml", false);
        }

        FileConfiguration config = YamlConfiguration.loadConfiguration(configFile);

        enabled = config.getBoolean("enabled", true);
        debug = config.getBoolean("debug", false);
        intervalTicks = config.getInt("interval-ticks", 60);
        spawnsPerCycle = config.getInt("spawns-per-cycle", 3);

        spawnRadiusMin = config.getInt("spawn-radius.min", 10);
        spawnRadiusMax = config.getInt("spawn-radius.max", 35);
        maxMobsPerPlayer = config.getInt("limits.max-mobs-per-player", 10);

        // Normal tier
        normalLevelOffsetMin = config.getInt("tiers.normal.level-offset-min", -3);
        normalLevelOffsetMax = config.getInt("tiers.normal.level-offset-max", 3);
        normalNamePrefix = ChatColor.translateAlternateColorCodes('&',
                config.getString("tiers.normal.name-prefix", ""));

        // Elite tier
        eliteChance = config.getDouble("tiers.elite.chance", 0.20);
        eliteLevelOffsetMin = config.getInt("tiers.elite.level-offset-min", 1);
        eliteLevelOffsetMax = config.getInt("tiers.elite.level-offset-max", 5);
        eliteStatMultiplier = config.getDouble("tiers.elite.stat-multiplier", 1.5);
        eliteNamePrefix = ChatColor.translateAlternateColorCodes('&',
                config.getString("tiers.elite.name-prefix", "&6⚔ "));

        // Boss tier — pity system
        bossBaseChance = config.getDouble("tiers.boss.base-chance", 0.002);
        bossPityIncrement = config.getDouble("tiers.boss.pity-increment", 0.003);
        bossCooldownSeconds = config.getInt("tiers.boss.cooldown-seconds", 1800);
        bossSpawnRadiusMin = config.getInt("tiers.boss.spawn-radius-min", 40);
        bossSpawnRadiusMax = config.getInt("tiers.boss.spawn-radius-max", 80);
        bossLevelOffsetMin = config.getInt("tiers.boss.level-offset-min", 3);
        bossLevelOffsetMax = config.getInt("tiers.boss.level-offset-max", 8);
        bossStatMultiplier = config.getDouble("tiers.boss.stat-multiplier", 3.0);
        bossNamePrefix = ChatColor.translateAlternateColorCodes('&',
                config.getString("tiers.boss.name-prefix", "&c✦ BOSS ✦ "));
        bossSpawnParticle = config.getString("tiers.boss.spawn-particle", "FLAME");
        bossParticleCount = config.getInt("tiers.boss.spawn-particle-count", 100);
        bossSpawnSound = config.getString("tiers.boss.spawn-sound", "ENTITY_ENDER_DRAGON_GROWL");
        bossSoundVolume = (float) config.getDouble("tiers.boss.spawn-sound-volume", 2.0);
        bossSoundPitch = (float) config.getDouble("tiers.boss.spawn-sound-pitch", 0.5);

        // Conditions
        nightOnly = config.getBoolean("conditions.night-only", false);
        maxLightLevel = config.getInt("conditions.max-light-level", 15);
        requireSolidGround = config.getBoolean("conditions.require-solid-ground", true);
        requireAirSpace = config.getBoolean("conditions.require-air-space", true);

        disabledWorlds = new HashSet<>(config.getStringList("disabled-worlds"));
    }

    private void startSpawnTask() {
        spawnTask = new BukkitRunnable() {
            @Override
            public void run() {
                int playerCount = plugin.getServer().getOnlinePlayers().size();
                if (playerCount == 0) return;

                if (debug) {
                    log.info("[MobSpawn] === 開始生成周期 === 在線玩家: " + playerCount);
                }

                for (Player player : plugin.getServer().getOnlinePlayers()) {
                    processPlayer(player);
                }
            }
        }.runTaskTimer(plugin, 40, intervalTicks);
    }

    private void processPlayer(Player player) {
        String pName = player.getName();

        // 跳過旁觀者
        if (player.getGameMode() == GameMode.SPECTATOR) {
            if (debug) log.info("[MobSpawn] 跳過 " + pName + ": 旁觀者模式");
            lastSkipReason = "旁觀者模式";
            return;
        }

        // 跳過禁用世界
        String worldName = player.getWorld().getName();
        if (disabledWorlds.contains(worldName)) {
            if (debug) log.info("[MobSpawn] 跳過 " + pName + ": 世界 " + worldName + " 已禁用");
            lastSkipReason = "世界禁用: " + worldName;
            return;
        }

        // 夜晚限制
        if (nightOnly) {
            long time = player.getWorld().getTime();
            if (time < 13000 || time > 23000) {
                if (debug) log.info("[MobSpawn] 跳過 " + pName + ": 白天 (time=" + time + ")");
                lastSkipReason = "白天";
                return;
            }
        }

        // ===== Zone-Based 檢查 =====
        ZoneManager zoneManager = plugin.getZoneManager();
        if (zoneManager == null || zoneManager.getZoneCount() == 0) {
            // 尚未設置任何 zone → 完全不生成自訂怪物
            if (debug) log.info("[MobSpawn] 跳過 " + pName + ": 尚未設定任何怪物區域 (/setmob)");
            lastSkipReason = "尚未設定怪物區域";
            return;
        }

        // 玩家在安全區域內 → 檢查是否為純安全區域（無生態域標籤）
        // 有生態域標籤的區域不阻止生成（怪物會生成在區域外）
        if (zoneManager.isInsideAnyZone(player.getLocation())) {
            // 檢查玩家所在的 zone 是否有 biome tag
            ZoneManager.MobZone playerZone = zoneManager.getZoneAt(player.getLocation());
            if (playerZone == null || playerZone.biomeTag == null) {
                // 純安全區域（無生態域標籤）→ 不生成
                if (debug) log.info("[MobSpawn] 跳過 " + pName + ": 在怪物安全區域內");
                lastSkipReason = "怪物安全區域";
                return;
            }
            // 有生態域標籤 → 允許生成（怪物生成在區域外）
            if (debug) log.info("[MobSpawn] " + pName + " 在生態域區域 '" + playerZone.name + "' [" + playerZone.biomeTag + "] 內，允許在區域外生成怪物");
        }

        // 保護區域 — 原有的 ProtectionArea 系統也繼續生效
        ProtectionAreaManager pam = plugin.getProtectionAreaManager();
        if (pam != null && pam.isInProtectedArea(player.getLocation())) {
            if (debug) log.info("[MobSpawn] 跳過 " + pName + ": 在保護區域內");
            lastSkipReason = "保護區域";
            return;
        }

        // 怪物數量上限
        int nearbyMobCount = countNearbyCustomMobs(player);
        if (nearbyMobCount >= maxMobsPerPlayer) {
            if (debug) log.info("[MobSpawn] 跳過 " + pName + ": 附近已有 " + nearbyMobCount + "/" + maxMobsPerPlayer + " 隻");
            lastSkipReason = "已達上限: " + nearbyMobCount;
            return;
        }

        // 檢查可用怪物 (普通怪物池，不包含 Boss)
        List<String> mobKeys = mobManager.getNormalMobKeys();
        if (mobKeys.isEmpty()) {
            if (debug) log.info("[MobSpawn] 跳過 " + pName + ": 沒有已註冊的普通怪物類型！");
            lastSkipReason = "無可用怪物類型";
            return;
        }

        // 嘗試生成
        int toSpawn = Math.min(spawnsPerCycle, maxMobsPerPlayer - nearbyMobCount);
        if (debug) log.info("[MobSpawn] 為 " + pName + " 嘗試生成 " + toSpawn + " 隻 (附近: " + nearbyMobCount + ", 可用類型: " + mobKeys.size() + ")");

        int spawned = 0;
        for (int i = 0; i < toSpawn; i++) {
            if (attemptSpawn(player, mobKeys)) {
                spawned++;
            }
        }

        if (debug) log.info("[MobSpawn] " + pName + " 本周期成功生成: " + spawned + "/" + toSpawn);
    }

    private int countNearbyCustomMobs(Player player) {
        int count = 0;
        int searchRadius = Math.max(spawnRadiusMax, bossSpawnRadiusMax);
        NamespacedKey key = mobManager.getCustomMobNamespacedKey();
        for (Entity entity : player.getNearbyEntities(searchRadius, searchRadius, searchRadius)) {
            if (entity instanceof LivingEntity mob) {
                if (mob.getPersistentDataContainer().has(key, PersistentDataType.STRING)) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * 嘗試生成一隻怪物
     */
    private boolean attemptSpawn(Player player, List<String> mobKeys) {
        totalSpawnAttempts++;

        // 先決定階級 (含 pity system)
        MobTier tier = determineTier(player);

        // 根據階級選擇不同的生成位置
        Location spawnLoc;
        if (tier == MobTier.BOSS) {
            spawnLoc = findBossSpawnLocation(player);
        } else {
            spawnLoc = findSpawnLocation(player);
        }

        if (spawnLoc == null) {
            totalLocationFails++;
            if (debug) log.info("[MobSpawn]   找不到有效生成位置 (嘗試5次失敗)");
            return false;
        }

        // ===== Zone-Based 等級計算 =====
        ZoneManager zoneManager = plugin.getZoneManager();
        int mobLevel;
        // Zone 一定存在 (processPlayer 已檢查過)
        int[] levelRange = zoneManager.calculateMobLevelRange(spawnLoc);
        int baseLevel = levelRange[0] + random.nextInt(Math.max(1, levelRange[1] - levelRange[0] + 1));

        // 再疊加階級偏移
        int tierOffset = calculateTierLevelOffset(tier);
        mobLevel = Math.max(1, baseLevel + tierOffset);

        if (debug) {
            int zoneTier = zoneManager.calculateTier(spawnLoc);
            log.info("[MobSpawn]   Zone等級: " + levelRange[0] + "~" + levelRange[1]
                    + " (Tier " + zoneTier + "), 基礎=" + baseLevel + " + 階級偏移=" + tierOffset
                    + " → 最終等級=" + mobLevel);
        }

        // ===== 根據等級篩選合適的怪物 =====
        // Boss 階級使用獨立的 Boss 怪物池
        List<String> candidateMobKeys;
        if (tier == MobTier.BOSS) {
            candidateMobKeys = mobManager.getBossMobKeys();
            if (candidateMobKeys.isEmpty()) {
                if (debug) log.info("[MobSpawn]   Boss 怪物池為空，跳過 Boss 生成");
                return false;
            }
        } else {
            candidateMobKeys = mobKeys;
        }

        // 檢查最近的zone是否有生態域標籤，如果有則過濾怪物
        List<String> filteredMobKeys = candidateMobKeys;
        ZoneManager.MobZone nearestZone = zoneManager.getNearestZone(spawnLoc);
        if (nearestZone != null && nearestZone.biomeTag != null) {
            String biomeTag = nearestZone.biomeTag.toLowerCase();
            filteredMobKeys = new ArrayList<>();
            for (String key : candidateMobKeys) {
                MobManager.MobData data = mobManager.getMobData(key);
                if (data == null) continue;
                List<String> mobTags = data.getTags();
                // 包含該生態域標籤的怪物，或沒有設定任何標籤的怪物（通用怪物）
                if (mobTags.isEmpty() || mobTags.contains(biomeTag)) {
                    filteredMobKeys.add(key);
                }
            }
            if (debug) {
                log.info("[MobSpawn]   生態域標籤: " + biomeTag + " → 過濾後可用怪物: " + filteredMobKeys.size() + "/" + candidateMobKeys.size());
            }
            // 如果過濾後沒有任何怪物，回退到候選池
            if (filteredMobKeys.isEmpty()) {
                if (debug) log.info("[MobSpawn]   生態域過濾後無怪物可用，回退到候選池");
                filteredMobKeys = candidateMobKeys;
            }
        }

        // ===== 日夜時段過濾 =====
        long worldTime = spawnLoc.getWorld().getTime(); // 0~24000
        boolean isNight = worldTime >= 13000 && worldTime < 23000;
        List<String> timeFilteredKeys = new ArrayList<>();
        for (String key : filteredMobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data == null) continue;
            String spawnTime = data.getSpawnTime();
            if (spawnTime.equals("all")) {
                timeFilteredKeys.add(key);
            } else if (spawnTime.equals("night") && isNight) {
                timeFilteredKeys.add(key);
            } else if (spawnTime.equals("day") && !isNight) {
                timeFilteredKeys.add(key);
            }
        }
        if (debug && timeFilteredKeys.size() != filteredMobKeys.size()) {
            log.info("[MobSpawn]   日夜過濾: " + (isNight ? "夜晚" : "白天") + " → " + timeFilteredKeys.size() + "/" + filteredMobKeys.size());
        }
        if (timeFilteredKeys.isEmpty()) {
            if (debug) log.info("[MobSpawn]   日夜過濾後無怪物可用，回退");
            timeFilteredKeys = filteredMobKeys;
        }
        filteredMobKeys = timeFilteredKeys;

        String mobKey = selectMobTypeForLevel(filteredMobKeys, mobLevel);

        if (mobKey == null) {
            if (debug) log.info("[MobSpawn]   找不到符合等級 " + mobLevel + " 的怪物類型");
            return false;
        }

        if (debug) {
            log.info("[MobSpawn]   生成: " + mobKey + " [" + tier.getDisplayName() + "] Lv." + mobLevel
                    + " 在 (" + spawnLoc.getBlockX() + ", " + spawnLoc.getBlockY() + ", " + spawnLoc.getBlockZ() + ")");
        }

        boolean success = spawnTieredMob(mobKey, spawnLoc, mobLevel, tier);
        if (success) {
            totalSpawnSuccess++;
            // BOSS 成功生成 → 重置 pity、設定冷卻
            if (tier == MobTier.BOSS) {
                UUID pid = player.getUniqueId();
                playerPityChance.put(pid, bossBaseChance);
                playerBossCooldown.put(pid, System.currentTimeMillis() + (bossCooldownSeconds * 1000L));
                if (debug) log.info("[MobSpawn]   ★ BOSS 已生成！pity 重置為 " + String.format("%.2f%%", bossBaseChance * 100)
                        + "，冷卻 " + bossCooldownSeconds + " 秒");
            }
        }
        return success;
    }

    /**
     * 計算階級等級偏移
     */
    private int calculateTierLevelOffset(MobTier tier) {
        return switch (tier) {
            case ELITE -> ThreadLocalRandom.current().nextInt(eliteLevelOffsetMin, eliteLevelOffsetMax + 1);
            case BOSS -> ThreadLocalRandom.current().nextInt(bossLevelOffsetMin, bossLevelOffsetMax + 1);
            default -> ThreadLocalRandom.current().nextInt(normalLevelOffsetMin, normalLevelOffsetMax + 1);
        };
    }

    /**
     * 決定怪物階級 (含累積機率系統)
     */
    private MobTier determineTier(Player player) {
        UUID pid = player.getUniqueId();

        // === BOSS 擲骰 (pity system) ===
        long now = System.currentTimeMillis();
        Long cooldownEnd = playerBossCooldown.get(pid);
        boolean bossOnCooldown = (cooldownEnd != null && now < cooldownEnd);

        if (!bossOnCooldown) {
            double currentPity = playerPityChance.getOrDefault(pid, bossBaseChance);
            double roll = random.nextDouble();

            if (debug) {
                log.info("[MobSpawn]   BOSS擲骰: roll=" + String.format("%.4f", roll)
                        + " 需要 < " + String.format("%.4f", currentPity)
                        + " (" + String.format("%.2f%%", currentPity * 100) + ")");
            }

            if (roll < currentPity) {
                return MobTier.BOSS;
            } else {
                double newPity = currentPity + bossPityIncrement;
                playerPityChance.put(pid, newPity);
                if (debug) {
                    log.info("[MobSpawn]   BOSS未命中，pity 累積: "
                            + String.format("%.2f%%", currentPity * 100) + " → "
                            + String.format("%.2f%%", newPity * 100));
                }
            }
        } else if (debug) {
            long remainSec = (cooldownEnd - now) / 1000;
            log.info("[MobSpawn]   BOSS 冷卻中 (剩餘 " + remainSec + " 秒)");
        }

        // === 精英 / 普通 擲骰 ===
        // 高 tier 區域提升精英機率
        double adjustedEliteChance = eliteChance;
        ZoneManager zoneManager = plugin.getZoneManager();
        if (zoneManager != null && zoneManager.getZoneCount() > 0) {
            int zoneTier = zoneManager.calculateTier(player.getLocation());
            // 每個 tier 增加 5% 精英機率
            adjustedEliteChance = Math.min(0.80, eliteChance + (zoneTier - 1) * 0.05);
        }

        double roll = random.nextDouble();
        if (roll < adjustedEliteChance) {
            return MobTier.ELITE;
        }
        return MobTier.NORMAL;
    }

    /**
     * 尋找普通怪 / 精英怪的生成位置
     */
    private Location findSpawnLocation(Player player) {
        return findSpawnLocationInRadius(player, spawnRadiusMin, spawnRadiusMax);
    }

    /**
     * 尋找 BOSS 的生成位置 (更遠)
     */
    private Location findBossSpawnLocation(Player player) {
        return findSpawnLocationInRadius(player, bossSpawnRadiusMin, bossSpawnRadiusMax);
    }

    /**
     * 在指定半徑範圍內尋找有效生成位置
     */
    private Location findSpawnLocationInRadius(Player player, int radiusMin, int radiusMax) {
        Location playerLoc = player.getLocation();
        World world = player.getWorld();

        for (int attempt = 0; attempt < 5; attempt++) {
            double angle = random.nextDouble() * Math.PI * 2;
            double distance = radiusMin + random.nextDouble() * (radiusMax - radiusMin);

            double x = playerLoc.getX() + Math.cos(angle) * distance;
            double z = playerLoc.getZ() + Math.sin(angle) * distance;

            // 確保 chunk 已載入
            int chunkX = (int) x >> 4;
            int chunkZ = (int) z >> 4;
            if (!world.isChunkLoaded(chunkX, chunkZ)) {
                continue;
            }

            int highestY = world.getHighestBlockYAt((int) x, (int) z);
            if (highestY < world.getMinHeight() + 1) {
                continue;
            }

            Location candidate = new Location(world, x + 0.5, highestY + 1, z + 0.5);

            if (!isValidSpawnLocation(candidate)) {
                continue;
            }

            // 檢查是否在 Zone 安全區內
            ZoneManager zoneManager = plugin.getZoneManager();
            if (zoneManager != null && zoneManager.isInsideAnyZone(candidate)) {
                if (debug) log.info("[MobSpawn]   候選位置在怪物安全區域內，跳過");
                continue;
            }

            // 檢查是否在保護區域內
            ProtectionAreaManager pam = plugin.getProtectionAreaManager();
            if (pam != null && pam.isInProtectedArea2D(candidate)) {
                if (debug) log.info("[MobSpawn]   候選位置在保護區域內，跳過");
                continue;
            }

            if (maxLightLevel < 15) {
                Block block = candidate.getBlock();
                if (block.getLightLevel() > maxLightLevel) {
                    continue;
                }
            }

            return candidate;
        }

        return null;
    }

    private boolean isValidSpawnLocation(Location location) {
        Block feetBlock = location.getBlock();
        Block groundBlock = feetBlock.getRelative(BlockFace.DOWN);
        Block headBlock = feetBlock.getRelative(BlockFace.UP);

        if (requireSolidGround && !groundBlock.getType().isSolid()) {
            return false;
        }

        if (requireAirSpace) {
            if (!feetBlock.getType().isAir() || !headBlock.getType().isAir()) {
                return false;
            }
        }

        if (groundBlock.isLiquid() || feetBlock.isLiquid()) {
            return false;
        }

        return true;
    }

    /**
     * 舊版等級計算 (當沒有 zone 時使用)
     */
    private int calculateLevelLegacy(int playerLevel, MobTier tier, Location playerLocation) {
        int levelOffset = calculateTierLevelOffset(tier);
        int level = playerLevel + levelOffset;
        return Math.max(1, level);
    }

    private String selectMobType(List<String> mobKeys) {
        return mobKeys.get(random.nextInt(mobKeys.size()));
    }

    /**
     * 根據等級篩選合適的怪物類型
     * 只選擇其 level-range 包含（或接近）指定等級的怪物
     *
     * @param mobKeys 所有可用的怪物 key
     * @param level   目標等級
     * @return 選中的 mob key，或 null（沒有符合的）
     */
    private String selectMobTypeForLevel(List<String> mobKeys, int level) {
        // 第一輪：嚴格匹配 — 怪物的 level-range 包含目標等級
        List<String> exactMatches = new ArrayList<>();
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data == null) continue;
            if (level >= data.getMinLevel() && level <= data.getMaxLevel()) {
                exactMatches.add(key);
            }
        }
        if (!exactMatches.isEmpty()) {
            return exactMatches.get(random.nextInt(exactMatches.size()));
        }

        // 第二輪：寬鬆匹配 — 允許 ±5 等級的容差
        List<String> nearMatches = new ArrayList<>();
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data == null) continue;
            if (level >= data.getMinLevel() - 5 && level <= data.getMaxLevel() + 5) {
                nearMatches.add(key);
            }
        }
        if (!nearMatches.isEmpty()) {
            return nearMatches.get(random.nextInt(nearMatches.size()));
        }

        // 第三輪：找最接近的怪物
        String closest = null;
        int closestDist = Integer.MAX_VALUE;
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data == null) continue;
            int dist = Math.min(Math.abs(level - data.getMinLevel()), Math.abs(level - data.getMaxLevel()));
            if (dist < closestDist) {
                closestDist = dist;
                closest = key;
            }
        }
        return closest;
    }

    private boolean spawnTieredMob(String mobKey, Location location, int level, MobTier tier) {
        LivingEntity mob = mobManager.spawnCustomMobWithLevel(mobKey, location, level);
        if (mob == null) {
            if (debug) log.warning("[MobSpawn]   生成失敗: mobManager 回傳 null (key=" + mobKey + ")");
            return false;
        }

        mobManager.setMobTier(mob, tier.name());
        spawnedMobs.add(mob.getUniqueId());

        MobManager.MobData mobData = mobManager.getMobData(mobKey);

        // 群體生成（如草原狼 pack_passive）
        if (mobData != null && "pack_passive".equalsIgnoreCase(mobData.getSpecialBehavior())) {
            int packSize = 2 + random.nextInt(4); // 額外 2~5 隻（加上原本的 1 隻 = 3~6 隻）
            for (int i = 0; i < packSize; i++) {
                double ox = (random.nextDouble() - 0.5) * 4;
                double oz = (random.nextDouble() - 0.5) * 4;
                Location packLoc = location.clone().add(ox, 0, oz);
                packLoc.setY(packLoc.getWorld().getHighestBlockYAt(packLoc) + 1);
                LivingEntity packMob = mobManager.spawnCustomMobWithLevel(mobKey, packLoc, level);
                if (packMob != null) {
                    mobManager.setMobTier(packMob, tier.name());
                    spawnedMobs.add(packMob.getUniqueId());
                }
            }
        }

        switch (tier) {
            case ELITE:
                applyEliteModifiers(mob);
                break;
            case BOSS:
                applyBossModifiers(mob, location, level);
                break;
            default:
                if (!normalNamePrefix.isEmpty()) {
                    String currentName = mob.getCustomName();
                    if (currentName != null) {
                        mob.setCustomName(normalNamePrefix + currentName);
                    }
                }
                break;
        }
        return true;
    }

    private void applyEliteModifiers(LivingEntity mob) {
        if (eliteStatMultiplier != 1.0) {
            double newMaxHealth = mob.getMaxHealth() * eliteStatMultiplier;
            mob.setMaxHealth(newMaxHealth);
            mob.setHealth(newMaxHealth);
        }

        String currentName = mob.getCustomName();
        if (currentName != null) {
            mob.setCustomName(eliteNamePrefix + ChatColor.translateAlternateColorCodes('&', "&e[精英] ") + currentName);
        }

        mob.setGlowing(true);
    }

    private void applyBossModifiers(LivingEntity mob, Location location, int level) {
        if (bossStatMultiplier != 1.0) {
            double newMaxHealth = mob.getMaxHealth() * bossStatMultiplier;
            mob.setMaxHealth(newMaxHealth);
            mob.setHealth(newMaxHealth);
        }

        String currentName = mob.getCustomName();
        if (currentName != null) {
            mob.setCustomName(bossNamePrefix + currentName);
        }

        mob.setGlowing(true);

        try {
            Particle particle = Particle.valueOf(bossSpawnParticle);
            location.getWorld().spawnParticle(particle, location.clone().add(0, 1, 0),
                    bossParticleCount, 1.5, 1.5, 1.5, 0.1);
        } catch (IllegalArgumentException e) {
            location.getWorld().spawnParticle(Particle.FLAME, location.clone().add(0, 1, 0),
                    bossParticleCount, 1.5, 1.5, 1.5, 0.1);
        }

        location.getWorld().spawnParticle(Particle.SOUL_FIRE_FLAME, location.clone().add(0, 1, 0),
                50, 2.0, 2.0, 2.0, 0.05);

        try {
            Sound sound = Registry.SOUNDS.get(NamespacedKey.minecraft(bossSpawnSound.toLowerCase()));
            if (sound != null) {
                location.getWorld().playSound(location, sound, bossSoundVolume, bossSoundPitch);
            } else {
                location.getWorld().playSound(location, Sound.ENTITY_ENDER_DRAGON_GROWL, 2.0f, 0.5f);
            }
        } catch (Exception e) {
            location.getWorld().playSound(location, Sound.ENTITY_ENDER_DRAGON_GROWL, 2.0f, 0.5f);
        }

        announceBossSpawn(mob, location, level);

        // 為 Boss 創建 BossBar
        BossBarManager bossBarMgr = plugin.getBossBarManager();
        if (bossBarMgr != null) {
            bossBarMgr.createBossBossBar(mob, level);
        }
    }

    private void announceBossSpawn(LivingEntity mob, Location location, int level) {
        String mobName = mob.getCustomName() != null ? mob.getCustomName() : "未知BOSS";
        int bx = location.getBlockX();
        int by = location.getBlockY();
        int bz = location.getBlockZ();

        String coordStr = ChatColor.AQUA + "(" + bx + ", " + by + ", " + bz + ")";

        // 顯示 Zone Tier 資訊
        String tierInfo = "";
        ZoneManager zoneManager = plugin.getZoneManager();
        if (zoneManager != null && zoneManager.getZoneCount() > 0) {
            int zoneTier = zoneManager.calculateTier(location);
            tierInfo = ChatColor.GRAY + " [" + zoneManager.getTierDisplayName(zoneTier) + ChatColor.GRAY + "]";
        }

        String message = ChatColor.RED + "" + ChatColor.BOLD + "⚠ "
                + ChatColor.DARK_RED + "" + ChatColor.BOLD + "【BOSS出現】\n"
                + ChatColor.RED + mobName + ChatColor.GRAY + " (Lv." + level + ")" + tierInfo + "\n"
                + ChatColor.YELLOW + "座標: " + coordStr + "\n"
                + ChatColor.GOLD + "快去討伐吧！";

        double notifyRadius = bossSpawnRadiusMax * 3.0;

        for (Player player : location.getWorld().getPlayers()) {
            if (player.getLocation().distance(location) <= notifyRadius) {
                player.sendMessage("");
                player.sendMessage(ChatColor.GOLD + "════════════════════════════════");
                player.sendMessage(message);
                player.sendMessage(ChatColor.GOLD + "════════════════════════════════");
                player.sendMessage("");
                player.sendTitle(
                        ChatColor.RED + "⚠ BOSS 出現 ⚠",
                        ChatColor.GOLD + mobName + ChatColor.GRAY + " Lv." + level + "  " + coordStr,
                        10, 80, 20
                );
            }
        }
    }

    // ==========================================
    // ===== 測試 / 指令用公開方法 =====
    // ==========================================

    /**
     * 強制在玩家附近生成一隻指定類型的怪物 (用於測試)
     */
    public String forceSpawn(Player player, String mobKey, MobTier tier) {
        List<String> mobKeys = mobManager.getMobKeys();
        if (mobKeys.isEmpty()) {
            return ChatColor.RED + "沒有已註冊的怪物類型！";
        }

        if (mobKey == null || mobKey.isEmpty()) {
            mobKey = selectMobType(mobKeys);
        } else if (mobManager.getMobData(mobKey) == null) {
            return ChatColor.RED + "未知的怪物類型: " + mobKey + "\n"
                    + ChatColor.YELLOW + "可用類型: " + String.join(", ", mobKeys);
        }

        Location spawnLoc = player.getLocation().add(player.getLocation().getDirection().multiply(8));
        spawnLoc.setY(player.getWorld().getHighestBlockYAt(spawnLoc.getBlockX(), spawnLoc.getBlockZ()) + 1);

        // Zone-based level
        int mobLevel;
        ZoneManager zoneManager = plugin.getZoneManager();
        if (zoneManager != null && zoneManager.getZoneCount() > 0) {
            int[] levelRange = zoneManager.calculateMobLevelRange(spawnLoc);
            int baseLevel = levelRange[0] + random.nextInt(Math.max(1, levelRange[1] - levelRange[0] + 1));
            int tierOffset = calculateTierLevelOffset(tier);
            mobLevel = Math.max(1, baseLevel + tierOffset);
        } else {
            PlayerStats stats = statsManager.getStats(player);
            int playerLevel = stats.getLevel();
            mobLevel = calculateLevelLegacy(playerLevel, tier, player.getLocation());
        }

        boolean success = spawnTieredMob(mobKey, spawnLoc, mobLevel, tier);
        if (success) {
            return ChatColor.GREEN + "✓ 成功生成 " + tier.getColor() + "[" + tier.getDisplayName() + "] "
                    + ChatColor.WHITE + mobKey + " Lv." + mobLevel
                    + ChatColor.GRAY + " 在 (" + spawnLoc.getBlockX() + ", " + spawnLoc.getBlockY() + ", " + spawnLoc.getBlockZ() + ")";
        } else {
            return ChatColor.RED + "✗ 生成失敗: " + mobKey;
        }
    }

    /**
     * 取得診斷資訊 (用於 /mobspawn status)
     */
    public List<String> getDebugStatus(Player player) {
        List<String> lines = new ArrayList<>();
        lines.add(ChatColor.GOLD + "========= MobSpawnManager 診斷 =========");
        lines.add(ChatColor.YELLOW + "系統狀態: " + (enabled ? ChatColor.GREEN + "啟用" : ChatColor.RED + "停用"));
        lines.add(ChatColor.YELLOW + "生成任務: " + (spawnTask != null && !spawnTask.isCancelled() ? ChatColor.GREEN + "運行中" : ChatColor.RED + "未運行"));
        lines.add(ChatColor.YELLOW + "間隔: " + ChatColor.WHITE + intervalTicks + " ticks (" + (intervalTicks / 20.0) + "秒)");
        lines.add(ChatColor.YELLOW + "每次生成: " + ChatColor.WHITE + spawnsPerCycle + " 隻");
        lines.add("");

        // 怪物類型
        List<String> mobKeys = mobManager.getMobKeys();
        List<String> bossMobKeys = mobManager.getBossMobKeys();
        List<String> normalMobKeys = mobManager.getNormalMobKeys();
        lines.add(ChatColor.YELLOW + "已註冊怪物類型: " + ChatColor.WHITE + mobKeys.size()
                + ChatColor.GRAY + " (普通: " + normalMobKeys.size() + ", Boss: " + bossMobKeys.size() + ")");
        if (mobKeys.size() <= 20) {
            lines.add(ChatColor.GRAY + "  " + String.join(", ", mobKeys));
        }
        if (!bossMobKeys.isEmpty()) {
            lines.add(ChatColor.RED + "  Boss: " + String.join(", ", bossMobKeys));
        }
        lines.add("");

        // Zone 資訊
        ZoneManager zoneManager = plugin.getZoneManager();
        if (zoneManager != null) {
            lines.add(ChatColor.AQUA + "--- Zone-Based 系統 ---");
            lines.add(ChatColor.YELLOW + "怪物區域數量: " + ChatColor.WHITE + zoneManager.getZoneCount());
            for (var zone : zoneManager.getAllZones()) {
                lines.add(ChatColor.GRAY + "  " + zone.name + ": Lv." + zone.minLevel + "~" + zone.maxLevel
                        + " (步進: " + zone.radiusStep + "格)");
            }
            lines.add("");
        }

        // 玩家資訊
        if (player != null) {
            lines.add(ChatColor.AQUA + "--- 你的狀態 ---");
            lines.add(ChatColor.YELLOW + "遊戲模式: " + ChatColor.WHITE + player.getGameMode().name());
            lines.add(ChatColor.YELLOW + "世界: " + ChatColor.WHITE + player.getWorld().getName()
                    + (disabledWorlds.contains(player.getWorld().getName()) ? ChatColor.RED + " (已禁用)" : ChatColor.GREEN + " (允許)"));

            // Zone-based 狀態
            if (zoneManager != null && zoneManager.getZoneCount() > 0) {
                boolean inZone = zoneManager.isInsideAnyZone(player.getLocation());
                lines.add(ChatColor.YELLOW + "安全區域: " + (inZone ? ChatColor.GREEN + "✓ 在安全區內" : ChatColor.RED + "✗ 在野外"));

                int zoneTier = zoneManager.calculateTier(player.getLocation());
                lines.add(ChatColor.YELLOW + "Zone Tier: " + zoneManager.getTierDisplayName(zoneTier));

                int[] levelRange = zoneManager.calculateMobLevelRange(player.getLocation());
                lines.add(ChatColor.YELLOW + "怪物等級: " + ChatColor.WHITE + "Lv." + levelRange[0] + " ~ Lv." + levelRange[1]);

                double dist = zoneManager.getDistanceToNearestZoneBorder(player.getLocation());
                if (dist >= 0) {
                    lines.add(ChatColor.YELLOW + "距最近安全區: " + ChatColor.WHITE + String.format("%.1f", dist) + " 格");
                }
            }

            int nearbyCount = countNearbyCustomMobs(player);
            lines.add(ChatColor.YELLOW + "附近自訂怪物: " + ChatColor.WHITE + nearbyCount + "/" + maxMobsPerPlayer
                    + (nearbyCount >= maxMobsPerPlayer ? ChatColor.RED + " (已達上限!)" : ChatColor.GREEN + " (未滿 ✓)"));

            PlayerStats stats = statsManager.getStats(player);
            lines.add(ChatColor.YELLOW + "玩家等級: " + ChatColor.WHITE + stats.getLevel());

            if (nightOnly) {
                long time = player.getWorld().getTime();
                lines.add(ChatColor.YELLOW + "時間: " + ChatColor.WHITE + time
                        + ((time < 13000 || time > 23000) ? ChatColor.RED + " (白天，不生成)" : ChatColor.GREEN + " (夜晚 ✓)"));
            }

            // BOSS pity 系統資訊
            lines.add("");
            lines.add(ChatColor.LIGHT_PURPLE + "--- BOSS 累積機率系統 ---");
            UUID pid = player.getUniqueId();
            double currentPity = playerPityChance.getOrDefault(pid, bossBaseChance);
            lines.add(ChatColor.YELLOW + "基礎機率: " + ChatColor.WHITE + String.format("%.2f%%", bossBaseChance * 100));
            lines.add(ChatColor.YELLOW + "每次累積: " + ChatColor.WHITE + "+" + String.format("%.2f%%", bossPityIncrement * 100));
            lines.add(ChatColor.YELLOW + "當前機率: " + ChatColor.GREEN + String.format("%.2f%%", currentPity * 100));

            Long cooldownEnd = playerBossCooldown.get(pid);
            if (cooldownEnd != null && System.currentTimeMillis() < cooldownEnd) {
                long remainSec = (cooldownEnd - System.currentTimeMillis()) / 1000;
                long min = remainSec / 60;
                long sec = remainSec % 60;
                lines.add(ChatColor.YELLOW + "BOSS冷卻: " + ChatColor.RED + min + "分" + sec + "秒");
            } else {
                lines.add(ChatColor.YELLOW + "BOSS冷卻: " + ChatColor.GREEN + "就緒 ✓");
            }
            lines.add(ChatColor.YELLOW + "BOSS生成範圍: " + ChatColor.WHITE + bossSpawnRadiusMin + "~" + bossSpawnRadiusMax + " 格");
        }
        lines.add("");

        // 統計
        lines.add(ChatColor.AQUA + "--- 生成統計 ---");
        lines.add(ChatColor.YELLOW + "總嘗試: " + ChatColor.WHITE + totalSpawnAttempts);
        lines.add(ChatColor.YELLOW + "總成功: " + ChatColor.GREEN + totalSpawnSuccess);
        lines.add(ChatColor.YELLOW + "位置失敗: " + ChatColor.RED + totalLocationFails);
        lines.add(ChatColor.YELLOW + "追蹤中怪物: " + ChatColor.WHITE + getSpawnedMobCount());
        lines.add(ChatColor.YELLOW + "最後跳過原因: " + ChatColor.WHITE + lastSkipReason);
        lines.add(ChatColor.GOLD + "==========================================");

        return lines;
    }

    /**
     * 清除所有已追蹤的怪物
     */
    public int clearAllSpawnedMobs() {
        int removed = 0;
        for (UUID uuid : spawnedMobs) {
            Entity entity = plugin.getServer().getEntity(uuid);
            if (entity != null && !entity.isDead()) {
                entity.remove();
                removed++;
            }
        }
        spawnedMobs.clear();
        return removed;
    }

    /**
     * 切換 debug 模式
     */
    public boolean toggleDebug() {
        debug = !debug;
        return debug;
    }

    public void reload() {
        if (spawnTask != null) {
            spawnTask.cancel();
            spawnTask = null;
        }
        loadConfig();
        if (enabled) {
            startSpawnTask();
        } else {
            log.info("[MobSpawnManager] 配置已重新載入，生成系統已停用");
        }
    }

    public void shutdown() {
        if (spawnTask != null) {
            spawnTask.cancel();
            spawnTask = null;
        }
        int removed = clearAllSpawnedMobs();
    }

    public int getSpawnedMobCount() {
        spawnedMobs.removeIf(uuid -> {
            Entity entity = plugin.getServer().getEntity(uuid);
            return entity == null || entity.isDead();
        });
        return spawnedMobs.size();
    }

    public boolean isEnabled() {
        return enabled;
    }
}

package com.customrpg.managers;

import com.customrpg.CustomRPG;
import com.customrpg.players.PlayerStats;
import org.bukkit.*;
import org.bukkit.block.Block;
import org.bukkit.block.BlockFace;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Entity;
import org.bukkit.entity.EntityType;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.scheduler.BukkitTask;

import java.io.File;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;
import java.util.logging.Logger;

/**
 * MobSpawnManager - 區域式動態怪物生成系統
 *
 * Zone-Based 生成：
 * - 玩家在 zone 內 → 不生成怪物
 * - 玩家在 zone 外 → 依距離計算怪物等級 (tier 系統)
 * - 保留 BOSS / ELITE / NORMAL 階級系統
 * - 保留累積機率 (pity) 系統
 */
public class MobSpawnManager {

    public enum MobTier {
        NORMAL("普通", ChatColor.WHITE),
        ELITE("精英", ChatColor.GOLD),
        BOSS("BOSS", ChatColor.RED);

        private final String displayName;
        private final ChatColor color;

        MobTier(String displayName, ChatColor color) {
            this.displayName = displayName;
            this.color = color;
        }

        public String getDisplayName() { return displayName; }
        public ChatColor getColor() { return color; }
    }

    private final CustomRPG plugin;
    private final MobManager mobManager;
    private final PlayerStatsManager statsManager;
    private final Logger log;
    private BukkitTask spawnTask;

    // Debug mode
    private boolean debug = false;

    // ===== Configuration =====
    private boolean enabled;
    private int intervalTicks;
    private int spawnsPerCycle;
    private int spawnRadiusMin;
    private int spawnRadiusMax;
    private int maxMobsPerPlayer;

    // Tier settings
    private int normalLevelOffsetMin, normalLevelOffsetMax;
    private String normalNamePrefix;

    private double eliteChance;
    private int eliteLevelOffsetMin, eliteLevelOffsetMax;
    private double eliteStatMultiplier;
    private String eliteNamePrefix;

    // Boss — 累積機率系統 (pity system)
    private double bossBaseChance;
    private double bossPityIncrement;
    private int bossCooldownSeconds;
    private int bossSpawnRadiusMin;
    private int bossSpawnRadiusMax;
    private int bossLevelOffsetMin, bossLevelOffsetMax;
    private double bossStatMultiplier;
    private String bossNamePrefix;
    private String bossSpawnParticle;
    private int bossParticleCount;
    private String bossSpawnSound;
    private float bossSoundVolume, bossSoundPitch;

    // Boss pity 運行時狀態 (per-player)
    private final Map<UUID, Double> playerPityChance = new HashMap<>();
    private final Map<UUID, Long> playerBossCooldown = new HashMap<>();

    // Conditions
    private boolean nightOnly;
    private int maxLightLevel;
    private boolean requireSolidGround;
    private boolean requireAirSpace;

    // Disabled worlds
    private Set<String> disabledWorlds;

    // Track spawned mobs
    private final Set<UUID> spawnedMobs = new HashSet<>();
    private final Random random = new Random();

    // 統計用
    private int totalSpawnAttempts = 0;
    private int totalSpawnSuccess = 0;
    private int totalLocationFails = 0;
    private String lastSkipReason = "無";

    public MobSpawnManager(CustomRPG plugin, MobManager mobManager, PlayerStatsManager statsManager) {
        this.plugin = plugin;
        this.mobManager = mobManager;
        this.statsManager = statsManager;
        this.log = plugin.getLogger();

        loadConfig();

        if (enabled) {
            startSpawnTask();
        } else {
            log.info("[MobSpawnManager] ✗ 動態怪物生成系統已停用 (config: enabled=false)");
        }
    }

    private void loadConfig() {
        File configFile = new File(plugin.getDataFolder(), "config/mob_spawner.yml");
        if (!configFile.exists()) {
            plugin.saveResource("config/mob_spawner.yml", false);
        }

        FileConfiguration config = YamlConfiguration.loadConfiguration(configFile);

        enabled = config.getBoolean("enabled", true);
        debug = config.getBoolean("debug", false);
        intervalTicks = config.getInt("interval-ticks", 60);
        spawnsPerCycle = config.getInt("spawns-per-cycle", 3);

        spawnRadiusMin = config.getInt("spawn-radius.min", 10);
        spawnRadiusMax = config.getInt("spawn-radius.max", 35);
        maxMobsPerPlayer = config.getInt("limits.max-mobs-per-player", 10);

        // Normal tier
        normalLevelOffsetMin = config.getInt("tiers.normal.level-offset-min", -3);
        normalLevelOffsetMax = config.getInt("tiers.normal.level-offset-max", 3);
        normalNamePrefix = ChatColor.translateAlternateColorCodes('&',
                config.getString("tiers.normal.name-prefix", ""));

        // Elite tier
        eliteChance = config.getDouble("tiers.elite.chance", 0.20);
        eliteLevelOffsetMin = config.getInt("tiers.elite.level-offset-min", 1);
        eliteLevelOffsetMax = config.getInt("tiers.elite.level-offset-max", 5);
        eliteStatMultiplier = config.getDouble("tiers.elite.stat-multiplier", 1.5);
        eliteNamePrefix = ChatColor.translateAlternateColorCodes('&',
                config.getString("tiers.elite.name-prefix", "&6⚔ "));

        // Boss tier — pity system
        bossBaseChance = config.getDouble("tiers.boss.base-chance", 0.002);
        bossPityIncrement = config.getDouble("tiers.boss.pity-increment", 0.003);
        bossCooldownSeconds = config.getInt("tiers.boss.cooldown-seconds", 1800);
        bossSpawnRadiusMin = config.getInt("tiers.boss.spawn-radius-min", 40);
        bossSpawnRadiusMax = config.getInt("tiers.boss.spawn-radius-max", 80);
        bossLevelOffsetMin = config.getInt("tiers.boss.level-offset-min", 3);
        bossLevelOffsetMax = config.getInt("tiers.boss.level-offset-max", 8);
        bossStatMultiplier = config.getDouble("tiers.boss.stat-multiplier", 3.0);
        bossNamePrefix = ChatColor.translateAlternateColorCodes('&',
                config.getString("tiers.boss.name-prefix", "&c✦ BOSS ✦ "));
        bossSpawnParticle = config.getString("tiers.boss.spawn-particle", "FLAME");
        bossParticleCount = config.getInt("tiers.boss.spawn-particle-count", 100);
        bossSpawnSound = config.getString("tiers.boss.spawn-sound", "ENTITY_ENDER_DRAGON_GROWL");
        bossSoundVolume = (float) config.getDouble("tiers.boss.spawn-sound-volume", 2.0);
        bossSoundPitch = (float) config.getDouble("tiers.boss.spawn-sound-pitch", 0.5);

        // Conditions
        nightOnly = config.getBoolean("conditions.night-only", false);
        maxLightLevel = config.getInt("conditions.max-light-level", 15);
        requireSolidGround = config.getBoolean("conditions.require-solid-ground", true);
        requireAirSpace = config.getBoolean("conditions.require-air-space", true);

        disabledWorlds = new HashSet<>(config.getStringList("disabled-worlds"));
    }

    private void startSpawnTask() {
        spawnTask = new BukkitRunnable() {
            @Override
            public void run() {
                int playerCount = plugin.getServer().getOnlinePlayers().size();
                if (playerCount == 0) return;

                if (debug) {
                    log.info("[MobSpawn] === 開始生成周期 === 在線玩家: " + playerCount);
                }

                for (Player player : plugin.getServer().getOnlinePlayers()) {
                    processPlayer(player);
                }
            }
        }.runTaskTimer(plugin, 40, intervalTicks);
    }

    private void processPlayer(Player player) {
        String pName = player.getName();

        // 跳過旁觀者
        if (player.getGameMode() == GameMode.SPECTATOR) {
            if (debug) log.info("[MobSpawn] 跳過 " + pName + ": 旁觀者模式");
            lastSkipReason = "旁觀者模式";
            return;
        }

        // 跳過禁用世界
        String worldName = player.getWorld().getName();
        if (disabledWorlds.contains(worldName)) {
            if (debug) log.info("[MobSpawn] 跳過 " + pName + ": 世界 " + worldName + " 已禁用");
            lastSkipReason = "世界禁用: " + worldName;
            return;
        }

        // 夜晚限制
        if (nightOnly) {
            long time = player.getWorld().getTime();
            if (time < 13000 || time > 23000) {
                if (debug) log.info("[MobSpawn] 跳過 " + pName + ": 白天 (time=" + time + ")");
                lastSkipReason = "白天";
                return;
            }
        }

        // ===== Zone-Based 檢查 =====
        ZoneManager zoneManager = plugin.getZoneManager();
        if (zoneManager == null || zoneManager.getZoneCount() == 0) {
            // 尚未設置任何 zone → 完全不生成自訂怪物
            if (debug) log.info("[MobSpawn] 跳過 " + pName + ": 尚未設定任何怪物區域 (/setmob)");
            lastSkipReason = "尚未設定怪物區域";
            return;
        }

        // 玩家在安全區域內 → 檢查是否為純安全區域（無生態域標籤）
        // 有生態域標籤的區域不阻止生成（怪物會生成在區域外）
        if (zoneManager.isInsideAnyZone(player.getLocation())) {
            // 檢查玩家所在的 zone 是否有 biome tag
            ZoneManager.MobZone playerZone = zoneManager.getZoneAt(player.getLocation());
            if (playerZone == null || playerZone.biomeTag == null) {
                // 純安全區域（無生態域標籤）→ 不生成
                if (debug) log.info("[MobSpawn] 跳過 " + pName + ": 在怪物安全區域內");
                lastSkipReason = "怪物安全區域";
                return;
            }
            // 有生態域標籤 → 允許生成（怪物生成在區域外）
            if (debug) log.info("[MobSpawn] " + pName + " 在生態域區域 '" + playerZone.name + "' [" + playerZone.biomeTag + "] 內，允許在區域外生成怪物");
        }

        // 保護區域 — 原有的 ProtectionArea 系統也繼續生效
        ProtectionAreaManager pam = plugin.getProtectionAreaManager();
        if (pam != null && pam.isInProtectedArea(player.getLocation())) {
            if (debug) log.info("[MobSpawn] 跳過 " + pName + ": 在保護區域內");
            lastSkipReason = "保護區域";
            return;
        }

        // 怪物數量上限
        int nearbyMobCount = countNearbyCustomMobs(player);
        if (nearbyMobCount >= maxMobsPerPlayer) {
            if (debug) log.info("[MobSpawn] 跳過 " + pName + ": 附近已有 " + nearbyMobCount + "/" + maxMobsPerPlayer + " 隻");
            lastSkipReason = "已達上限: " + nearbyMobCount;
            return;
        }

        // 檢查可用怪物 (普通怪物池，不包含 Boss)
        List<String> mobKeys = mobManager.getNormalMobKeys();
        if (mobKeys.isEmpty()) {
            if (debug) log.info("[MobSpawn] 跳過 " + pName + ": 沒有已註冊的普通怪物類型！");
            lastSkipReason = "無可用怪物類型";
            return;
        }

        // 嘗試生成
        int toSpawn = Math.min(spawnsPerCycle, maxMobsPerPlayer - nearbyMobCount);
        if (debug) log.info("[MobSpawn] 為 " + pName + " 嘗試生成 " + toSpawn + " 隻 (附近: " + nearbyMobCount + ", 可用類型: " + mobKeys.size() + ")");

        int spawned = 0;
        for (int i = 0; i < toSpawn; i++) {
            if (attemptSpawn(player, mobKeys)) {
                spawned++;
            }
        }

        if (debug) log.info("[MobSpawn] " + pName + " 本周期成功生成: " + spawned + "/" + toSpawn);
    }

    private int countNearbyCustomMobs(Player player) {
        int count = 0;
        int searchRadius = Math.max(spawnRadiusMax, bossSpawnRadiusMax);
        NamespacedKey key = mobManager.getCustomMobNamespacedKey();
        for (Entity entity : player.getNearbyEntities(searchRadius, searchRadius, searchRadius)) {
            if (entity instanceof LivingEntity mob) {
                if (mob.getPersistentDataContainer().has(key, PersistentDataType.STRING)) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * 嘗試生成一隻怪物
     */
    private boolean attemptSpawn(Player player, List<String> mobKeys) {
        totalSpawnAttempts++;

        // 先決定階級 (含 pity system)
        MobTier tier = determineTier(player);

        // 根據階級選擇不同的生成位置
        Location spawnLoc;
        if (tier == MobTier.BOSS) {
            spawnLoc = findBossSpawnLocation(player);
        } else {
            spawnLoc = findSpawnLocation(player);
        }

        if (spawnLoc == null) {
            totalLocationFails++;
            if (debug) log.info("[MobSpawn]   找不到有效生成位置 (嘗試5次失敗)");
            return false;
        }

        // ===== Zone-Based 等級計算 =====
        ZoneManager zoneManager = plugin.getZoneManager();
        int mobLevel;
        // Zone 一定存在 (processPlayer 已檢查過)
        int[] levelRange = zoneManager.calculateMobLevelRange(spawnLoc);
        int baseLevel = levelRange[0] + random.nextInt(Math.max(1, levelRange[1] - levelRange[0] + 1));

        // 再疊加階級偏移
        int tierOffset = calculateTierLevelOffset(tier);
        mobLevel = Math.max(1, baseLevel + tierOffset);

        if (debug) {
            int zoneTier = zoneManager.calculateTier(spawnLoc);
            log.info("[MobSpawn]   Zone等級: " + levelRange[0] + "~" + levelRange[1]
                    + " (Tier " + zoneTier + "), 基礎=" + baseLevel + " + 階級偏移=" + tierOffset
                    + " → 最終等級=" + mobLevel);
        }

        // ===== 根據等級篩選合適的怪物 =====
        // Boss 階級使用獨立的 Boss 怪物池
        List<String> candidateMobKeys;
        if (tier == MobTier.BOSS) {
            candidateMobKeys = mobManager.getBossMobKeys();
            if (candidateMobKeys.isEmpty()) {
                if (debug) log.info("[MobSpawn]   Boss 怪物池為空，跳過 Boss 生成");
                return false;
            }
        } else {
            candidateMobKeys = mobKeys;
        }

        // Peaceful 世界會讓敵對生物立刻消失，先過濾掉這些怪物
        if (spawnLoc.getWorld().getDifficulty() == Difficulty.PEACEFUL) {
            List<String> peacefulAllowed = new ArrayList<>();
            for (String key : candidateMobKeys) {
                if (!mobManager.willBeRemovedInPeaceful(key)) {
                    peacefulAllowed.add(key);
                }
            }

            if (debug && peacefulAllowed.size() != candidateMobKeys.size()) {
                log.info("[MobSpawn]   世界難度為 Peaceful，已排除會被原版立即移除的敵對怪物: "
                        + (candidateMobKeys.size() - peacefulAllowed.size()) + " 隻候選類型");
            }

            if (peacefulAllowed.isEmpty()) {
                lastSkipReason = "和平模式：敵對怪物會被原版立即移除";
                return false;
            }

            candidateMobKeys = peacefulAllowed;
        }

        // 檢查最近的zone是否有生態域標籤，如果有則過濾怪物
        List<String> filteredMobKeys = candidateMobKeys;
        ZoneManager.MobZone nearestZone = zoneManager.getNearestZone(spawnLoc);
        if (nearestZone != null && nearestZone.biomeTag != null) {
            String biomeTag = nearestZone.biomeTag.toLowerCase();
            filteredMobKeys = new ArrayList<>();
            for (String key : candidateMobKeys) {
                MobManager.MobData data = mobManager.getMobData(key);
                if (data == null) continue;
                List<String> mobTags = data.getTags();
                // 包含該生態域標籤的怪物，或沒有設定任何標籤的怪物（通用怪物）
                if (mobTags.isEmpty() || mobTags.contains(biomeTag)) {
                    filteredMobKeys.add(key);
                }
            }
            if (debug) {
                log.info("[MobSpawn]   生態域標籤: " + biomeTag + " → 過濾後可用怪物: " + filteredMobKeys.size() + "/" + candidateMobKeys.size());
            }
            // 如果過濾後沒有任何怪物，回退到候選池
            if (filteredMobKeys.isEmpty()) {
                if (debug) log.info("[MobSpawn]   生態域過濾後無怪物可用，回退到候選池");
                filteredMobKeys = candidateMobKeys;
            }
        }

        // ===== 日夜時段過濾 =====
        long worldTime = spawnLoc.getWorld().getTime(); // 0~24000
        boolean isNight = worldTime >= 13000 && worldTime < 23000;
        List<String> timeFilteredKeys = new ArrayList<>();
        for (String key : filteredMobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data == null) continue;
            String spawnTime = data.getSpawnTime();
            if (spawnTime.equals("all")) {
                timeFilteredKeys.add(key);
            } else if (spawnTime.equals("night") && isNight) {
                timeFilteredKeys.add(key);
            } else if (spawnTime.equals("day") && !isNight) {
                timeFilteredKeys.add(key);
            }
        }
        if (debug && timeFilteredKeys.size() != filteredMobKeys.size()) {
            log.info("[MobSpawn]   日夜過濾: " + (isNight ? "夜晚" : "白天") + " → " + timeFilteredKeys.size() + "/" + filteredMobKeys.size());
        }
        if (timeFilteredKeys.isEmpty()) {
            if (debug) log.info("[MobSpawn]   日夜過濾後無怪物可用，回退");
            timeFilteredKeys = filteredMobKeys;
        }
        filteredMobKeys = timeFilteredKeys;

        String mobKey = selectMobTypeForLevel(filteredMobKeys, mobLevel);

        if (mobKey == null) {
            if (debug) log.info("[MobSpawn]   找不到符合等級 " + mobLevel + " 的怪物類型");
            return false;
        }

        if (debug) {
            log.info("[MobSpawn]   生成: " + mobKey + " [" + tier.getDisplayName() + "] Lv." + mobLevel
                    + " 在 (" + spawnLoc.getBlockX() + ", " + spawnLoc.getBlockY() + ", " + spawnLoc.getBlockZ() + ")");
        }

        boolean success = spawnTieredMob(mobKey, spawnLoc, mobLevel, tier);
        if (success) {
            totalSpawnSuccess++;
            // BOSS 成功生成 → 重置 pity、設定冷卻
            if (tier == MobTier.BOSS) {
                UUID pid = player.getUniqueId();
                playerPityChance.put(pid, bossBaseChance);
                playerBossCooldown.put(pid, System.currentTimeMillis() + (bossCooldownSeconds * 1000L));
                if (debug) log.info("[MobSpawn]   ★ BOSS 已生成！pity 重置為 " + String.format("%.2f%%", bossBaseChance * 100)
                        + "，冷卻 " + bossCooldownSeconds + " 秒");
            }
        }
        return success;
    }

    /**
     * 計算階級等級偏移
     */
    private int calculateTierLevelOffset(MobTier tier) {
        return switch (tier) {
            case ELITE -> ThreadLocalRandom.current().nextInt(eliteLevelOffsetMin, eliteLevelOffsetMax + 1);
            case BOSS -> ThreadLocalRandom.current().nextInt(bossLevelOffsetMin, bossLevelOffsetMax + 1);
            default -> ThreadLocalRandom.current().nextInt(normalLevelOffsetMin, normalLevelOffsetMax + 1);
        };
    }

    /**
     * 決定怪物階級 (含累積機率系統)
     */
    private MobTier determineTier(Player player) {
        UUID pid = player.getUniqueId();

        // === BOSS 擲骰 (pity system) ===
        long now = System.currentTimeMillis();
        Long cooldownEnd = playerBossCooldown.get(pid);
        boolean bossOnCooldown = (cooldownEnd != null && now < cooldownEnd);

        if (!bossOnCooldown) {
            double currentPity = playerPityChance.getOrDefault(pid, bossBaseChance);
            double roll = random.nextDouble();

            if (debug) {
                log.info("[MobSpawn]   BOSS擲骰: roll=" + String.format("%.4f", roll)
                        + " 需要 < " + String.format("%.4f", currentPity)
                        + " (" + String.format("%.2f%%", currentPity * 100) + ")");
            }

            if (roll < currentPity) {
                return MobTier.BOSS;
            } else {
                double newPity = currentPity + bossPityIncrement;
                playerPityChance.put(pid, newPity);
                if (debug) {
                    log.info("[MobSpawn]   BOSS未命中，pity 累積: "
                            + String.format("%.2f%%", currentPity * 100) + " → "
                            + String.format("%.2f%%", newPity * 100));
                }
            }
        } else if (debug) {
            long remainSec = (cooldownEnd - now) / 1000;
            log.info("[MobSpawn]   BOSS 冷卻中 (剩餘 " + remainSec + " 秒)");
        }

        // === 精英 / 普通 擲骰 ===
        // 高 tier 區域提升精英機率
        double adjustedEliteChance = eliteChance;
        ZoneManager zoneManager = plugin.getZoneManager();
        if (zoneManager != null && zoneManager.getZoneCount() > 0) {
            int zoneTier = zoneManager.calculateTier(player.getLocation());
            // 每個 tier 增加 5% 精英機率
            adjustedEliteChance = Math.min(0.80, eliteChance + (zoneTier - 1) * 0.05);
        }

        double roll = random.nextDouble();
        if (roll < adjustedEliteChance) {
            return MobTier.ELITE;
        }
        return MobTier.NORMAL;
    }

    /**
     * 尋找普通怪 / 精英怪的生成位置
     */
    private Location findSpawnLocation(Player player) {
        return findSpawnLocationInRadius(player, spawnRadiusMin, spawnRadiusMax);
    }

    /**
     * 尋找 BOSS 的生成位置 (更遠)
     */
    private Location findBossSpawnLocation(Player player) {
        return findSpawnLocationInRadius(player, bossSpawnRadiusMin, bossSpawnRadiusMax);
    }

    /**
     * 在指定半徑範圍內尋找有效生成位置
     */
    private Location findSpawnLocationInRadius(Player player, int radiusMin, int radiusMax) {
        Location playerLoc = player.getLocation();
        World world = player.getWorld();

        for (int attempt = 0; attempt < 5; attempt++) {
            double angle = random.nextDouble() * Math.PI * 2;
            double distance = radiusMin + random.nextDouble() * (radiusMax - radiusMin);

            double x = playerLoc.getX() + Math.cos(angle) * distance;
            double z = playerLoc.getZ() + Math.sin(angle) * distance;

            // 確保 chunk 已載入
            int chunkX = (int) x >> 4;
            int chunkZ = (int) z >> 4;
            if (!world.isChunkLoaded(chunkX, chunkZ)) {
                continue;
            }

            int highestY = world.getHighestBlockYAt((int) x, (int) z);
            if (highestY < world.getMinHeight() + 1) {
                continue;
            }

            Location candidate = new Location(world, x + 0.5, highestY + 1, z + 0.5);

            if (!isValidSpawnLocation(candidate)) {
                continue;
            }

            // 檢查是否在 Zone 安全區內
            ZoneManager zoneManager = plugin.getZoneManager();
            if (zoneManager != null && zoneManager.isInsideAnyZone(candidate)) {
                if (debug) log.info("[MobSpawn]   候選位置在怪物安全區域內，跳過");
                continue;
            }

            // 檢查是否在保護區域內
            ProtectionAreaManager pam = plugin.getProtectionAreaManager();
            if (pam != null && pam.isInProtectedArea2D(candidate)) {
                if (debug) log.info("[MobSpawn]   候選位置在保護區域內，跳過");
                continue;
            }

            if (maxLightLevel < 15) {
                Block block = candidate.getBlock();
                if (block.getLightLevel() > maxLightLevel) {
                    continue;
                }
            }

            return candidate;
        }

        return null;
    }

    private boolean isValidSpawnLocation(Location location) {
        Block feetBlock = location.getBlock();
        Block groundBlock = feetBlock.getRelative(BlockFace.DOWN);
        Block headBlock = feetBlock.getRelative(BlockFace.UP);

        if (requireSolidGround && !groundBlock.getType().isSolid()) {
            return false;
        }

        if (requireAirSpace) {
            if (!feetBlock.getType().isAir() || !headBlock.getType().isAir()) {
                return false;
            }
        }

        if (groundBlock.isLiquid() || feetBlock.isLiquid()) {
            return false;
        }

        return true;
    }

    /**
     * 舊版等級計算 (當沒有 zone 時使用)
     */
    private int calculateLevelLegacy(int playerLevel, MobTier tier, Location playerLocation) {
        int levelOffset = calculateTierLevelOffset(tier);
        int level = playerLevel + levelOffset;
        return Math.max(1, level);
    }

    private String selectMobType(List<String> mobKeys) {
        return mobKeys.get(random.nextInt(mobKeys.size()));
    }

    /**
     * 根據等級篩選合適的怪物類型
     * 只選擇其 level-range 包含（或接近）指定等級的怪物
     *
     * @param mobKeys 所有可用的怪物 key
     * @param level   目標等級
     * @return 選中的 mob key，或 null（沒有符合的）
     */
    private String selectMobTypeForLevel(List<String> mobKeys, int level) {
        // 第一輪：嚴格匹配 — 怪物的 level-range 包含目標等級
        List<String> exactMatches = new ArrayList<>();
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data == null) continue;
            if (level >= data.getMinLevel() && level <= data.getMaxLevel()) {
                exactMatches.add(key);
            }
        }
        if (!exactMatches.isEmpty()) {
            return exactMatches.get(random.nextInt(exactMatches.size()));
        }

        // 第二輪：寬鬆匹配 — 允許 ±5 等級的容差
        List<String> nearMatches = new ArrayList<>();
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data == null) continue;
            if (level >= data.getMinLevel() - 5 && level <= data.getMaxLevel() + 5) {
                nearMatches.add(key);
            }
        }
        if (!nearMatches.isEmpty()) {
            return nearMatches.get(random.nextInt(nearMatches.size()));
        }

        // 第三輪：找最接近的怪物
        String closest = null;
        int closestDist = Integer.MAX_VALUE;
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data == null) continue;
            int dist = Math.min(Math.abs(level - data.getMinLevel()), Math.abs(level - data.getMaxLevel()));
            if (dist < closestDist) {
                closestDist = dist;
                closest = key;
            }
        }
        return closest;
    }

    private boolean spawnTieredMob(String mobKey, Location location, int level, MobTier tier) {
        LivingEntity mob = mobManager.spawnCustomMobWithLevel(mobKey, location, level);
        if (mob == null) {
            if (debug) log.warning("[MobSpawn]   生成失敗: mobManager 回傳 null (key=" + mobKey + ")");
            return false;
        }

        mobManager.setMobTier(mob, tier.name());
        spawnedMobs.add(mob.getUniqueId());

        MobManager.MobData mobData = mobManager.getMobData(mobKey);

        // 群體生成（如草原狼 pack_passive）
        if (mobData != null && "pack_passive".equalsIgnoreCase(mobData.getSpecialBehavior())) {
            int packSize = 2 + random.nextInt(4); // 額外 2~5 隻（加上原本的 1 隻 = 3~6 隻）
            for (int i = 0; i < packSize; i++) {
                double ox = (random.nextDouble() - 0.5) * 4;
                double oz = (random.nextDouble() - 0.5) * 4;
                Location packLoc = location.clone().add(ox, 0, oz);
                packLoc.setY(packLoc.getWorld().getHighestBlockYAt(packLoc) + 1);
                LivingEntity packMob = mobManager.spawnCustomMobWithLevel(mobKey, packLoc, level);
                if (packMob != null) {
                    mobManager.setMobTier(packMob, tier.name());
                    spawnedMobs.add(packMob.getUniqueId());
                }
            }
        }

        switch (tier) {
            case ELITE:
                applyEliteModifiers(mob);
                break;
            case BOSS:
                applyBossModifiers(mob, location, level);
                break;
            default:
                if (!normalNamePrefix.isEmpty()) {
                    String currentName = mob.getCustomName();
                    if (currentName != null) {
                        mob.setCustomName(normalNamePrefix + currentName);
                    }
                }
                break;
        }
        return true;
    }

    private void applyEliteModifiers(LivingEntity mob) {
        if (eliteStatMultiplier != 1.0) {
            double newMaxHealth = mob.getMaxHealth() * eliteStatMultiplier;
            mob.setMaxHealth(newMaxHealth);
            mob.setHealth(newMaxHealth);
        }

        String currentName = mob.getCustomName();
        if (currentName != null) {
            mob.setCustomName(eliteNamePrefix + ChatColor.translateAlternateColorCodes('&', "&e[精英] ") + currentName);
        }

        mob.setGlowing(true);
    }

    private void applyBossModifiers(LivingEntity mob, Location location, int level) {
        if (bossStatMultiplier != 1.0) {
            double newMaxHealth = mob.getMaxHealth() * bossStatMultiplier;
            mob.setMaxHealth(newMaxHealth);
            mob.setHealth(newMaxHealth);
        }

        String currentName = mob.getCustomName();
        if (currentName != null) {
            mob.setCustomName(bossNamePrefix + currentName);
        }

        mob.setGlowing(true);

        try {
            Particle particle = Particle.valueOf(bossSpawnParticle);
            location.getWorld().spawnParticle(particle, location.clone().add(0, 1, 0),
                    bossParticleCount, 1.5, 1.5, 1.5, 0.1);
        } catch (IllegalArgumentException e) {
            location.getWorld().spawnParticle(Particle.FLAME, location.clone().add(0, 1, 0),
                    bossParticleCount, 1.5, 1.5, 1.5, 0.1);
        }

        location.getWorld().spawnParticle(Particle.SOUL_FIRE_FLAME, location.clone().add(0, 1, 0),
                50, 2.0, 2.0, 2.0, 0.05);

        try {
            Sound sound = Registry.SOUNDS.get(NamespacedKey.minecraft(bossSpawnSound.toLowerCase()));
            if (sound != null) {
                location.getWorld().playSound(location, sound, bossSoundVolume, bossSoundPitch);
            } else {
                location.getWorld().playSound(location, Sound.ENTITY_ENDER_DRAGON_GROWL, 2.0f, 0.5f);
            }
        } catch (Exception e) {
            location.getWorld().playSound(location, Sound.ENTITY_ENDER_DRAGON_GROWL, 2.0f, 0.5f);
        }

        announceBossSpawn(mob, location, level);

        // 為 Boss 創建 BossBar
        BossBarManager bossBarMgr = plugin.getBossBarManager();
        if (bossBarMgr != null) {
            bossBarMgr.createBossBossBar(mob, level);
        }
    }

    private void announceBossSpawn(LivingEntity mob, Location location, int level) {
        String mobName = mob.getCustomName() != null ? mob.getCustomName() : "未知BOSS";
        int bx = location.getBlockX();
        int by = location.getBlockY();
        int bz = location.getBlockZ();

        String coordStr = ChatColor.AQUA + "(" + bx + ", " + by + ", " + bz + ")";

        // 顯示 Zone Tier 資訊
        String tierInfo = "";
        ZoneManager zoneManager = plugin.getZoneManager();
        if (zoneManager != null && zoneManager.getZoneCount() > 0) {
            int zoneTier = zoneManager.calculateTier(location);
            tierInfo = ChatColor.GRAY + " [" + zoneManager.getTierDisplayName(zoneTier) + ChatColor.GRAY + "]";
        }

        String message = ChatColor.RED + "" + ChatColor.BOLD + "⚠ "
                + ChatColor.DARK_RED + "" + ChatColor.BOLD + "【BOSS出現】\n"
                + ChatColor.RED + mobName + ChatColor.GRAY + " (Lv." + level + ")" + tierInfo + "\n"
                + ChatColor.YELLOW + "座標: " + coordStr + "\n"
                + ChatColor.GOLD + "快去討伐吧！";

        double notifyRadius = bossSpawnRadiusMax * 3.0;

        for (Player player : location.getWorld().getPlayers()) {
            if (player.getLocation().distance(location) <= notifyRadius) {
                player.sendMessage("");
                player.sendMessage(ChatColor.GOLD + "════════════════════════════════");
                player.sendMessage(message);
                player.sendMessage(ChatColor.GOLD + "════════════════════════════════");
                player.sendMessage("");
                player.sendTitle(
                        ChatColor.RED + "⚠ BOSS 出現 ⚠",
                        ChatColor.GOLD + mobName + ChatColor.GRAY + " Lv." + level + "  " + coordStr,
                        10, 80, 20
                );
            }
        }
    }

    // ==========================================
    // ===== 測試 / 指令用公開方法 =====
    // ==========================================

    /**
     * 強制在玩家附近生成一隻指定類型的怪物 (用於測試)
     */
    public String forceSpawn(Player player, String mobKey, MobTier tier) {
        List<String> mobKeys = new ArrayList<>(mobManager.getMobKeys());
        if (player.getWorld().getDifficulty() == Difficulty.PEACEFUL) {
            mobKeys.removeIf(mobManager::willBeRemovedInPeaceful);
        }

        if (mobKeys.isEmpty()) {
            if (player.getWorld().getDifficulty() == Difficulty.PEACEFUL) {
                return ChatColor.RED + "目前世界難度是 Peaceful，敵對自訂怪會被 Minecraft 立刻移除。"
                        + "\n" + ChatColor.YELLOW + "請先把世界難度改成 easy / normal / hard。";
            }
            return ChatColor.RED + "沒有已註冊的怪物類型！";
        }

        if (mobKey == null || mobKey.isEmpty()) {
            mobKey = selectMobType(mobKeys);
        } else if (mobManager.getMobData(mobKey) == null) {
            return ChatColor.RED + "未知的怪物類型: " + mobKey + "\n"
                    + ChatColor.YELLOW + "可用類型: " + String.join(", ", mobKeys);
        } else if (player.getWorld().getDifficulty() == Difficulty.PEACEFUL && mobManager.willBeRemovedInPeaceful(mobKey)) {
            EntityType actualType = mobManager.getActualSpawnEntityType(mobKey);
            return ChatColor.RED + "此怪物在 Peaceful 世界中會被 Minecraft 立刻移除：" + mobKey
                    + ChatColor.GRAY + " (實際實體類型: " + (actualType != null ? actualType.name() : "unknown") + ")"
                    + "\n" + ChatColor.YELLOW + "請先把世界難度改成 easy / normal / hard。";
        }

        Location desiredLoc = player.getLocation().clone().add(player.getLocation().getDirection().multiply(8));
        Location spawnLoc = mobManager.findSafeSpawnLocation(desiredLoc);
        if (spawnLoc == null) {
            return ChatColor.RED + "找不到安全的生成位置，請到較空曠的位置再試一次。";
        }

        // Zone-based level
        int mobLevel;
        ZoneManager zoneManager = plugin.getZoneManager();
        if (zoneManager != null && zoneManager.getZoneCount() > 0) {
            int[] levelRange = zoneManager.calculateMobLevelRange(spawnLoc);
            int baseLevel = levelRange[0] + random.nextInt(Math.max(1, levelRange[1] - levelRange[0] + 1));
            int tierOffset = calculateTierLevelOffset(tier);
            mobLevel = Math.max(1, baseLevel + tierOffset);
        } else {
            PlayerStats stats = statsManager.getStats(player);
            int playerLevel = stats.getLevel();
            mobLevel = calculateLevelLegacy(playerLevel, tier, player.getLocation());
        }

        boolean success = spawnTieredMob(mobKey, spawnLoc, mobLevel, tier);
        if (success) {
            return ChatColor.GREEN + "✓ 成功生成 " + tier.getColor() + "[" + tier.getDisplayName() + "] "
                    + ChatColor.WHITE + mobKey + " Lv." + mobLevel
                    + ChatColor.GRAY + " 在 (" + spawnLoc.getBlockX() + ", " + spawnLoc.getBlockY() + ", " + spawnLoc.getBlockZ() + ")";
        } else {
            return ChatColor.RED + "✗ 生成失敗: " + mobKey;
        }
    }

    /**
     * 取得診斷資訊 (用於 /mobspawn status)
     */
    public List<String> getDebugStatus(Player player) {
        List<String> lines = new ArrayList<>();
        lines.add(ChatColor.GOLD + "========= MobSpawnManager 診斷 =========");
        lines.add(ChatColor.YELLOW + "系統狀態: " + (enabled ? ChatColor.GREEN + "啟用" : ChatColor.RED + "停用"));
        lines.add(ChatColor.YELLOW + "生成任務: " + (spawnTask != null && !spawnTask.isCancelled() ? ChatColor.GREEN + "運行中" : ChatColor.RED + "未運行"));
        lines.add(ChatColor.YELLOW + "間隔: " + ChatColor.WHITE + intervalTicks + " ticks (" + (intervalTicks / 20.0) + "秒)");
        lines.add(ChatColor.YELLOW + "每次生成: " + ChatColor.WHITE + spawnsPerCycle + " 隻");
        lines.add("");

        // 怪物類型
        List<String> mobKeys = mobManager.getMobKeys();
        List<String> bossMobKeys = mobManager.getBossMobKeys();
        List<String> normalMobKeys = mobManager.getNormalMobKeys();
        lines.add(ChatColor.YELLOW + "已註冊怪物類型: " + ChatColor.WHITE + mobKeys.size()
                + ChatColor.GRAY + " (普通: " + normalMobKeys.size() + ", Boss: " + bossMobKeys.size() + ")");
        if (mobKeys.size() <= 20) {
            lines.add(ChatColor.GRAY + "  " + String.join(", ", mobKeys));
        }
        if (!bossMobKeys.isEmpty()) {
            lines.add(ChatColor.RED + "  Boss: " + String.join(", ", bossMobKeys));
        }
        lines.add("");

        // Zone 資訊
        ZoneManager zoneManager = plugin.getZoneManager();
        if (zoneManager != null) {
            lines.add(ChatColor.AQUA + "--- Zone-Based 系統 ---");
            lines.add(ChatColor.YELLOW + "怪物區域數量: " + ChatColor.WHITE + zoneManager.getZoneCount());
            if (zoneManager.getZoneCount() == 0) {
                lines.add(ChatColor.RED + "  尚未設定任何怪物區域，自然生成不會啟動。請先使用 /setmob 建立 zone。");
            }
            for (var zone : zoneManager.getAllZones()) {
                lines.add(ChatColor.GRAY + "  " + zone.name + ": Lv." + zone.minLevel + "~" + zone.maxLevel
                        + " (步進: " + zone.radiusStep + "格)");
            }
            lines.add("");
        }

        // 玩家資訊
        if (player != null) {
            lines.add(ChatColor.AQUA + "--- 你的狀態 ---");
            lines.add(ChatColor.YELLOW + "遊戲模式: " + ChatColor.WHITE + player.getGameMode().name());
            lines.add(ChatColor.YELLOW + "世界: " + ChatColor.WHITE + player.getWorld().getName()
                    + (disabledWorlds.contains(player.getWorld().getName()) ? ChatColor.RED + " (已禁用)" : ChatColor.GREEN + " (允許)"));
            lines.add(ChatColor.YELLOW + "世界難度: " + ChatColor.WHITE + player.getWorld().getDifficulty().name()
                    + (player.getWorld().getDifficulty() == Difficulty.PEACEFUL
                    ? ChatColor.RED + " (敵對自訂怪會被原版立即移除)"
                    : ChatColor.GREEN + " (允許敵對怪)"));

            // Zone-based 狀態
            if (zoneManager != null && zoneManager.getZoneCount() > 0) {
                boolean inZone = zoneManager.isInsideAnyZone(player.getLocation());
                lines.add(ChatColor.YELLOW + "安全區域: " + (inZone ? ChatColor.GREEN + "✓ 在安全區內" : ChatColor.RED + "✗ 在野外"));

                int zoneTier = zoneManager.calculateTier(player.getLocation());
                lines.add(ChatColor.YELLOW + "Zone Tier: " + zoneManager.getTierDisplayName(zoneTier));

                int[] levelRange = zoneManager.calculateMobLevelRange(player.getLocation());
                lines.add(ChatColor.YELLOW + "怪物等級: " + ChatColor.WHITE + "Lv." + levelRange[0] + " ~ Lv." + levelRange[1]);

                double dist = zoneManager.getDistanceToNearestZoneBorder(player.getLocation());
                if (dist >= 0) {
                    lines.add(ChatColor.YELLOW + "距最近安全區: " + ChatColor.WHITE + String.format("%.1f", dist) + " 格");
                }
            }

            int nearbyCount = countNearbyCustomMobs(player);
            lines.add(ChatColor.YELLOW + "附近自訂怪物: " + ChatColor.WHITE + nearbyCount + "/" + maxMobsPerPlayer
                    + (nearbyCount >= maxMobsPerPlayer ? ChatColor.RED + " (已達上限!)" : ChatColor.GREEN + " (未滿 ✓)"));

            PlayerStats stats = statsManager.getStats(player);
            lines.add(ChatColor.YELLOW + "玩家等級: " + ChatColor.WHITE + stats.getLevel());

            if (nightOnly) {
                long time = player.getWorld().getTime();
                lines.add(ChatColor.YELLOW + "時間: " + ChatColor.WHITE + time
                        + ((time < 13000 || time > 23000) ? ChatColor.RED + " (白天，不生成)" : ChatColor.GREEN + " (夜晚 ✓)"));
            }

            // BOSS pity 系統資訊
            lines.add("");
            lines.add(ChatColor.LIGHT_PURPLE + "--- BOSS 累積機率系統 ---");
            UUID pid = player.getUniqueId();
            double currentPity = playerPityChance.getOrDefault(pid, bossBaseChance);
            lines.add(ChatColor.YELLOW + "基礎機率: " + ChatColor.WHITE + String.format("%.2f%%", bossBaseChance * 100));
            lines.add(ChatColor.YELLOW + "每次累積: " + ChatColor.WHITE + "+" + String.format("%.2f%%", bossPityIncrement * 100));
            lines.add(ChatColor.YELLOW + "當前機率: " + ChatColor.GREEN + String.format("%.2f%%", currentPity * 100));

            Long cooldownEnd = playerBossCooldown.get(pid);
            if (cooldownEnd != null && System.currentTimeMillis() < cooldownEnd) {
                long remainSec = (cooldownEnd - System.currentTimeMillis()) / 1000;
                long min = remainSec / 60;
                long sec = remainSec % 60;
                lines.add(ChatColor.YELLOW + "BOSS冷卻: " + ChatColor.RED + min + "分" + sec + "秒");
            } else {
                lines.add(ChatColor.YELLOW + "BOSS冷卻: " + ChatColor.GREEN + "就緒 ✓");
            }
            lines.add(ChatColor.YELLOW + "BOSS生成範圍: " + ChatColor.WHITE + bossSpawnRadiusMin + "~" + bossSpawnRadiusMax + " 格");
        }
        lines.add("");

        // 統計
        lines.add(ChatColor.AQUA + "--- 生成統計 ---");
        lines.add(ChatColor.YELLOW + "總嘗試: " + ChatColor.WHITE + totalSpawnAttempts);
        lines.add(ChatColor.YELLOW + "總成功: " + ChatColor.GREEN + totalSpawnSuccess);
        lines.add(ChatColor.YELLOW + "位置失敗: " + ChatColor.RED + totalLocationFails);
        lines.add(ChatColor.YELLOW + "追蹤中怪物: " + ChatColor.WHITE + getSpawnedMobCount());
        lines.add(ChatColor.YELLOW + "最後跳過原因: " + ChatColor.WHITE + lastSkipReason);
        lines.add(ChatColor.GOLD + "==========================================");

        return lines;
    }

    /**
     * 清除所有已追蹤的怪物
     */
    public int clearAllSpawnedMobs() {
        int removed = 0;
        for (UUID uuid : spawnedMobs) {
            Entity entity = plugin.getServer().getEntity(uuid);
            if (entity != null && !entity.isDead()) {
                entity.remove();
                removed++;
            }
        }
        spawnedMobs.clear();
        return removed;
    }

    /**
     * 切換 debug 模式
     */
    public boolean toggleDebug() {
        debug = !debug;
        return debug;
    }

    public void reload() {
        if (spawnTask != null) {
            spawnTask.cancel();
            spawnTask = null;
        }
        loadConfig();
        if (enabled) {
            startSpawnTask();
        } else {
            log.info("[MobSpawnManager] 配置已重新載入，生成系統已停用");
        }
    }

    public void shutdown() {
        if (spawnTask != null) {
            spawnTask.cancel();
            spawnTask = null;
        }
        int removed = clearAllSpawnedMobs();
    }

    public int getSpawnedMobCount() {
        spawnedMobs.removeIf(uuid -> {
            Entity entity = plugin.getServer().getEntity(uuid);
            return entity == null || entity.isDead();
        });
        return spawnedMobs.size();
    }

    public boolean isEnabled() {
        return enabled;
    }
}

package com.customrpg.managers;

import com.customrpg.CustomRPG;
import org.bukkit.Location;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;

import java.io.File;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * SafeZoneManager - 管理圓形安全區域
 */
public class SafeZoneManager {

    private final CustomRPG plugin;
    private final File configFile;
    private final Map<String, SafeZone> safeZones = new LinkedHashMap<>();

    public SafeZoneManager(CustomRPG plugin) {
        this.plugin = plugin;
        this.configFile = new File(plugin.getDataFolder(), "config/safe_zones.yml");
        load();
    }

    public void reload() {
        load();
    }

    private void load() {
        safeZones.clear();

        if (!configFile.exists()) {
            plugin.saveResource("config/safe_zones.yml", false);
        }

        FileConfiguration config = YamlConfiguration.loadConfiguration(configFile);
        ConfigurationSection zonesSection = config.getConfigurationSection("zones");
        if (zonesSection == null) {
            plugin.getLogger().warning("[SafeZoneManager] No zones section found in config/safe_zones.yml");
            return;
        }

        for (String id : zonesSection.getKeys(false)) {
            ConfigurationSection section = zonesSection.getConfigurationSection(id);
            if (section == null) {
                continue;
            }

            String world = section.getString("world", "world");
            String name = section.getString("name", id);
            String type = section.getString("type", "SAFE_ZONE");
            double x = section.getDouble("center.x");
            double y = section.getDouble("center.y");
            double z = section.getDouble("center.z");
            double radius = Math.max(1.0, section.getDouble("radius", 200.0));

            safeZones.put(id.toLowerCase(), new SafeZone(id, name, type, world, x, y, z, radius));
        }

        plugin.getLogger().info("[SafeZoneManager] Loaded " + safeZones.size() + " safe zones");
    }

    public boolean isInSafeZone(Location location) {
        return getZoneAt(location) != null;
    }

    public SafeZone getZoneAt(Location location) {
        if (location == null || location.getWorld() == null) {
            return null;
        }

        String worldName = location.getWorld().getName();
        for (SafeZone zone : safeZones.values()) {
            if (zone.contains(worldName, location.getX(), location.getY(), location.getZ())) {
                return zone;
            }
        }
        return null;
    }

    public int getZoneCount() {
        return safeZones.size();
    }

    public Collection<SafeZone> getZones() {
        return new ArrayList<>(safeZones.values());
    }

    public static class SafeZone {
        private final String id;
        private final String name;
        private final String type;
        private final String world;
        private final double x;
        private final double y;
        private final double z;
        private final double radius;
        private final double radiusSquared;

        public SafeZone(String id, String name, String type, String world,
                        double x, double y, double z, double radius) {
            this.id = id;
            this.name = name;
            this.type = type;
            this.world = world;
            this.x = x;
            this.y = y;
            this.z = z;
            this.radius = radius;
            this.radiusSquared = radius * radius;
        }

        public boolean contains(String worldName, double targetX, double targetY, double targetZ) {
            if (!world.equalsIgnoreCase(worldName)) {
                return false;
            }
            double dx = targetX - x;
            double dy = targetY - y;
            double dz = targetZ - z;
            return (dx * dx) + (dy * dy) + (dz * dz) <= radiusSquared;
        }

        public String getId() {
            return id;
        }

        public String getName() {
            return name;
        }

        public String getType() {
            return type;
        }

        public String getWorld() {
            return world;
        }

        public double getX() {
            return x;
        }

        public double getY() {
            return y;
        }

        public double getZ() {
            return z;
        }

        public double getRadius() {
            return radius;
        }
    }
}

